import { GoogleGenAI, Type } from "@google/genai";
import { AiEstimation } from "../types";

export const estimateMissionDetails = async (
  description: string,
  serviceType: string
): Promise<AiEstimation | null> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Tu es un expert en services à domicile en Côte d'Ivoire (Ménage, Bricolage, Cuisine, etc.). 
      Analyse cette demande d'un client :
      Type de service : ${serviceType}
      Description utilisateur : "${description}"

      Instructions :
      1. Estime la durée nécessaire en heures (nombre).
      2. Suggère un prix total juste en FCFA (basé sur un tarif de 2500 à 5000 FCFA/h selon la difficulté).
      3. Reformule la description pour qu'elle soit professionnelle, claire et structurée pour le prestataire.

      Réponds UNIQUEMENT au format JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            estimatedDuration: { 
              type: Type.NUMBER,
              description: "Durée estimée en heures"
            },
            suggestedPrice: { 
              type: Type.NUMBER,
              description: "Prix suggéré en FCFA"
            },
            descriptionImprovement: { 
              type: Type.STRING,
              description: "Description reformulée professionnellement"
            },
          },
          required: ["estimatedDuration", "suggestedPrice", "descriptionImprovement"],
        },
      },
    });

    const text = response.text;
    if (!text) return null;
    return JSON.parse(text) as AiEstimation;
  } catch (error) {
    console.error("Gemini AI Estimation Error:", error);
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, MarketItem, AiEstimation } from '../types';
import { SERVICE_ICONS, CITIES, BASE_RATES, MARKET_PACKAGING_FEE, MARKET_SERVICE_FEE, MARKET_DELIVERY_FEE, LAUNDRY_MIN_PRICE, LAUNDRY_EXTRA_PRICE, LAUNDRY_MIN_QTY } from '../constants';
import { MapPin, Calendar, Clock, Send, Loader2, Star, AlertTriangle, CheckCircle, Crosshair, Plus, Trash2, ShoppingBag, DollarSign, User as UserIcon, Save, History, PlusCircle, Map as MapIcon, Menu, Timer, ChevronDown, Shirt, ThumbsUp, Sparkles, Wand2, X, ChevronUp } from 'lucide-react';
import { estimateMissionDetails } from '../services/geminiService';

interface ClientDashboardProps {
  currentUser: User;
  missions: Mission[];
  onAddMission: (newMission: Mission, paymentMethod: string) => Promise<void>;
  onValidateMission: (missionId: string) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateMission: (missionId: string, rating: number, comment: string) => void;
  baseRates: Record<ServiceCategory, number>;
  commissionRate: number;
  onUpdateUser: (data: Partial<User>) => void;
}

const CATEGORY_STYLES: Record<ServiceCategory, { active: string; inactive: string }> = {
  [ServiceCategory.CLEANING]: { active: "bg-sky-600 border-sky-700 text-white shadow-lg scale-105 ring-2 ring-sky-300", inactive: "bg-white border-sky-100 text-sky-700 hover:bg-sky-50" },
  [ServiceCategory.COOKING]: { active: "bg-orange-600 border-orange-700 text-white shadow-lg scale-105 ring-2 ring-orange-300", inactive: "bg-white border-orange-100 text-orange-700 hover:bg-orange-50" },
  [ServiceCategory.ELDERLY_CARE]: { active: "bg-emerald-600 border-emerald-700 text-white shadow-lg scale-105 ring-2 ring-emerald-300", inactive: "bg-white border-emerald-100 text-emerald-700 hover:bg-emerald-50" },
  [ServiceCategory.GARDENING]: { active: "bg-green-600 border-green-700 text-white shadow-lg scale-105 ring-2 ring-green-300", inactive: "bg-white border-green-100 text-green-700 hover:bg-green-50" },
  [ServiceCategory.LAUNDRY]: { active: "bg-indigo-600 border-indigo-700 text-white shadow-lg scale-105 ring-2 ring-indigo-300", inactive: "bg-white border-indigo-100 text-indigo-700 hover:bg-indigo-50" },
  [ServiceCategory.BABYSITTING]: { active: "bg-pink-600 border-pink-700 text-white shadow-lg scale-105 ring-2 ring-pink-300", inactive: "bg-white border-pink-100 text-pink-700 hover:bg-pink-50" },
  [ServiceCategory.MARKET]: { active: "bg-amber-600 border-amber-700 text-white shadow-lg scale-105 ring-2 ring-amber-300", inactive: "bg-white border-amber-100 text-orange-700 hover:bg-amber-50" },
  [ServiceCategory.HANDYMAN]: { active: "bg-violet-600 border-violet-700 text-white shadow-lg scale-105 ring-2 ring-violet-300", inactive: "bg-white border-violet-100 text-violet-700 hover:bg-violet-50" },
};

export default function ClientDashboard({
  currentUser,
  missions,
  onAddMission,
  onValidateMission,
  onDisputeMission,
  onRateMission,
  baseRates,
  commissionRate,
  onUpdateUser
}: ClientDashboardProps) {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'profile'>('new');

  const [selectedCategory, setSelectedCategory] = useState<ServiceCategory>(ServiceCategory.CLEANING);
  const [description, setDescription] = useState('');
  const [date, setDate] = useState('');
  const [time, setTime] = useState(''); 
  const [endTime, setEndTime] = useState(''); 
  const [duration, setDuration] = useState(2); 

  const [laundryQuantity, setLaundryQuantity] = useState<number>(20); 

  const [location, setLocation] = useState<string>(currentUser.address || '');
  const [debouncedLocation, setDebouncedLocation] = useState<string>(currentUser.address || '');
  const [city, setCity] = useState(currentUser.city || 'Abidjan');
  const [isLocating, setIsLocating] = useState(false);
  const [statusFilter, setStatusFilter] = useState<string>('TOUTES');

  const [marketItems, setMarketItems] = useState<MarketItem[]>([]);
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [deliveryWindow, setDeliveryWindow] = useState("");

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('Mobile Money');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);

  // IA State
  const [isEstimating, setIsEstimating] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiEstimation | null>(null);

  const [expandedMissionId, setExpandedMissionId] = useState<string | null>(null);
  const [showRatingModal, setShowRatingModal] = useState(false);
  const [ratingMissionId, setRatingMissionId] = useState<string | null>(null);
  const [ratingValue, setRatingValue] = useState(5);
  const [ratingComment, setRatingComment] = useState('');

  const [profileForm, setProfileForm] = useState({
      name: currentUser.name,
      phone: currentUser.phone,
      email: currentUser.email,
      address: currentUser.address || '',
      city: currentUser.city || 'Abidjan',
  });

  useEffect(() => {
    const handler = setTimeout(() => {
        setDebouncedLocation(location);
    }, 1500);
    return () => clearTimeout(handler);
  }, [location]);

  useEffect(() => {
    if (time && endTime && selectedCategory !== ServiceCategory.MARKET && selectedCategory !== ServiceCategory.LAUNDRY) {
      const [startH, startM] = time.split(':').map(Number);
      const [endH, endM] = endTime.split(':').map(Number);

      let diffHours = endH - startH;
      let diffMinutes = endM - startM;

      let totalHours = diffHours + (diffMinutes / 60);
      if (totalHours <= 0) totalHours = 1;

      setDuration(Math.round(totalHours * 10) / 10);
    }
  }, [time, endTime, selectedCategory]);

  const getDeliveryOptions = () => {
      const options = [];
      const now = new Date();
      const currentHour = now.getHours();
      if (currentHour < 11) options.push("Aujourd'hui avant 12h");
      if (currentHour < 13) options.push("Aujourd'hui avant 14h");
      if (currentHour < 17) options.push("Aujourd'hui avant 18h");
      options.push("Demain Matin (8h - 12h)");
      options.push("Demain Après-midi (14h - 18h)");
      return options;
  };

  useEffect(() => {
      const opts = getDeliveryOptions();
      if (opts.length > 0 && !deliveryWindow) setDeliveryWindow(opts[0]);
  }, []);

  const handleAiAssist = async () => {
      if (!description || description.length < 10) {
          alert("Veuillez donner un peu plus de détails pour que l'IA puisse vous aider.");
          return;
      }
      setIsEstimating(true);
      const result = await estimateMissionDetails(description, selectedCategory);
      if (result) {
          setAiSuggestion(result);
      } else {
          alert("L'assistant IA est momentanément indisponible.");
      }
      setIsEstimating(false);
  };

  const applyAiSuggestion = () => {
      if (!aiSuggestion) return;
      setDescription(aiSuggestion.descriptionImprovement);
      setDuration(aiSuggestion.estimatedDuration);
      // On ajuste l'heure de fin si possible
      if (time) {
          const [h, m] = time.split(':').map(Number);
          const endTotalMinutes = h * 60 + m + aiSuggestion.estimatedDuration * 60;
          const endH = Math.floor(endTotalMinutes / 60) % 24;
          const endM = Math.floor(endTotalMinutes % 60);
          setEndTime(`${endH.toString().padStart(2, '0')}:${endM.toString().padStart(2, '0')}`);
      }
      setAiSuggestion(null);
  };

  const getMissionPrice = () => {
      if (selectedCategory === ServiceCategory.MARKET) {
          const itemsTotal = marketItems.reduce((acc, item) => acc + item.price, 0);
          if (itemsTotal === 0) return 0;
          return itemsTotal + MARKET_PACKAGING_FEE + MARKET_SERVICE_FEE + MARKET_DELIVERY_FEE;
      }
      if (selectedCategory === ServiceCategory.LAUNDRY) {
          if (laundryQuantity <= LAUNDRY_MIN_QTY) return LAUNDRY_MIN_PRICE;
          const extraItems = laundryQuantity - LAUNDRY_MIN_QTY;
          return LAUNDRY_MIN_PRICE + (extraItems * LAUNDRY_EXTRA_PRICE);
      }
      const rate = baseRates[selectedCategory] || 2500;
      return Math.round(rate * duration);
  };

  const totalPrice = getMissionPrice();

  const myMissions = missions
    .filter(m => m.clientId === currentUser.id)
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
    .filter(m => {
      if (statusFilter === 'TOUTES') return true;
      if (statusFilter === 'EN_ATTENTE') return m.status === MissionStatus.PENDING;
      if (statusFilter === 'EN_COURS') return [MissionStatus.ACCEPTED, MissionStatus.IN_PROGRESS, MissionStatus.PAYMENT_PENDING].includes(m.status);
      if (statusFilter === 'TERMINEE') return m.status === MissionStatus.COMPLETED;
      if (statusFilter === 'ANNULEE') return [MissionStatus.CANCELLED, MissionStatus.ARCHIVED, MissionStatus.DISPUTED].includes(m.status);
      return true;
  });

  const handleLocateMe = () => {
    if (!navigator.geolocation) return;
    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
        async (position) => {
            const { latitude, longitude } = position.coords;
            const latLng = `${latitude.toFixed(5)}, ${longitude.toFixed(5)}`;
            setLocation(latLng);
            try {
                const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
                const data = await response.json();
                if (data && data.address) {
                    const addr = [data.address.road, data.address.suburb].filter(Boolean).join(', ');
                    if (addr) setLocation(`${addr} (${latLng})`);
                    if (data.address.city) setCity(data.address.city);
                }
            } catch (e) {}
            setIsLocating(false);
        },
        () => setIsLocating(false)
    );
  };

  const handleAddItem = () => {
      const price = parseFloat(newItemPrice);
      if (!newItemName || isNaN(price) || price <= 0) return;
      setMarketItems([...marketItems, { name: newItemName, price }]);
      setNewItemName('');
      setNewItemPrice('');
  };

  const handleInitiateMission = (e: React.FormEvent) => {
      e.preventDefault();
      if (selectedCategory !== ServiceCategory.MARKET) {
          if (!date || !time) { alert("Détails temporels requis."); return; }
          if (selectedCategory !== ServiceCategory.LAUNDRY && !endTime) { alert("Heure de fin requise."); return; }
      }
      if (selectedCategory !== ServiceCategory.MARKET && !description) { alert("Description requise."); return; }
      if (selectedCategory === ServiceCategory.MARKET && marketItems.length === 0) { alert("Liste vide."); return; }
      setShowPaymentModal(true);
  };

  const confirmPayment = async () => {
      setIsProcessingPayment(true);
      const isoDate = `${date || new Date().toISOString().split('T')[0]}T${time || "08:00"}`;
      const isoEndTime = endTime ? `${date}T${endTime}` : undefined;
      const newMission: Mission = {
          id: `m${Date.now()}`,
          title: selectedCategory === ServiceCategory.MARKET ? 'Course au marché' : `${selectedCategory}`,
          clientId: currentUser.id, clientName: currentUser.name, category: selectedCategory,
          description: description || `Mission ${selectedCategory}`, location: location || "Non spécifié", city,
          date: isoDate, endTime: isoEndTime, durationHours: duration,
          quantity: selectedCategory === ServiceCategory.LAUNDRY ? laundryQuantity : undefined,
          totalPrice, commission: totalPrice * commissionRate, providerAmount: totalPrice * (1 - commissionRate),
          status: MissionStatus.PENDING, createdAt: new Date().toISOString(),
          marketItems: selectedCategory === ServiceCategory.MARKET ? marketItems : undefined,
          deliveryWindow: selectedCategory === ServiceCategory.MARKET ? deliveryWindow : undefined,
      };
      await onAddMission(newMission, paymentMethod);
      setActiveTab('history');
      setIsProcessingPayment(false);
      setShowPaymentModal(false);
  };

  const renderNewRequest = () => {
    const mapUrl = `https://maps.google.com/maps?q=${encodeURIComponent(debouncedLocation || city)}&t=k&z=17&ie=UTF8&iwloc=&output=embed`;
    const today = new Date().toISOString().split('T')[0];

    return (
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden animate-slide-up pb-20 md:pb-0">
          <div className="p-6 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
              <h2 className="text-xl font-bold text-gray-800 flex items-center"><PlusCircle className="mr-2 text-blue-600"/> Nouvelle Demande</h2>
          </div>

          <div className="p-6">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                  {Object.values(ServiceCategory).map((cat) => {
                      const Icon = SERVICE_ICONS[cat];
                      const isSelected = selectedCategory === cat;
                      return (
                          <button key={cat} onClick={() => { setSelectedCategory(cat); if (cat === ServiceCategory.LAUNDRY) setLaundryQuantity(20); }} className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all ${isSelected ? CATEGORY_STYLES[cat].active : CATEGORY_STYLES[cat].inactive}`}>
                              <div className={`p-3 rounded-full mb-2 ${isSelected ? 'bg-white/20' : 'bg-gray-100'}`}><Icon size={24} /></div>
                              <span className="text-[10px] uppercase font-black tracking-tighter text-center">{cat}</span>
                          </button>
                      );
                  })}
              </div>

              <form onSubmit={handleInitiateMission} className="space-y-6">
                  <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                        <label className="block text-xs font-black uppercase text-gray-400 mb-3 tracking-widest">Localisation</label>
                        <div className="relative flex items-center mb-4">
                            <input type="text" required value={location} onChange={(e) => setLocation(e.target.value)} className="w-full pl-10 pr-16 p-3 border border-gray-200 rounded-xl font-bold bg-white text-sm outline-none focus:border-blue-500" placeholder="Adresse ou repère..." />
                            <MapPin size={16} className="absolute left-3 text-blue-500" />
                            <button type="button" onClick={handleLocateMe} className="absolute right-1 px-3 py-1.5 bg-blue-600 text-white rounded-lg text-[10px] font-black uppercase">{isLocating ? '...' : 'GPS'}</button>
                        </div>
                        <div className="rounded-xl overflow-hidden shadow-inner h-40 border border-gray-200"><iframe width="100%" height="100%" frameBorder="0" src={mapUrl}></iframe></div>
                  </div>

                  {selectedCategory === ServiceCategory.MARKET ? (
                      <div className="bg-amber-50 p-6 rounded-2xl border border-amber-100 animate-fade-in">
                          <h3 className="font-black text-amber-800 mb-4 flex items-center text-sm uppercase tracking-widest"><ShoppingBag className="mr-2" size={18}/> Ma Liste de courses</h3>
                          <div className="flex gap-2 mb-4">
                              <input type="text" placeholder="Ex: Tomates" className="flex-grow p-3 rounded-xl border-amber-200 bg-white font-bold text-sm" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} />
                              <input type="number" placeholder="F" className="w-24 p-3 rounded-xl border-amber-200 bg-white font-bold text-sm" value={newItemPrice} onChange={(e) => setNewItemPrice(e.target.value)} />
                              <button type="button" onClick={handleAddItem} className="bg-amber-600 text-white p-3 rounded-xl shadow-md"><Plus size={20} /></button>
                          </div>
                          <div className="space-y-2 mb-4">
                              {marketItems.map((item, idx) => (
                                  <div key={idx} className="flex justify-between items-center bg-white p-3 rounded-xl shadow-sm">
                                      <span className="font-bold text-gray-700">{item.name}</span>
                                      <div className="flex items-center"><span className="font-black mr-3 text-amber-600">{item.price} F</span><button type="button" onClick={() => handleRemoveItem(idx)}><Trash2 size={14} className="text-red-400" /></button></div>
                                  </div>
                              ))}
                          </div>
                          <div className="grid grid-cols-2 gap-4">
                              <input type="date" min={today} value={date} onChange={(e) => setDate(e.target.value)} className="p-3 bg-white border border-amber-200 rounded-xl font-bold text-xs" />
                              <select value={deliveryWindow} onChange={(e) => setDeliveryWindow(e.target.value)} className="p-3 bg-white border border-amber-200 rounded-xl font-bold text-xs">
                                  {getDeliveryOptions().map(opt => <option key={opt} value={opt}>{opt}</option>)}
                              </select>
                          </div>
                      </div>
                  ) : (
                      <div className="space-y-6 animate-fade-in">
                          <div className="relative">
                              <label className="block text-xs font-black uppercase text-gray-400 mb-2 tracking-widest">Description du besoin</label>
                              <textarea required value={description} onChange={(e) => setDescription(e.target.value)} className="w-full p-4 border border-gray-200 rounded-2xl min-h-[100px] text-sm font-bold bg-white focus:border-blue-500 outline-none" placeholder="Décrivez votre demande en quelques mots..." />
                              <button type="button" onClick={handleAiAssist} disabled={isEstimating} className="absolute bottom-4 right-4 bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-black flex items-center shadow-lg hover:shadow-blue-200 transition-all transform active:scale-95 disabled:opacity-50">
                                  {isEstimating ? <Loader2 size={14} className="animate-spin mr-2"/> : <Wand2 size={14} className="mr-2"/>}
                                  Aide de l'IA
                              </button>
                          </div>

                          {aiSuggestion && (
                              <div className="bg-blue-50 border border-blue-100 p-5 rounded-2xl animate-fade-in">
                                  <div className="flex items-center justify-between mb-3">
                                      <span className="text-xs font-black text-blue-800 uppercase flex items-center"><Sparkles size={14} className="mr-2"/> Suggestion de l'assistant IA</span>
                                      <button onClick={() => setAiSuggestion(null)} className="text-blue-400 hover:text-blue-600"><X size={16}/></button>
                                  </div>
                                  <p className="text-xs text-blue-700 italic mb-4 leading-relaxed">"{aiSuggestion.descriptionImprovement}"</p>
                                  <div className="flex gap-4 mb-4">
                                      <div className="bg-white px-3 py-2 rounded-lg border border-blue-100 flex-1"><span className="block text-[10px] text-gray-400 font-bold uppercase">Durée</span><span className="font-black text-blue-900">{aiSuggestion.estimatedDuration}h</span></div>
                                      <div className="bg-white px-3 py-2 rounded-lg border border-blue-100 flex-1"><span className="block text-[10px] text-gray-400 font-bold uppercase">Budget</span><span className="font-black text-blue-900">{aiSuggestion.suggestedPrice.toLocaleString()} F</span></div>
                                  </div>
                                  <button type="button" onClick={applyAiSuggestion} className="w-full bg-blue-600 text-white py-2.5 rounded-xl font-black text-xs uppercase shadow-md shadow-blue-100">Appliquer les suggestions</button>
                              </div>
                          )}

                          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                              <input type="date" required min={today} value={date} onChange={(e) => setDate(e.target.value)} className="p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                              <input type="time" required value={time} onChange={(e) => setTime(e.target.value)} className="p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                              {selectedCategory !== ServiceCategory.LAUNDRY && <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />}
                              {selectedCategory === ServiceCategory.LAUNDRY && (
                                  <div className="bg-indigo-50 p-2 rounded-2xl flex items-center justify-center border border-indigo-100">
                                      <input type="number" min="20" value={laundryQuantity} onChange={(e) => setLaundryQuantity(Math.max(20, parseInt(e.target.value) || 20))} className="w-20 text-center bg-transparent font-black text-indigo-700 outline-none" />
                                      <span className="text-[10px] font-black uppercase text-indigo-400">Pièces</span>
                                  </div>
                              )}
                          </div>
                      </div>
                  )}

                  <div className="flex items-center justify-between pt-6 border-t border-gray-100">
                      <div><p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Estimé</p><p className="text-3xl font-black text-blue-950">{totalPrice.toLocaleString()} F</p></div>
                      <button type="submit" className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 flex items-center transition-all hover:scale-105 active:scale-95"><Send size={20} className="mr-2" /> Commander</button>
                  </div>
              </form>
          </div>
      </div>
    );
  };

  const renderHistory = () => (
      <div className="space-y-4 animate-slide-up relative h-full min-h-[50vh]">
          <div className="flex space-x-2 overflow-x-auto pb-2 sticky top-0 bg-gray-50 z-10 py-2">
              <button onClick={() => setStatusFilter('TOUTES')} className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest ${statusFilter === 'TOUTES' ? 'bg-blue-600 text-white' : 'bg-white text-gray-400 border border-gray-200'}`}>Toutes</button>
              <button onClick={() => setStatusFilter('EN_COURS')} className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest ${statusFilter === 'EN_COURS' ? 'bg-blue-600 text-white' : 'bg-white text-gray-400 border border-gray-200'}`}>En cours</button>
              <button onClick={() => setStatusFilter('TERMINEE')} className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest ${statusFilter === 'TERMINEE' ? 'bg-green-600 text-white' : 'bg-white text-gray-400 border border-gray-200'}`}>Terminées</button>
          </div>

          {myMissions.length === 0 ? (
              <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-gray-200"><History size={48} className="mx-auto text-gray-200 mb-4" /><p className="text-gray-400 font-bold">Aucune mission trouvée.</p></div>
          ) : (
              myMissions.map(mission => (
                  <div key={mission.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100 transition-all hover:shadow-md">
                      <div className="flex justify-between items-start mb-4">
                          <div className="flex items-center space-x-4">
                              <div className="p-3 bg-gray-50 rounded-2xl"><div className="text-blue-600">{React.createElement(SERVICE_ICONS[mission.category], {size: 24})}</div></div>
                              <div><h3 className="font-black text-blue-950 text-lg">{mission.title}</h3><p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{new Date(mission.date).toLocaleDateString()}</p></div>
                          </div>
                          <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${mission.status === MissionStatus.COMPLETED ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>{mission.status}</span>
                      </div>
                      <div className="bg-gray-50 p-4 rounded-2xl mb-4 text-xs font-medium text-gray-600 leading-relaxed italic">"{mission.description}"</div>
                      <div className="flex justify-end gap-2">
                          {mission.status === MissionStatus.COMPLETED && !mission.clientRating && (
                              <button onClick={() => { setRatingMissionId(mission.id); setShowRatingModal(true); }} className="bg-yellow-100 text-yellow-700 px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest flex items-center hover:bg-yellow-200 transition-colors"><Star size={14} className="mr-2" /> Noter</button>
                          )}
                          {(mission.status === MissionStatus.IN_PROGRESS || mission.status === MissionStatus.ACCEPTED) && (
                              <button onClick={() => onValidateMission(mission.id)} className="bg-green-600 text-white px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest flex items-center hover:bg-green-700 transition-colors shadow-lg shadow-green-100"><CheckCircle size={14} className="mr-2" /> Valider la fin</button>
                          )}
                      </div>
                  </div>
              ))
          )}
      </div>
  );

  return (
    <div className="space-y-6">
        {showRatingModal && (
            <div className="fixed inset-0 bg-blue-950/40 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm animate-scale-in shadow-2xl relative">
                    <button onClick={() => setShowRatingModal(false)} className="absolute top-6 right-6 text-gray-300 hover:text-gray-600"><X size={20}/></button>
                    <div className="text-center mb-8">
                        <div className="w-16 h-16 bg-yellow-100 rounded-2xl flex items-center justify-center mx-auto mb-4"><Star size={32} className="text-yellow-500" fill="currentColor"/></div>
                        <h3 className="text-2xl font-black text-blue-950">Avis Service</h3>
                        <p className="text-sm font-medium text-gray-500 mt-1">Comment évaluez-vous le travail ?</p>
                    </div>
                    <div className="flex justify-center space-x-2 mb-8">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button key={star} onClick={() => setRatingValue(star)} className={`transition-all hover:scale-125 ${star <= ratingValue ? 'text-yellow-400' : 'text-gray-100'}`}><Star size={32} fill="currentColor" /></button>
                        ))}
                    </div>
                    <textarea value={ratingComment} onChange={(e) => setRatingComment(e.target.value)} className="w-full border border-gray-100 rounded-2xl p-4 mb-8 focus:ring-2 focus:ring-yellow-400 outline-none text-sm font-bold bg-gray-50" rows={3} placeholder="Votre commentaire..." />
                    <button onClick={() => { onRateMission(ratingMissionId!, ratingValue, ratingComment); setShowRatingModal(false); }} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all">Envoyer l'avis</button>
                </div>
            </div>
        )}

        {showPaymentModal && (
            <div className="fixed inset-0 bg-blue-950/40 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl animate-scale-in">
                    <h3 className="text-2xl font-black text-blue-950 mb-6 flex items-center"><DollarSign className="mr-2 text-green-500" size={28}/> Paiement</h3>
                    <div className="bg-gray-50 p-6 rounded-2xl mb-8 flex justify-between items-center"><span className="text-sm font-bold text-gray-400 uppercase tracking-widest">Total à payer</span><span className="font-black text-3xl text-blue-600">{totalPrice.toLocaleString()} F</span></div>
                    <div className="flex space-x-3">
                        <button onClick={() => setShowPaymentModal(false)} className="flex-1 py-4 text-gray-400 font-black uppercase text-xs">Retour</button>
                        <button onClick={confirmPayment} disabled={isProcessingPayment} className="flex-1 py-4 bg-green-600 text-white rounded-2xl font-black text-lg shadow-xl shadow-green-100 flex justify-center items-center active:scale-95 transition-all">{isProcessingPayment ? <Loader2 className="animate-spin" /> : "Payer"}</button>
                    </div>
                </div>
            </div>
        )}

      <div className="flex bg-white p-1.5 rounded-2xl shadow-sm max-w-md mx-auto border border-gray-100">
        <button onClick={() => setActiveTab('new')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'new' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Commander</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Mes Missions</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'profile' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Profil</button>
      </div>

      <div>
        {activeTab === 'new' && renderNewRequest()}
        {activeTab === 'history' && renderHistory()}
        {activeTab === 'profile' && renderProfile()}
      </div>
    </div>
  );
}

{
  "name": "Servi+",
  "description": "Plateforme de mise en relation pour services ménagers et bricolage à domicile en Côte d'Ivoire.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

import React, { useState, useEffect } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, MarketItem, AiEstimation } from '../types';
import { SERVICE_ICONS, CITIES, BASE_RATES, MARKET_PACKAGING_FEE, MARKET_SERVICE_FEE, MARKET_DELIVERY_FEE, LAUNDRY_MIN_PRICE, LAUNDRY_EXTRA_PRICE, LAUNDRY_MIN_QTY } from '../constants';
import { MapPin, Calendar, Clock, Send, Loader2, Star, AlertTriangle, CheckCircle, Crosshair, Plus, Trash2, ShoppingBag, DollarSign, User as UserIcon, Save, History, PlusCircle, Map as MapIcon, Menu, Timer, ChevronDown, Shirt, ThumbsUp, Sparkles, Wand2, X, ChevronUp } from 'lucide-react';
import { estimateMissionDetails } from '../services/geminiService';

interface ClientDashboardProps {
  currentUser: User;
  missions: Mission[];
  onAddMission: (newMission: Mission, paymentMethod: string) => Promise<void>;
  onValidateMission: (missionId: string) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateMission: (missionId: string, rating: number, comment: string) => void;
  baseRates: Record<ServiceCategory, number>;
  commissionRate: number;
  onUpdateUser: (data: Partial<User>) => void;
}

const CATEGORY_STYLES: Record<ServiceCategory, { active: string; inactive: string }> = {
  [ServiceCategory.CLEANING]: { active: "bg-sky-600 border-sky-700 text-white shadow-lg scale-105 ring-2 ring-sky-300", inactive: "bg-white border-sky-100 text-sky-700 hover:bg-sky-50" },
  [ServiceCategory.COOKING]: { active: "bg-orange-600 border-orange-700 text-white shadow-lg scale-105 ring-2 ring-orange-300", inactive: "bg-white border-orange-100 text-orange-700 hover:bg-orange-50" },
  [ServiceCategory.ELDERLY_CARE]: { active: "bg-emerald-600 border-emerald-700 text-white shadow-lg scale-105 ring-2 ring-emerald-300", inactive: "bg-white border-emerald-100 text-emerald-700 hover:bg-emerald-50" },
  [ServiceCategory.GARDENING]: { active: "bg-green-600 border-green-700 text-white shadow-lg scale-105 ring-2 ring-green-300", inactive: "bg-white border-green-100 text-green-700 hover:bg-green-50" },
  [ServiceCategory.LAUNDRY]: { active: "bg-indigo-600 border-indigo-700 text-white shadow-lg scale-105 ring-2 ring-indigo-300", inactive: "bg-white border-indigo-100 text-indigo-700 hover:bg-indigo-50" },
  [ServiceCategory.BABYSITTING]: { active: "bg-pink-600 border-pink-700 text-white shadow-lg scale-105 ring-2 ring-pink-300", inactive: "bg-white border-pink-100 text-pink-700 hover:bg-pink-50" },
  [ServiceCategory.MARKET]: { active: "bg-amber-600 border-amber-700 text-white shadow-lg scale-105 ring-2 ring-amber-300", inactive: "bg-white border-amber-100 text-orange-700 hover:bg-amber-50" },
  [ServiceCategory.HANDYMAN]: { active: "bg-violet-600 border-violet-700 text-white shadow-lg scale-105 ring-2 ring-violet-300", inactive: "bg-white border-violet-100 text-violet-700 hover:bg-violet-50" },
};

export default function ClientDashboard({
  currentUser,
  missions,
  onAddMission,
  onValidateMission,
  onDisputeMission,
  onRateMission,
  baseRates,
  commissionRate,
  onUpdateUser
}: ClientDashboardProps) {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'profile'>('new');

  const [selectedCategory, setSelectedCategory] = useState<ServiceCategory>(ServiceCategory.CLEANING);
  const [description, setDescription] = useState('');
  const [date, setDate] = useState('');
  const [time, setTime] = useState(''); 
  const [endTime, setEndTime] = useState(''); 
  const [duration, setDuration] = useState(2); 

  const [laundryQuantity, setLaundryQuantity] = useState<number>(20); 

  const [location, setLocation] = useState<string>(currentUser.address || '');
  const [debouncedLocation, setDebouncedLocation] = useState<string>(currentUser.address || '');
  const [city, setCity] = useState(currentUser.city || 'Abidjan');
  const [isLocating, setIsLocating] = useState(false);
  const [statusFilter, setStatusFilter] = useState<string>('TOUTES');

  const [marketItems, setMarketItems] = useState<MarketItem[]>([]);
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [deliveryWindow, setDeliveryWindow] = useState("");

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('Mobile Money');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);

  // IA State
  const [isEstimating, setIsEstimating] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiEstimation | null>(null);

  const [expandedMissionId, setExpandedMissionId] = useState<string | null>(null);
  const [showRatingModal, setShowRatingModal] = useState(false);
  const [ratingMissionId, setRatingMissionId] = useState<string | null>(null);
  const [ratingValue, setRatingValue] = useState(5);
  const [ratingComment, setRatingComment] = useState('');

  const [profileForm, setProfileForm] = useState({
      name: currentUser.name,
      phone: currentUser.phone,
      email: currentUser.email,
      address: currentUser.address || '',
      city: currentUser.city || 'Abidjan',
  });

  useEffect(() => {
    const handler = setTimeout(() => {
        setDebouncedLocation(location);
    }, 1500);
    return () => clearTimeout(handler);
  }, [location]);

  useEffect(() => {
    if (time && endTime && selectedCategory !== ServiceCategory.MARKET && selectedCategory !== ServiceCategory.LAUNDRY) {
      const [startH, startM] = time.split(':').map(Number);
      const [endH, endM] = endTime.split(':').map(Number);

      let diffHours = endH - startH;
      let diffMinutes = endM - startM;

      let totalHours = diffHours + (diffMinutes / 60);
      if (totalHours <= 0) totalHours = 1;

      setDuration(Math.round(totalHours * 10) / 10);
    }
  }, [time, endTime, selectedCategory]);

  const getDeliveryOptions = () => {
      const options = [];
      const now = new Date();
      const currentHour = now.getHours();
      if (currentHour < 11) options.push("Aujourd'hui avant 12h");
      if (currentHour < 13) options.push("Aujourd'hui avant 14h");
      if (currentHour < 17) options.push("Aujourd'hui avant 18h");
      options.push("Demain Matin (8h - 12h)");
      options.push("Demain Après-midi (14h - 18h)");
      return options;
  };

  useEffect(() => {
      const opts = getDeliveryOptions();
      if (opts.length > 0 && !deliveryWindow) setDeliveryWindow(opts[0]);
  }, []);

  const handleAiAssist = async () => {
      if (!description || description.length < 10) {
          alert("Veuillez donner un peu plus de détails pour que l'IA puisse vous aider.");
          return;
      }
      setIsEstimating(true);
      const result = await estimateMissionDetails(description, selectedCategory);
      if (result) {
          setAiSuggestion(result);
      } else {
          alert("L'assistant IA est momentanément indisponible.");
      }
      setIsEstimating(false);
  };

  const applyAiSuggestion = () => {
      if (!aiSuggestion) return;
      setDescription(aiSuggestion.descriptionImprovement);
      setDuration(aiSuggestion.estimatedDuration);
      // On ajuste l'heure de fin si possible
      if (time) {
          const [h, m] = time.split(':').map(Number);
          const endTotalMinutes = h * 60 + m + aiSuggestion.estimatedDuration * 60;
          const endH = Math.floor(endTotalMinutes / 60) % 24;
          const endM = Math.floor(endTotalMinutes % 60);
          setEndTime(`${endH.toString().padStart(2, '0')}:${endM.toString().padStart(2, '0')}`);
      }
      setAiSuggestion(null);
  };

  const getMissionPrice = () => {
      if (selectedCategory === ServiceCategory.MARKET) {
          const itemsTotal = marketItems.reduce((acc, item) => acc + item.price, 0);
          if (itemsTotal === 0) return 0;
          return itemsTotal + MARKET_PACKAGING_FEE + MARKET_SERVICE_FEE + MARKET_DELIVERY_FEE;
      }
      if (selectedCategory === ServiceCategory.LAUNDRY) {
          if (laundryQuantity <= LAUNDRY_MIN_QTY) return LAUNDRY_MIN_PRICE;
          const extraItems = laundryQuantity - LAUNDRY_MIN_QTY;
          return LAUNDRY_MIN_PRICE + (extraItems * LAUNDRY_EXTRA_PRICE);
      }
      const rate = baseRates[selectedCategory] || 2500;
      return Math.round(rate * duration);
  };

  const totalPrice = getMissionPrice();

  const myMissions = missions
    .filter(m => m.clientId === currentUser.id)
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
    .filter(m => {
      if (statusFilter === 'TOUTES') return true;
      if (statusFilter === 'EN_ATTENTE') return m.status === MissionStatus.PENDING;
      if (statusFilter === 'EN_COURS') return [MissionStatus.ACCEPTED, MissionStatus.IN_PROGRESS, MissionStatus.PAYMENT_PENDING].includes(m.status);
      if (statusFilter === 'TERMINEE') return m.status === MissionStatus.COMPLETED;
      if (statusFilter === 'ANNULEE') return [MissionStatus.CANCELLED, MissionStatus.ARCHIVED, MissionStatus.DISPUTED].includes(m.status);
      return true;
  });

  const handleLocateMe = () => {
    if (!navigator.geolocation) return;
    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
        async (position) => {
            const { latitude, longitude } = position.coords;
            const latLng = `${latitude.toFixed(5)}, ${longitude.toFixed(5)}`;
            setLocation(latLng);
            try {
                const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
                const data = await response.json();
                if (data && data.address) {
                    const addr = [data.address.road, data.address.suburb].filter(Boolean).join(', ');
                    if (addr) setLocation(`${addr} (${latLng})`);
                    if (data.address.city) setCity(data.address.city);
                }
            } catch (e) {}
            setIsLocating(false);
        },
        () => setIsLocating(false)
    );
  };

  const handleAddItem = () => {
      const price = parseFloat(newItemPrice);
      if (!newItemName || isNaN(price) || price <= 0) return;
      setMarketItems([...marketItems, { name: newItemName, price }]);
      setNewItemName('');
      setNewItemPrice('');
  };

  // Fix: Added handleRemoveItem to resolve missing function error
  const handleRemoveItem = (index: number) => {
      const newItems = [...marketItems];
      newItems.splice(index, 1);
      setMarketItems(newItems);
  };

  const handleInitiateMission = (e: React.FormEvent) => {
      e.preventDefault();
      if (selectedCategory !== ServiceCategory.MARKET) {
          if (!date || !time) { alert("Détails temporels requis."); return; }
          if (selectedCategory !== ServiceCategory.LAUNDRY && !endTime) { alert("Heure de fin requise."); return; }
      }
      if (selectedCategory !== ServiceCategory.MARKET && !description) { alert("Description requise."); return; }
      if (selectedCategory === ServiceCategory.MARKET && marketItems.length === 0) { alert("Liste vide."); return; }
      setShowPaymentModal(true);
  };

  const confirmPayment = async () => {
      setIsProcessingPayment(true);
      const isoDate = `${date || new Date().toISOString().split('T')[0]}T${time || "08:00"}`;
      const isoEndTime = endTime ? `${date}T${endTime}` : undefined;
      const newMission: Mission = {
          id: `m${Date.now()}`,
          title: selectedCategory === ServiceCategory.MARKET ? 'Course au marché' : `${selectedCategory}`,
          clientId: currentUser.id, clientName: currentUser.name, category: selectedCategory,
          description: description || `Mission ${selectedCategory}`, location: location || "Non spécifié", city,
          date: isoDate, endTime: isoEndTime, durationHours: duration,
          quantity: selectedCategory === ServiceCategory.LAUNDRY ? laundryQuantity : undefined,
          totalPrice, commission: totalPrice * commissionRate, providerAmount: totalPrice * (1 - commissionRate),
          status: MissionStatus.PENDING, createdAt: new Date().toISOString(),
          marketItems: selectedCategory === ServiceCategory.MARKET ? marketItems : undefined,
          deliveryWindow: selectedCategory === ServiceCategory.MARKET ? deliveryWindow : undefined,
      };
      await onAddMission(newMission, paymentMethod);
      setActiveTab('history');
      setIsProcessingPayment(false);
      setShowPaymentModal(false);
  };

  const renderNewRequest = () => {
    const mapUrl = `https://maps.google.com/maps?q=${encodeURIComponent(debouncedLocation || city)}&t=k&z=17&ie=UTF8&iwloc=&output=embed`;
    const today = new Date().toISOString().split('T')[0];

    return (
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden animate-slide-up pb-20 md:pb-0">
          <div className="p-6 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
              <h2 className="text-xl font-bold text-gray-800 flex items-center"><PlusCircle className="mr-2 text-blue-600"/> Nouvelle Demande</h2>
          </div>

          <div className="p-6">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                  {Object.values(ServiceCategory).map((cat) => {
                      const Icon = SERVICE_ICONS[cat];
                      const isSelected = selectedCategory === cat;
                      return (
                          <button key={cat} onClick={() => { setSelectedCategory(cat); if (cat === ServiceCategory.LAUNDRY) setLaundryQuantity(20); }} className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all ${isSelected ? CATEGORY_STYLES[cat].active : CATEGORY_STYLES[cat].inactive}`}>
                              <div className={`p-3 rounded-full mb-2 ${isSelected ? 'bg-white/20' : 'bg-gray-100'}`}><Icon size={24} /></div>
                              <span className="text-[10px] uppercase font-black tracking-tighter text-center">{cat}</span>
                          </button>
                      );
                  })}
              </div>

              <form onSubmit={handleInitiateMission} className="space-y-6">
                  <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                        <label className="block text-xs font-black uppercase text-gray-400 mb-3 tracking-widest">Localisation</label>
                        <div className="relative flex items-center mb-4">
                            <input type="text" required value={location} onChange={(e) => setLocation(e.target.value)} className="w-full pl-10 pr-16 p-3 border border-gray-200 rounded-xl font-bold bg-white text-sm outline-none focus:border-blue-500" placeholder="Adresse ou repère..." />
                            <MapPin size={16} className="absolute left-3 text-blue-500" />
                            <button type="button" onClick={handleLocateMe} className="absolute right-1 px-3 py-1.5 bg-blue-600 text-white rounded-lg text-[10px] font-black uppercase">{isLocating ? '...' : 'GPS'}</button>
                        </div>
                        <div className="rounded-xl overflow-hidden shadow-inner h-40 border border-gray-200"><iframe width="100%" height="100%" frameBorder="0" src={mapUrl}></iframe></div>
                  </div>

                  {selectedCategory === ServiceCategory.MARKET ? (
                      <div className="bg-amber-50 p-6 rounded-2xl border border-amber-100 animate-fade-in">
                          <h3 className="font-black text-amber-800 mb-4 flex items-center text-sm uppercase tracking-widest"><ShoppingBag className="mr-2" size={18}/> Ma Liste de courses</h3>
                          <div className="flex gap-2 mb-4">
                              <input type="text" placeholder="Ex: Tomates" className="flex-grow p-3 rounded-xl border-amber-200 bg-white font-bold text-sm" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} />
                              <input type="number" placeholder="F" className="w-24 p-3 rounded-xl border-amber-200 bg-white font-bold text-sm" value={newItemPrice} onChange={(e) => setNewItemPrice(e.target.value)} />
                              <button type="button" onClick={handleAddItem} className="bg-amber-600 text-white p-3 rounded-xl shadow-md"><Plus size={20} /></button>
                          </div>
                          <div className="space-y-2 mb-4">
                              {marketItems.map((item, idx) => (
                                  <div key={idx} className="flex justify-between items-center bg-white p-3 rounded-xl shadow-sm">
                                      <span className="font-bold text-gray-700">{item.name}</span>
                                      <div className="flex items-center"><span className="font-black mr-3 text-amber-600">{item.price} F</span><button type="button" onClick={() => handleRemoveItem(idx)}><Trash2 size={14} className="text-red-400" /></button></div>
                                  </div>
                              ))}
                          </div>
                          <div className="grid grid-cols-2 gap-4">
                              <input type="date" min={today} value={date} onChange={(e) => setDate(e.target.value)} className="p-3 bg-white border border-amber-200 rounded-xl font-bold text-xs" />
                              <select value={deliveryWindow} onChange={(e) => setDeliveryWindow(e.target.value)} className="p-3 bg-white border border-amber-200 rounded-xl font-bold text-xs">
                                  {getDeliveryOptions().map(opt => <option key={opt} value={opt}>{opt}</option>)}
                              </select>
                          </div>
                      </div>
                  ) : (
                      <div className="space-y-6 animate-fade-in">
                          <div className="relative">
                              <label className="block text-xs font-black uppercase text-gray-400 mb-2 tracking-widest">Description du besoin</label>
                              <textarea required value={description} onChange={(e) => setDescription(e.target.value)} className="w-full p-4 border border-gray-200 rounded-2xl min-h-[100px] text-sm font-bold bg-white focus:border-blue-500 outline-none" placeholder="Décrivez votre demande en quelques mots..." />
                              <button type="button" onClick={handleAiAssist} disabled={isEstimating} className="absolute bottom-4 right-4 bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-black flex items-center shadow-lg hover:shadow-blue-200 transition-all transform active:scale-95 disabled:opacity-50">
                                  {isEstimating ? <Loader2 size={14} className="animate-spin mr-2"/> : <Wand2 size={14} className="mr-2"/>}
                                  Aide de l'IA
                              </button>
                          </div>

                          {aiSuggestion && (
                              <div className="bg-blue-50 border border-blue-100 p-5 rounded-2xl animate-fade-in">
                                  <div className="flex items-center justify-between mb-3">
                                      <span className="text-xs font-black text-blue-800 uppercase flex items-center"><Sparkles size={14} className="mr-2"/> Suggestion de l'assistant IA</span>
                                      <button onClick={() => setAiSuggestion(null)} className="text-blue-400 hover:text-blue-600"><X size={16}/></button>
                                  </div>
                                  <p className="text-xs text-blue-700 italic mb-4 leading-relaxed">"{aiSuggestion.descriptionImprovement}"</p>
                                  <div className="flex gap-4 mb-4">
                                      <div className="bg-white px-3 py-2 rounded-lg border border-blue-100 flex-1"><span className="block text-[10px] text-gray-400 font-bold uppercase">Durée</span><span className="font-black text-blue-900">{aiSuggestion.estimatedDuration}h</span></div>
                                      <div className="bg-white px-3 py-2 rounded-lg border border-blue-100 flex-1"><span className="block text-[10px] text-gray-400 font-bold uppercase">Budget</span><span className="font-black text-blue-900">{aiSuggestion.suggestedPrice.toLocaleString()} F</span></div>
                                  </div>
                                  <button type="button" onClick={applyAiSuggestion} className="w-full bg-blue-600 text-white py-2.5 rounded-xl font-black text-xs uppercase shadow-md shadow-blue-100">Appliquer les suggestions</button>
                              </div>
                          )}

                          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                              <input type="date" required min={today} value={date} onChange={(e) => setDate(e.target.value)} className="p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                              <input type="time" required value={time} onChange={(e) => setTime(e.target.value)} className="p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                              {selectedCategory !== ServiceCategory.LAUNDRY && <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />}
                              {selectedCategory === ServiceCategory.LAUNDRY && (
                                  <div className="bg-indigo-50 p-2 rounded-2xl flex items-center justify-center border border-indigo-100">
                                      <input type="number" min="20" value={laundryQuantity} onChange={(e) => setLaundryQuantity(Math.max(20, parseInt(e.target.value) || 20))} className="w-20 text-center bg-transparent font-black text-indigo-700 outline-none" />
                                      <span className="text-[10px] font-black uppercase text-indigo-400">Pièces</span>
                                  </div>
                              )}
                          </div>
                      </div>
                  )}

                  <div className="flex items-center justify-between pt-6 border-t border-gray-100">
                      <div><p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Estimé</p><p className="text-3xl font-black text-blue-950">{totalPrice.toLocaleString()} F</p></div>
                      <button type="submit" className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 flex items-center transition-all hover:scale-105 active:scale-95"><Send size={20} className="mr-2" /> Commander</button>
                  </div>
              </form>
          </div>
      </div>
    );
  };

  const renderHistory = () => (
      <div className="space-y-4 animate-slide-up relative h-full min-h-[50vh]">
          <div className="flex space-x-2 overflow-x-auto pb-2 sticky top-0 bg-gray-50 z-10 py-2">
              <button onClick={() => setStatusFilter('TOUTES')} className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest ${statusFilter === 'TOUTES' ? 'bg-blue-600 text-white' : 'bg-white text-gray-400 border border-gray-200'}`}>Toutes</button>
              <button onClick={() => setStatusFilter('EN_COURS')} className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest ${statusFilter === 'EN_COURS' ? 'bg-blue-600 text-white' : 'bg-white text-gray-400 border border-gray-200'}`}>En cours</button>
              <button onClick={() => setStatusFilter('TERMINEE')} className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest ${statusFilter === 'TERMINEE' ? 'bg-green-600 text-white' : 'bg-white text-gray-400 border border-gray-200'}`}>Terminées</button>
          </div>

          {myMissions.length === 0 ? (
              <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-gray-200"><History size={48} className="mx-auto text-gray-200 mb-4" /><p className="text-gray-400 font-bold">Aucune mission trouvée.</p></div>
          ) : (
              myMissions.map(mission => (
                  <div key={mission.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100 transition-all hover:shadow-md">
                      <div className="flex justify-between items-start mb-4">
                          <div className="flex items-center space-x-4">
                              <div className="p-3 bg-gray-50 rounded-2xl"><div className="text-blue-600">{React.createElement(SERVICE_ICONS[mission.category], {size: 24})}</div></div>
                              <div><h3 className="font-black text-blue-950 text-lg">{mission.title}</h3><p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{new Date(mission.date).toLocaleDateString()}</p></div>
                          </div>
                          <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${mission.status === MissionStatus.COMPLETED ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>{mission.status}</span>
                      </div>
                      <div className="bg-gray-50 p-4 rounded-2xl mb-4 text-xs font-medium text-gray-600 leading-relaxed italic">"{mission.description}"</div>
                      <div className="flex justify-end gap-2">
                          {mission.status === MissionStatus.COMPLETED && !mission.clientRating && (
                              <button onClick={() => { setRatingMissionId(mission.id); setShowRatingModal(true); }} className="bg-yellow-100 text-yellow-700 px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest flex items-center hover:bg-yellow-200 transition-colors"><Star size={14} className="mr-2" /> Noter</button>
                          )}
                          {(mission.status === MissionStatus.IN_PROGRESS || mission.status === MissionStatus.ACCEPTED) && (
                              <button onClick={() => onValidateMission(mission.id)} className="bg-green-600 text-white px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest flex items-center hover:bg-green-700 transition-colors shadow-lg shadow-green-100"><CheckCircle size={14} className="mr-2" /> Valider la fin</button>
                          )}
                      </div>
                  </div>
              ))
          )}
      </div>
  );

  // Fix: Added missing renderProfile function to resolve the error
  const renderProfile = () => (
      <div className="bg-white rounded-2xl shadow-sm p-8 max-w-xl mx-auto animate-slide-up">
          <h2 className="text-2xl font-black text-blue-950 mb-6 flex items-center">
              <UserIcon className="mr-2 text-blue-600" size={28} />
              Mon Profil
          </h2>

          <form onSubmit={(e) => {
              e.preventDefault();
              onUpdateUser(profileForm);
              alert("✅ Profil mis à jour !");
          }} className="space-y-6">
              <div>
                  <label className="block text-xs font-black uppercase text-gray-400 mb-2 tracking-widest">Nom Complet</label>
                  <input 
                    type="text" 
                    required
                    value={profileForm.name}
                    onChange={(e) => setProfileForm({...profileForm, name: e.target.value})}
                    className="w-full p-4 border border-gray-200 rounded-2xl font-bold text-sm bg-gray-50 focus:bg-white focus:border-blue-500 transition-all outline-none"
                  />
              </div>

              <div>
                  <label className="block text-xs font-black uppercase text-gray-400 mb-2 tracking-widest">Téléphone</label>
                  <input 
                    type="tel" 
                    required
                    value={profileForm.phone}
                    onChange={(e) => setProfileForm({...profileForm, phone: e.target.value})}
                    className="w-full p-4 border border-gray-200 rounded-2xl font-bold text-sm bg-gray-50 focus:bg-white focus:border-blue-500 transition-all outline-none"
                  />
              </div>

              <div className="relative">
                  <label className="block text-xs font-black uppercase text-gray-400 mb-2 tracking-widest">Ville</label>
                  <div className="relative">
                    <select
                        value={profileForm.city}
                        onChange={(e) => setProfileForm({...profileForm, city: e.target.value})}
                        className="w-full p-4 border border-gray-200 rounded-2xl font-bold text-sm bg-gray-50 focus:bg-white focus:border-blue-500 transition-all outline-none appearance-none"
                    >
                        {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-4 text-gray-400 pointer-events-none" size={18} />
                  </div>
              </div>

              <div>
                  <label className="block text-xs font-black uppercase text-gray-400 mb-2 tracking-widest">Adresse</label>
                  <input 
                    type="text" 
                    value={profileForm.address}
                    onChange={(e) => setProfileForm({...profileForm, address: e.target.value})}
                    className="w-full p-4 border border-gray-200 rounded-2xl font-bold text-sm bg-gray-50 focus:bg-white focus:border-blue-500 transition-all outline-none"
                  />
              </div>

              <button 
                  type="submit"
                  className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center mt-4"
              >
                  <Save size={20} className="mr-2" />
                  Sauvegarder
              </button>
          </form>
      </div>
  );

  return (
    <div className="space-y-6">
        {showRatingModal && (
            <div className="fixed inset-0 bg-blue-950/40 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm animate-scale-in shadow-2xl relative">
                    <button onClick={() => setShowRatingModal(false)} className="absolute top-6 right-6 text-gray-300 hover:text-gray-600"><X size={20}/></button>
                    <div className="text-center mb-8">
                        <div className="w-16 h-16 bg-yellow-100 rounded-2xl flex items-center justify-center mx-auto mb-4"><Star size={32} className="text-yellow-500" fill="currentColor"/></div>
                        <h3 className="text-2xl font-black text-blue-950">Avis Service</h3>
                        <p className="text-sm font-medium text-gray-500 mt-1">Comment évaluez-vous le travail ?</p>
                    </div>
                    <div className="flex justify-center space-x-2 mb-8">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button key={star} onClick={() => setRatingValue(star)} className={`transition-all hover:scale-125 ${star <= ratingValue ? 'text-yellow-400' : 'text-gray-100'}`}><Star size={32} fill="currentColor" /></button>
                        ))}
                    </div>
                    <textarea value={ratingComment} onChange={(e) => setRatingComment(e.target.value)} className="w-full border border-gray-100 rounded-2xl p-4 mb-8 focus:ring-2 focus:ring-yellow-400 outline-none text-sm font-bold bg-gray-50" rows={3} placeholder="Votre commentaire..." />
                    <button onClick={() => { onRateMission(ratingMissionId!, ratingValue, ratingComment); setShowRatingModal(false); }} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all">Envoyer l'avis</button>
                </div>
            </div>
        )}

        {showPaymentModal && (
            <div className="fixed inset-0 bg-blue-950/40 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl animate-scale-in">
                    <h3 className="text-2xl font-black text-blue-950 mb-6 flex items-center"><DollarSign className="mr-2 text-green-500" size={28}/> Paiement</h3>
                    <div className="bg-gray-50 p-6 rounded-2xl mb-8 flex justify-between items-center"><span className="text-sm font-bold text-gray-400 uppercase tracking-widest">Total à payer</span><span className="font-black text-3xl text-blue-600">{totalPrice.toLocaleString()} F</span></div>
                    <div className="flex space-x-3">
                        <button onClick={() => setShowPaymentModal(false)} className="flex-1 py-4 text-gray-400 font-black uppercase text-xs">Retour</button>
                        <button onClick={confirmPayment} disabled={isProcessingPayment} className="flex-1 py-4 bg-green-600 text-white rounded-2xl font-black text-lg shadow-xl shadow-green-100 flex justify-center items-center active:scale-95 transition-all">{isProcessingPayment ? <Loader2 className="animate-spin" /> : "Payer"}</button>
                    </div>
                </div>
            </div>
        )}

      <div className="flex bg-white p-1.5 rounded-2xl shadow-sm max-w-md mx-auto border border-gray-100">
        <button onClick={() => setActiveTab('new')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'new' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Commander</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Mes Missions</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'profile' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Profil</button>
      </div>

      <div>
        {activeTab === 'new' && renderNewRequest()}
        {activeTab === 'history' && renderHistory()}
        {activeTab === 'profile' && renderProfile()}
      </div>
    </div>
  );
}

export enum UserRole {
  CLIENT = 'CLIENT',
  PROVIDER = 'PROVIDER',
  ADMIN = 'ADMIN',
  GUEST = 'GUEST'
}

export enum ServiceCategory {
  CLEANING = 'Ménage',
  COOKING = 'Cuisine',
  ELDERLY_CARE = 'Garde de personnes âgées',
  GARDENING = 'Jardinage',
  LAUNDRY = 'Lessive',
  BABYSITTING = 'Garde d\'enfants',
  MARKET = 'Faire mon marché',
  HANDYMAN = 'Bricolage'
}

export enum MissionStatus {
  PENDING = 'En attente',
  ACCEPTED = 'Acceptée',
  IN_PROGRESS = 'En cours',
  PAYMENT_PENDING = 'En attente de paiement',
  COMPLETED = 'Terminée',
  DISPUTED = 'En litige',
  CANCELLED = 'Annulée',
  ARCHIVED = 'Archivée'
}

export interface MarketItem {
  name: string;
  price: number;
}

export interface User {
  id: string;
  name: string;
  email: string;
  phone: string;
  password?: string;
  role: UserRole;
  avatarUrl: string;
  address?: string;
  city?: string;
  rating?: number;
  walletBalance?: number;
  verified?: boolean;
  services?: ServiceCategory[];
  createdAt?: string;
  idNumber?: string;
  idCardRecto?: string;
  idCardVerso?: string;
  acceptTerms?: boolean;
  isSuperAdmin?: boolean;
}

export interface Mission {
  id: string;
  title: string;
  clientId: string;
  clientName: string;
  providerId?: string;
  providerName?: string;
  category: ServiceCategory;
  description: string;
  location: string;
  city?: string;
  date: string;
  endTime?: string;
  durationHours: number;
  quantity?: number;
  marketItems?: MarketItem[];
  deliveryWindow?: string;
  totalPrice: number;
  commission: number;
  providerAmount: number;
  status: MissionStatus;
  createdAt: string;
  latitude?: number;
  longitude?: number;
  estimatedArrivalTime?: string;
  estimatedDistance?: number;
  disputeReason?: string;
  disputeInitiator?: 'CLIENT' | 'PROVIDER';
  completedAt?: string;
  clientRating?: number;
  clientComment?: string;
  providerRating?: number;
  providerComment?: string;
}

export interface Transaction {
  id: string;
  amount: number;
  type: 'INCOME' | 'PAYOUT';
  userId: string;
  userName?: string;
  missionId?: string;
  date: string;
  method: 'Mobile Money' | 'Carte Bancaire' | 'Espèces' | 'Virement';
  status: 'SUCCESS' | 'PENDING_APPROVAL' | 'REJECTED';
}

export interface AiEstimation {
  estimatedDuration: number;
  suggestedPrice: number;
  descriptionImprovement: string;
}

