import React, { useState, useEffect } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, MarketItem, AiEstimation } from '../types';
import { SERVICE_ICONS, CITIES, BASE_RATES, MARKET_PACKAGING_FEE, MARKET_SERVICE_FEE, MARKET_DELIVERY_FEE, LAUNDRY_MIN_PRICE, LAUNDRY_EXTRA_PRICE, LAUNDRY_MIN_QTY } from '../constants';
import { MapPin, Calendar, Clock, Send, Loader2, Star, AlertTriangle, CheckCircle, Crosshair, Plus, Trash2, ShoppingBag, DollarSign, User as UserIcon, Save, History, PlusCircle, Map as MapIcon, Menu, Timer, ChevronDown, Shirt, ThumbsUp, Sparkles, Wand2, X, ChevronUp } from 'lucide-react';
import { estimateMissionDetails } from '../services/geminiService';

interface ClientDashboardProps {
  currentUser: User;
  missions: Mission[];
  onAddMission: (newMission: Mission, paymentMethod: string) => Promise<void>;
  onValidateMission: (missionId: string) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateMission: (missionId: string, rating: number, comment: string) => void;
  baseRates: Record<ServiceCategory, number>;
  commissionRate: number;
  onUpdateUser: (data: Partial<User>) => void;
}

const CATEGORY_STYLES: Record<ServiceCategory, { active: string; inactive: string }> = {
  [ServiceCategory.CLEANING]: { active: "bg-sky-600 border-sky-700 text-white shadow-lg scale-105 ring-2 ring-sky-300", inactive: "bg-white border-sky-100 text-sky-700 hover:bg-sky-50" },
  [ServiceCategory.COOKING]: { active: "bg-orange-600 border-orange-700 text-white shadow-lg scale-105 ring-2 ring-orange-300", inactive: "bg-white border-orange-100 text-orange-700 hover:bg-orange-50" },
  [ServiceCategory.ELDERLY_CARE]: { active: "bg-emerald-600 border-emerald-700 text-white shadow-lg scale-105 ring-2 ring-emerald-300", inactive: "bg-white border-emerald-100 text-emerald-700 hover:bg-emerald-50" },
  [ServiceCategory.GARDENING]: { active: "bg-green-600 border-green-700 text-white shadow-lg scale-105 ring-2 ring-green-300", inactive: "bg-white border-green-100 text-green-700 hover:bg-green-50" },
  [ServiceCategory.LAUNDRY]: { active: "bg-indigo-600 border-indigo-700 text-white shadow-lg scale-105 ring-2 ring-indigo-300", inactive: "bg-white border-indigo-100 text-indigo-700 hover:bg-indigo-50" },
  [ServiceCategory.BABYSITTING]: { active: "bg-pink-600 border-pink-700 text-white shadow-lg scale-105 ring-2 ring-pink-300", inactive: "bg-white border-pink-100 text-pink-700 hover:bg-pink-50" },
  [ServiceCategory.MARKET]: { active: "bg-amber-600 border-amber-700 text-white shadow-lg scale-105 ring-2 ring-amber-300", inactive: "bg-white border-amber-100 text-orange-700 hover:bg-amber-50" },
  [ServiceCategory.HANDYMAN]: { active: "bg-violet-600 border-violet-700 text-white shadow-lg scale-105 ring-2 ring-violet-300", inactive: "bg-white border-violet-100 text-violet-700 hover:bg-violet-50" },
};

export default function ClientDashboard({
  currentUser,
  missions,
  onAddMission,
  onValidateMission,
  onDisputeMission,
  onRateMission,
  baseRates,
  commissionRate,
  onUpdateUser
}: ClientDashboardProps) {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'profile'>('new');

  const [selectedCategory, setSelectedCategory] = useState<ServiceCategory>(ServiceCategory.CLEANING);
  const [description, setDescription] = useState('');
  const [date, setDate] = useState('');
  const [time, setTime] = useState(''); 
  const [endTime, setEndTime] = useState(''); 
  const [duration, setDuration] = useState(2); 

  const [laundryQuantity, setLaundryQuantity] = useState<number>(20); 

  const [location, setLocation] = useState<string>(currentUser.address || '');
  const [debouncedLocation, setDebouncedLocation] = useState<string>(currentUser.address || '');
  const [city, setCity] = useState(currentUser.city || 'Abidjan');
  const [isLocating, setIsLocating] = useState(false);
  const [statusFilter, setStatusFilter] = useState<string>('TOUTES');

  const [marketItems, setMarketItems] = useState<MarketItem[]>([]);
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [deliveryWindow, setDeliveryWindow] = useState("");

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('Mobile Money');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);

  const [isEstimating, setIsEstimating] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiEstimation | null>(null);

  const [expandedMissionId, setExpandedMissionId] = useState<string | null>(null);
  const [showRatingModal, setShowRatingModal] = useState(false);
  const [ratingMissionId, setRatingMissionId] = useState<string | null>(null);
  const [ratingValue, setRatingValue] = useState(5);
  const [ratingComment, setRatingComment] = useState('');

  const [profileForm, setProfileForm] = useState({
      name: currentUser.name,
      phone: currentUser.phone,
      email: currentUser.email,
      address: currentUser.address || '',
      city: currentUser.city || 'Abidjan',
  });

  useEffect(() => {
    const handler = setTimeout(() => {
        setDebouncedLocation(location);
    }, 1500);
    return () => clearTimeout(handler);
  }, [location]);

  useEffect(() => {
    if (time && endTime && selectedCategory !== ServiceCategory.MARKET && selectedCategory !== ServiceCategory.LAUNDRY) {
      const [startH, startM] = time.split(':').map(Number);
      const [endH, endM] = endTime.split(':').map(Number);

      let diffHours = endH - startH;
      let diffMinutes = endM - startM;

      let totalHours = diffHours + (diffMinutes / 60);
      if (totalHours <= 0) totalHours = 1;

      setDuration(Math.round(totalHours * 10) / 10);
    }
  }, [time, endTime, selectedCategory]);

  const getDeliveryOptions = () => {
      const options = [];
      const now = new Date();
      const currentHour = now.getHours();
      if (currentHour < 11) options.push("Aujourd'hui avant 12h");
      if (currentHour < 13) options.push("Aujourd'hui avant 14h");
      if (currentHour < 17) options.push("Aujourd'hui avant 18h");
      options.push("Demain Matin (8h - 12h)");
      options.push("Demain Après-midi (14h - 18h)");
      return options;
  };

  useEffect(() => {
      const opts = getDeliveryOptions();
      if (opts.length > 0 && !deliveryWindow) setDeliveryWindow(opts[0]);
  }, []);

  const handleAiAssist = async () => {
      if (!description || description.length < 10) {
          alert("Veuillez donner un peu plus de détails pour que l'IA puisse vous aider.");
          return;
      }
      setIsEstimating(true);
      const result = await estimateMissionDetails(description, selectedCategory);
      if (result) setAiSuggestion(result);
      setIsEstimating(false);
  };

  const applyAiSuggestion = () => {
      if (!aiSuggestion) return;
      setDescription(aiSuggestion.descriptionImprovement);
      setDuration(aiSuggestion.estimatedDuration);
      if (time) {
          const [h, m] = time.split(':').map(Number);
          const endTotalMinutes = h * 60 + m + aiSuggestion.estimatedDuration * 60;
          const endH = Math.floor(endTotalMinutes / 60) % 24;
          const endM = Math.floor(endTotalMinutes % 60);
          setEndTime(`${endH.toString().padStart(2, '0')}:${endM.toString().padStart(2, '0')}`);
      }
      setAiSuggestion(null);
  };

  const getMissionPrice = () => {
      if (selectedCategory === ServiceCategory.MARKET) {
          const itemsTotal = marketItems.reduce((acc, item) => acc + item.price, 0);
          if (itemsTotal === 0) return 0;
          return itemsTotal + MARKET_PACKAGING_FEE + MARKET_SERVICE_FEE + MARKET_DELIVERY_FEE;
      }
      if (selectedCategory === ServiceCategory.LAUNDRY) {
          if (laundryQuantity <= LAUNDRY_MIN_QTY) return LAUNDRY_MIN_PRICE;
          return LAUNDRY_MIN_PRICE + ((laundryQuantity - LAUNDRY_MIN_QTY) * LAUNDRY_EXTRA_PRICE);
      }
      return Math.round((baseRates[selectedCategory] || 2500) * duration);
  };

  const totalPrice = getMissionPrice();

  const myMissions = missions
    .filter(m => m.clientId === currentUser.id)
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
    .filter(m => {
      if (statusFilter === 'TOUTES') return true;
      if (statusFilter === 'EN_ATTENTE') return m.status === MissionStatus.PENDING;
      if (statusFilter === 'EN_COURS') return [MissionStatus.ACCEPTED, MissionStatus.IN_PROGRESS, MissionStatus.PAYMENT_PENDING].includes(m.status);
      if (statusFilter === 'TERMINEE') return m.status === MissionStatus.COMPLETED;
      if (statusFilter === 'ANNULEE') return [MissionStatus.CANCELLED, MissionStatus.ARCHIVED, MissionStatus.DISPUTED].includes(m.status);
      return true;
  });

  const handleLocateMe = () => {
    if (!navigator.geolocation) return;
    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(async (pos) => {
        const latLng = `${pos.coords.latitude.toFixed(5)}, ${pos.coords.longitude.toFixed(5)}`;
        setLocation(latLng);
        setIsLocating(false);
    }, () => setIsLocating(false));
  };

  const handleAddItem = () => {
      const price = parseFloat(newItemPrice);
      if (!newItemName || isNaN(price)) return;
      setMarketItems([...marketItems, { name: newItemName, price }]);
      setNewItemName(''); setNewItemPrice('');
  };

  const handleRemoveItem = (index: number) => {
      setMarketItems(marketItems.filter((_, i) => i !== index));
  };

  const handleInitiateMission = (e: React.FormEvent) => {
      e.preventDefault();
      setShowPaymentModal(true);
  };

  const confirmPayment = async () => {
      setIsProcessingPayment(true);
      const isoDate = `${date || new Date().toISOString().split('T')[0]}T${time || "08:00"}`;
      const newMission: Mission = {
          id: `m${Date.now()}`,
          title: selectedCategory === ServiceCategory.MARKET ? 'Course au marché' : `${selectedCategory}`,
          clientId: currentUser.id, clientName: currentUser.name, category: selectedCategory,
          description: description || `Mission ${selectedCategory}`, location: location || "Non spécifié", city,
          date: isoDate, endTime: endTime ? `${date}T${endTime}` : undefined, durationHours: duration,
          quantity: selectedCategory === ServiceCategory.LAUNDRY ? laundryQuantity : undefined,
          totalPrice, commission: totalPrice * commissionRate, providerAmount: totalPrice * (1 - commissionRate),
          status: MissionStatus.PENDING, createdAt: new Date().toISOString(),
          marketItems: selectedCategory === ServiceCategory.MARKET ? marketItems : undefined,
          deliveryWindow: selectedCategory === ServiceCategory.MARKET ? deliveryWindow : undefined,
      };
      await onAddMission(newMission, paymentMethod);
      setActiveTab('history');
      setIsProcessingPayment(false);
      setShowPaymentModal(false);
  };

  const renderNewRequest = () => {
    const mapUrl = `https://maps.google.com/maps?q=${encodeURIComponent(debouncedLocation || city)}&t=k&z=17&ie=UTF8&iwloc=&output=embed`;
    const today = new Date().toISOString().split('T')[0];
    return (
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden animate-slide-up pb-20">
          <div className="p-6 border-b border-gray-50 bg-gray-50 flex justify-between items-center">
              <h2 className="text-xl font-black text-blue-950 flex items-center"><PlusCircle className="mr-2 text-blue-600"/> Nouvelle Demande</h2>
          </div>
          <div className="p-6">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                  {Object.values(ServiceCategory).map((cat) => {
                      const Icon = SERVICE_ICONS[cat];
                      const isSelected = selectedCategory === cat;
                      return (
                          <button key={cat} onClick={() => setSelectedCategory(cat)} className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all ${isSelected ? CATEGORY_STYLES[cat].active : CATEGORY_STYLES[cat].inactive}`}>
                              <div className={`p-3 rounded-full mb-2 ${isSelected ? 'bg-white/20' : 'bg-gray-100'}`}><Icon size={24} /></div>
                              <span className="text-[10px] uppercase font-black tracking-tighter text-center">{cat}</span>
                          </button>
                      );
                  })}
              </div>
              <form onSubmit={handleInitiateMission} className="space-y-6">
                  <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                        <label className="block text-xs font-black uppercase text-gray-400 mb-3 tracking-widest">Localisation</label>
                        <div className="relative flex items-center mb-4">
                            <input type="text" required value={location} onChange={(e) => setLocation(e.target.value)} className="w-full pl-10 pr-16 p-3 border border-gray-200 rounded-xl font-bold bg-white text-sm outline-none" placeholder="Où ?" />
                            <MapPin size={16} className="absolute left-3 text-blue-500" />
                            <button type="button" onClick={handleLocateMe} className="absolute right-1 px-3 py-1.5 bg-blue-600 text-white rounded-lg text-[10px] font-black uppercase">GPS</button>
                        </div>
                        <div className="rounded-xl overflow-hidden shadow-inner h-40 border border-gray-200"><iframe width="100%" height="100%" frameBorder="0" src={mapUrl}></iframe></div>
                  </div>
                  {selectedCategory === ServiceCategory.MARKET ? (
                      <div className="bg-amber-50 p-6 rounded-2xl border border-amber-100">
                          <h3 className="font-black text-amber-800 mb-4 flex items-center text-sm uppercase tracking-widest"><ShoppingBag className="mr-2" size={18}/> Ma Liste</h3>
                          <div className="flex gap-2 mb-4">
                              <input type="text" placeholder="Article" className="flex-grow p-3 rounded-xl bg-white font-bold text-sm" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} />
                              <input type="number" placeholder="FCFA" className="w-24 p-3 rounded-xl bg-white font-bold text-sm" value={newItemPrice} onChange={(e) => setNewItemPrice(e.target.value)} />
                              <button type="button" onClick={handleAddItem} className="bg-amber-600 text-white p-3 rounded-xl shadow-md"><Plus size={20} /></button>
                          </div>
                          <div className="space-y-2 mb-4">
                              {marketItems.map((item, idx) => (
                                  <div key={idx} className="flex justify-between items-center bg-white p-3 rounded-xl shadow-sm">
                                      <span className="font-bold text-gray-700">{item.name}</span>
                                      <div className="flex items-center"><span className="font-black mr-3 text-amber-600">{item.price} F</span><button type="button" onClick={() => handleRemoveItem(idx)}><Trash2 size={14} className="text-red-400" /></button></div>
                                  </div>
                              ))}
                          </div>
                      </div>
                  ) : (
                      <div className="space-y-6">
                          <div className="relative">
                              <label className="block text-xs font-black uppercase text-gray-400 mb-2 tracking-widest">Besoin</label>
                              <textarea required value={description} onChange={(e) => setDescription(e.target.value)} className="w-full p-4 border border-gray-200 rounded-2xl min-h-[100px] text-sm font-bold bg-white focus:border-blue-500 outline-none" placeholder="Dites-nous tout..." />
                              <button type="button" onClick={handleAiAssist} disabled={isEstimating} className="absolute bottom-4 right-4 bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-black flex items-center shadow-lg">
                                  {isEstimating ? <Loader2 size={14} className="animate-spin mr-2"/> : <Wand2 size={14} className="mr-2"/>} Aide IA
                              </button>
                          </div>
                          {aiSuggestion && (
                              <div className="bg-blue-50 border border-blue-100 p-5 rounded-2xl animate-fade-in">
                                  <p className="text-xs text-blue-700 italic mb-4 leading-relaxed">"{aiSuggestion.descriptionImprovement}"</p>
                                  <button type="button" onClick={applyAiSuggestion} className="w-full bg-blue-600 text-white py-2.5 rounded-xl font-black text-xs uppercase shadow-md shadow-blue-100">Appliquer</button>
                              </div>
                          )}
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                              <input type="date" required min={today} value={date} onChange={(e) => setDate(e.target.value)} className="p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                              <input type="time" required value={time} onChange={(e) => setTime(e.target.value)} className="p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                              <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                          </div>
                      </div>
                  )}
                  <div className="flex items-center justify-between pt-6 border-t border-gray-100">
                      <div><p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Estimé</p><p className="text-3xl font-black text-blue-950">{totalPrice.toLocaleString()} F</p></div>
                      <button type="submit" className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 flex items-center transition-all hover:scale-105 active:scale-95"><Send size={20} className="mr-2" /> Commander</button>
                  </div>
              </form>
          </div>
      </div>
    );
  };

  const renderHistory = () => (
      <div className="space-y-4 animate-slide-up relative h-full min-h-[50vh]">
          {myMissions.map(mission => (
              <div key={mission.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100 transition-all hover:shadow-md">
                  <div className="flex justify-between items-start mb-4">
                      <div className="flex items-center space-x-4">
                          <div className="p-3 bg-gray-50 rounded-2xl"><div className="text-blue-600">{React.createElement(SERVICE_ICONS[mission.category], {size: 24})}</div></div>
                          <div><h3 className="font-black text-blue-950 text-lg">{mission.title}</h3><p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{new Date(mission.date).toLocaleDateString()}</p></div>
                      </div>
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${mission.status === MissionStatus.COMPLETED ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>{mission.status}</span>
                  </div>
                  <div className="flex justify-end gap-2">
                      {mission.status === MissionStatus.COMPLETED && !mission.clientRating && (
                          <button onClick={() => { setRatingMissionId(mission.id); setShowRatingModal(true); }} className="bg-yellow-100 text-yellow-700 px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest flex items-center"><Star size={14} className="mr-2" /> Noter</button>
                      )}
                      {(mission.status === MissionStatus.IN_PROGRESS || mission.status === MissionStatus.ACCEPTED) && (
                          <button onClick={() => onValidateMission(mission.id)} className="bg-green-600 text-white px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest flex items-center"><CheckCircle size={14} className="mr-2" /> Valider</button>
                      )}
                  </div>
              </div>
          ))}
          {myMissions.length === 0 && <div className="text-center py-20 text-gray-400 font-bold">Aucune mission.</div>}
      </div>
  );

  const renderProfile = () => (
      <div className="bg-white rounded-3xl shadow-sm p-8 max-w-xl mx-auto animate-slide-up">
          <h2 className="text-2xl font-black text-blue-950 mb-6 flex items-center"><UserIcon className="mr-2 text-blue-600" size={28} /> Mon Profil</h2>
          <form onSubmit={(e) => { e.preventDefault(); onUpdateUser(profileForm); alert("Sauvegardé !"); }} className="space-y-6">
              <input type="text" required value={profileForm.name} onChange={(e) => setProfileForm({...profileForm, name: e.target.value})} className="w-full p-4 border border-gray-200 rounded-2xl font-bold bg-gray-50 outline-none focus:bg-white" placeholder="Nom" />
              <input type="tel" required value={profileForm.phone} onChange={(e) => setProfileForm({...profileForm, phone: e.target.value})} className="w-full p-4 border border-gray-200 rounded-2xl font-bold bg-gray-50 outline-none focus:bg-white" placeholder="Téléphone" />
              <button type="submit" className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all flex items-center justify-center"><Save size={20} className="mr-2" /> Sauvegarder</button>
          </form>
      </div>
  );

  return (
    <div className="space-y-6">
        {showRatingModal && (
            <div className="fixed inset-0 bg-blue-950/40 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm animate-scale-in shadow-2xl relative">
                    <button onClick={() => setShowRatingModal(false)} className="absolute top-6 right-6 text-gray-300 hover:text-gray-600"><X size={20}/></button>
                    <div className="flex justify-center space-x-2 mb-8">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button key={star} onClick={() => setRatingValue(star)} className={`transition-all hover:scale-125 ${star <= ratingValue ? 'text-yellow-400' : 'text-gray-100'}`}><Star size={32} fill="currentColor" /></button>
                        ))}
                    </div>
                    <button onClick={() => { onRateMission(ratingMissionId!, ratingValue, ratingComment); setShowRatingModal(false); }} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all">Envoyer</button>
                </div>
            </div>
        )}
        {showPaymentModal && (
            <div className="fixed inset-0 bg-blue-950/40 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl animate-scale-in text-center">
                    <h3 className="text-2xl font-black text-blue-950 mb-6 flex items-center justify-center"><DollarSign className="mr-2 text-green-500" size={28}/> Paiement</h3>
                    <div className="bg-gray-50 p-6 rounded-2xl mb-8 flex justify-between items-center"><span className="text-sm font-bold text-gray-400 uppercase tracking-widest">Total</span><span className="font-black text-3xl text-blue-600">{totalPrice.toLocaleString()} F</span></div>
                    <div className="flex space-x-3">
                        <button onClick={() => setShowPaymentModal(false)} className="flex-1 py-4 text-gray-400 font-black uppercase text-xs">Retour</button>
                        <button onClick={confirmPayment} disabled={isProcessingPayment} className="flex-1 py-4 bg-green-600 text-white rounded-2xl font-black text-lg shadow-xl shadow-green-100 flex justify-center items-center active:scale-95 transition-all">{isProcessingPayment ? <Loader2 className="animate-spin" /> : "Payer"}</button>
                    </div>
                </div>
            </div>
        )}
      <div className="flex bg-white p-1.5 rounded-2xl shadow-sm max-w-md mx-auto border border-gray-100">
        <button onClick={() => setActiveTab('new')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'new' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Commander</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Historique</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'profile' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Profil</button>
      </div>
      <div>
        {activeTab === 'new' && renderNewRequest()}
        {activeTab === 'history' && renderHistory()}
        {activeTab === 'profile' && renderProfile()}
      </div>
    </div>
  );
}

