  PENDING = 'En attente',
  ACCEPTED = 'Acceptée',
  IN_PROGRESS = 'En cours',
  PAYMENT_PENDING = 'En attente de paiement',
  COMPLETED = 'Terminée',
  DISPUTED = 'En litige',
  CANCELLED = 'Annulée',
  ARCHIVED = 'Archivée'
}

export interface MarketItem {
  name: string;
  price: number;
}

export interface User {
  id: string;
  name: string;
  email: string;
  phone: string;
  password?: string;
  role: UserRole;
  avatarUrl: string;
  address?: string;
  city?: string;
  rating?: number;
  walletBalance?: number;
  verified?: boolean;
  services?: ServiceCategory[];
  createdAt?: string;
  idNumber?: string;
  idCardRecto?: string;
  idCardVerso?: string;
  acceptTerms?: boolean;
  isSuperAdmin?: boolean;
}

export interface Mission {
  id: string;
  title: string;
  clientId: string;
  clientName: string;
  providerId?: string;
  providerName?: string;
  category: ServiceCategory;
  description: string;
  location: string;
  city?: string;
  date: string;
  endTime?: string;
  durationHours: number;
  quantity?: number;
  marketItems?: MarketItem[];
  deliveryWindow?: string;
  totalPrice: number;
  commission: number;
  providerAmount: number;
  status: MissionStatus;
  createdAt: string;
  latitude?: number;
  longitude?: number;
  estimatedArrivalTime?: string;
  estimatedDistance?: number;
  disputeReason?: string;
  disputeInitiator?: 'CLIENT' | 'PROVIDER';
  completedAt?: string;
  clientRating?: number;
  clientComment?: string;
  providerRating?: number;
  providerComment?: string;
