interface ClientDashboardProps {
  currentUser: User;
  missions: Mission[];
  onAddMission: (newMission: Mission, paymentMethod: string) => Promise<void>;
  onValidateMission: (missionId: string) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateMission: (missionId: string, rating: number, comment: string) => void;
  baseRates: Record<ServiceCategory, number>;
  commissionRate: number;
  onUpdateUser: (data: Partial<User>) => void;
}

// Typage strict Record<ServiceCategory, ...> pour garantir l'exhaustivité des styles
const CATEGORY_STYLES: Record<ServiceCategory, { active: string; inactive: string }> = {
  [ServiceCategory.CLEANING]: { active: "bg-sky-600 border-sky-700 text-white shadow-lg scale-105 ring-2 ring-sky-300", inactive: "bg-white border-sky-100 text-sky-700 hover:bg-sky-50" },
  [ServiceCategory.COOKING]: { active: "bg-orange-600 border-orange-700 text-white shadow-lg scale-105 ring-2 ring-orange-300", inactive: "bg-white border-orange-100 text-orange-700 hover:bg-orange-50" },
  [ServiceCategory.ELDERLY_CARE]: { active: "bg-emerald-600 border-emerald-700 text-white shadow-lg scale-105 ring-2 ring-emerald-300", inactive: "bg-white border-emerald-100 text-emerald-700 hover:bg-emerald-50" },
  [ServiceCategory.GARDENING]: { active: "bg-green-600 border-green-700 text-white shadow-lg scale-105 ring-2 ring-green-300", inactive: "bg-white border-green-100 text-green-700 hover:bg-green-50" },
  [ServiceCategory.LAUNDRY]: { active: "bg-indigo-600 border-indigo-700 text-white shadow-lg scale-105 ring-2 ring-indigo-300", inactive: "bg-white border-indigo-100 text-indigo-700 hover:bg-indigo-50" },
  [ServiceCategory.BABYSITTING]: { active: "bg-pink-600 border-pink-700 text-white shadow-lg scale-105 ring-2 ring-pink-300", inactive: "bg-white border-pink-100 text-pink-700 hover:bg-pink-50" },
  [ServiceCategory.MARKET]: { active: "bg-amber-600 border-amber-700 text-white shadow-lg scale-105 ring-2 ring-amber-300", inactive: "bg-white border-amber-100 text-orange-700 hover:bg-orange-50" },
  [ServiceCategory.HANDYMAN]: { active: "bg-violet-600 border-violet-700 text-white shadow-lg scale-105 ring-2 ring-violet-300", inactive: "bg-white border-violet-100 text-violet-700 hover:bg-violet-50" },
};

export default function ClientDashboard({
  currentUser,
  missions,
  onAddMission,
  onValidateMission,
  onRateMission,
  baseRates,
  commissionRate,
  onUpdateUser
}: ClientDashboardProps) {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'profile'>('new');
  const [selectedCategory, setSelectedCategory] = useState<ServiceCategory>(ServiceCategory.CLEANING);
  const [description, setDescription] = useState('');
  const [date, setDate] = useState('');
  const [time, setTime] = useState(''); 
  const [endTime, setEndTime] = useState(''); 
  const [duration, setDuration] = useState(2); 
  const [laundryQuantity, setLaundryQuantity] = useState<number>(20); 
  const [location, setLocation] = useState<string>(currentUser.address || '');
  const [debouncedLocation, setDebouncedLocation] = useState<string>(currentUser.address || '');
  const [city, setCity] = useState(currentUser.city || 'Abidjan');
  const [marketItems, setMarketItems] = useState<MarketItem[]>([]);
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [deliveryWindow, setDeliveryWindow] = useState("");
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentMethod] = useState('Mobile Money');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);
  const [isEstimating, setIsEstimating] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiEstimation | null>(null);
  const [showRatingModal, setShowRatingModal] = useState(false);
  const [ratingMissionId, setRatingMissionId] = useState<string | null>(null);
  const [ratingValue, setRatingValue] = useState(5);
  const [ratingComment, setRatingComment] = useState('');
  const [profileForm, setProfileForm] = useState({
      name: currentUser.name,
      phone: currentUser.phone,
      email: currentUser.email,
      address: currentUser.address || '',
      city: currentUser.city || 'Abidjan',
  });

  useEffect(() => {
    const handler = setTimeout(() => { setDebouncedLocation(location); }, 1500);
    return () => clearTimeout(handler);
  }, [location]);

  useEffect(() => {
    if (time && endTime && selectedCategory !== ServiceCategory.MARKET && selectedCategory !== ServiceCategory.LAUNDRY) {
      const [startH, startM] = time.split(':').map(Number);
      const [endH, endM] = endTime.split(':').map(Number);
      let diffHours = endH - startH;
      let diffMinutes = endM - startM;
      let totalHours = diffHours + (diffMinutes / 60);
      if (totalHours <= 0) totalHours = 1;
      setDuration(Math.round(totalHours * 10) / 10);
    }
  }, [time, endTime, selectedCategory]);

  const getMissionPrice = () => {
      if (selectedCategory === ServiceCategory.MARKET) {
          const itemsTotal = marketItems.reduce((acc, item) => acc + item.price, 0);
          if (itemsTotal === 0) return 0;
          return itemsTotal + MARKET_PACKAGING_FEE + MARKET_SERVICE_FEE + MARKET_DELIVERY_FEE;
      }
      if (selectedCategory === ServiceCategory.LAUNDRY) {
          if (laundryQuantity <= LAUNDRY_MIN_QTY) return LAUNDRY_MIN_PRICE;
          return LAUNDRY_MIN_PRICE + ((laundryQuantity - LAUNDRY_MIN_QTY) * LAUNDRY_EXTRA_PRICE);
      }
      return Math.round((baseRates[selectedCategory] || 2500) * duration);
  };

  const totalPrice = getMissionPrice();
  const myMissions = missions.filter(m => m.clientId === currentUser.id).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  const handleAiAssist = async () => {
      if (!description || description.length < 10) return;
      setIsEstimating(true);
      const result = await estimateMissionDetails(description, selectedCategory);
      if (result) setAiSuggestion(result);
      setIsEstimating(false);
  };

  const confirmPayment = async () => {
      setIsProcessingPayment(true);
      const isoDate = `${date}T${time}`;
      const newMission: Mission = {
          id: `m${Date.now()}`,
          title: selectedCategory === ServiceCategory.MARKET ? 'Course au marché' : `${selectedCategory}`,
          clientId: currentUser.id, clientName: currentUser.name, category: selectedCategory,
          description: description || `Mission ${selectedCategory}`, location: location || "Non spécifié", city,
          date: isoDate, endTime: endTime ? `${date}T${endTime}` : undefined, durationHours: duration,
          quantity: selectedCategory === ServiceCategory.LAUNDRY ? laundryQuantity : undefined,
          totalPrice, commission: totalPrice * commissionRate, providerAmount: totalPrice * (1 - commissionRate),
          status: MissionStatus.PENDING, createdAt: new Date().toISOString(),
          marketItems: selectedCategory === ServiceCategory.MARKET ? marketItems : undefined,
          deliveryWindow: selectedCategory === ServiceCategory.MARKET ? deliveryWindow : undefined,
      };
      await onAddMission(newMission, paymentMethod);
      setActiveTab('history');
      setIsProcessingPayment(false);
      setShowPaymentModal(false);
  };

  return (
    <div className="space-y-6">
      {/* Modales */}
      {showRatingModal && (
        <div className="fixed inset-0 bg-blue-950/40 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl relative">
            <button onClick={() => setShowRatingModal(false)} className="absolute top-6 right-6 text-gray-300 hover:text-gray-600"><X size={20}/></button>
            <div className="flex justify-center space-x-2 mb-8">
              {[1, 2, 3, 4, 5].map((star) => (
                <button key={star} onClick={() => setRatingValue(star)} className={`transition-all hover:scale-125 ${star <= ratingValue ? 'text-yellow-400' : 'text-gray-100'}`}><Star size={32} fill="currentColor" /></button>
              ))}
            </div>
            <button onClick={() => { onRateMission(ratingMissionId!, ratingValue, ratingComment); setShowRatingModal(false); }} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-lg">Noter</button>
          </div>
        </div>
      )}

      {showPaymentModal && (
        <div className="fixed inset-0 bg-blue-950/40 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl text-center">
            <h3 className="text-2xl font-black text-blue-950 mb-6 flex items-center justify-center"><DollarSign className="mr-2 text-green-500" size={28}/> Paiement</h3>
            <div className="bg-gray-50 p-6 rounded-2xl mb-8 flex justify-between items-center"><span className="text-sm font-bold text-gray-400 uppercase">Total</span><span className="font-black text-3xl text-blue-600">{totalPrice.toLocaleString()} F</span></div>
            <div className="flex space-x-3">
              <button onClick={() => setShowPaymentModal(false)} className="flex-1 py-4 text-gray-400 font-black uppercase text-xs">Retour</button>
              <button onClick={confirmPayment} disabled={isProcessingPayment} className="flex-1 py-4 bg-green-600 text-white rounded-2xl font-black text-lg">{isProcessingPayment ? <Loader2 className="animate-spin" /> : "Payer"}</button>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Onglets */}
      <div className="flex bg-white p-1.5 rounded-2xl shadow-sm max-w-md mx-auto border border-gray-100">
        <button onClick={() => setActiveTab('new')} className={`flex-1 py-3 text-xs font-black uppercase rounded-xl transition-all ${activeTab === 'new' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Commander</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 text-xs font-black uppercase rounded-xl transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Historique</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 py-3 text-xs font-black uppercase rounded-xl transition-all ${activeTab === 'profile' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Profil</button>
      </div>

      {/* Contenu principal */}
      <div className="animate-fade-in">
        {activeTab === 'new' && (
          <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden pb-20">
            <div className="p-6 border-b border-gray-50 bg-gray-50 flex justify-between items-center"><h2 className="text-xl font-black text-blue-950 flex items-center"><PlusCircle className="mr-2 text-blue-600"/> Nouvelle Demande</h2></div>
            <div className="p-6">
              {/* Choix de catégorie */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                {(Object.values(ServiceCategory) as ServiceCategory[]).map((cat) => {
                  const Icon = SERVICE_ICONS[cat];
                  const isSelected = selectedCategory === cat;
                  return (
                    <button key={cat} onClick={() => setSelectedCategory(cat)} className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all ${isSelected ? CATEGORY_STYLES[cat].active : CATEGORY_STYLES[cat].inactive}`}>
                      <div className={`p-3 rounded-full mb-2 ${isSelected ? 'bg-white/20' : 'bg-gray-100'}`}><Icon size={24} /></div>
                      <span className="text-[10px] uppercase font-black text-center">{cat}</span>
                    </button>
                  );
                })}
              </div>

              {/* Formulaire de commande */}
              <form onSubmit={(e) => { e.preventDefault(); setShowPaymentModal(true); }} className="space-y-6">
                <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                  <label className="block text-xs font-black uppercase text-gray-400 mb-3">Localisation</label>
                  <div className="relative flex items-center mb-4">
                    <input type="text" required value={location} onChange={(e) => setLocation(e.target.value)} className="w-full pl-10 pr-4 p-3 border border-gray-200 rounded-xl font-bold bg-white text-sm outline-none" placeholder="Où ?" />
                    <MapPin size={16} className="absolute left-3 text-blue-500" />
                  </div>
                </div>

                <div className="relative">
                  <label className="block text-xs font-black uppercase text-gray-400 mb-2">Description du besoin</label>
                  <textarea required value={description} onChange={(e) => setDescription(e.target.value)} className="w-full p-4 border border-gray-200 rounded-2xl min-h-[100px] text-sm font-bold focus:border-blue-500 outline-none" placeholder="Décrivez votre besoin..." />
                  <button type="button" onClick={handleAiAssist} disabled={isEstimating} className="absolute bottom-4 right-4 bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-black flex items-center shadow-lg">
                    {isEstimating ? <Loader2 size={14} className="animate-spin mr-2"/> : <Wand2 size={14} className="mr-2"/>} Aide IA
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-1">Date</label>
                    <input type="date" required value={date} onChange={(e) => setDate(e.target.value)} className="w-full p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-1">Début</label>
                    <input type="time" required value={time} onChange={(e) => setTime(e.target.value)} className="w-full p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-1">Fin</label>
                    <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-4 bg-white border border-gray-200 rounded-2xl font-bold text-sm" />
                  </div>
                </div>

                <div className="flex items-center justify-between pt-6 border-t border-gray-100">
                  <div><p className="text-[10px] font-black text-gray-400 uppercase">Total Estimé</p><p className="text-3xl font-black text-blue-950">{totalPrice.toLocaleString()} F</p></div>
                  <button type="submit" className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 flex items-center transition-all hover:scale-105 active:scale-95"><Send size={20} className="mr-2" /> Commander</button>
                </div>
              </form>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-4 relative h-full min-h-[50vh]">
            {myMissions.map(mission => (
              <div key={mission.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
                <div className="flex justify-between items-start mb-4">
                  <div className="flex items-center space-x-4">
                    <div className="p-3 bg-gray-50 rounded-2xl text-blue-600">{React.createElement(SERVICE_ICONS[mission.category], {size: 24})}</div>
                    <div><h3 className="font-black text-blue-950 text-lg">{mission.title}</h3><p className="text-xs font-bold text-gray-400 uppercase">{new Date(mission.date).toLocaleDateString()}</p></div>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${mission.status === MissionStatus.COMPLETED ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>{mission.status}</span>
                </div>
                {mission.status === MissionStatus.COMPLETED && !mission.clientRating && (
                  <button onClick={() => { setRatingMissionId(mission.id); setShowRatingModal(true); }} className="w-full bg-yellow-50 text-yellow-700 py-3 rounded-xl font-black text-xs uppercase flex items-center justify-center"><Star size={14} className="mr-2" /> Noter la prestation</button>
                )}
                {mission.status === MissionStatus.IN_PROGRESS && (
                   <button onClick={() => onValidateMission(mission.id)} className="w-full bg-green-600 text-white py-3 rounded-xl font-black text-xs uppercase flex items-center justify-center"><CheckCircle size={14} className="mr-2" /> Valider la fin de mission</button>
                )}
              </div>
            ))}
          </div>
        )}

        {activeTab === 'profile' && (
          <div className="bg-white rounded-3xl shadow-sm p-8 max-w-xl mx-auto">
            <h2 className="text-2xl font-black text-blue-950 mb-6 flex items-center"><UserIcon className="mr-2 text-blue-600" size={28} /> Mon Profil</h2>
            <form onSubmit={(e) => { e.preventDefault(); onUpdateUser(profileForm); alert("Sauvegardé !"); }} className="space-y-6">
              <input type="text" required value={profileForm.name} onChange={(e) => setProfileForm({...profileForm, name: e.target.value})} className="w-full p-4 border border-gray-200 rounded-2xl font-bold bg-gray-50 outline-none" placeholder="Nom" />
              <input type="tel" required value={profileForm.phone} onChange={(e) => setProfileForm({...profileForm, phone: e.target.value})} className="w-full p-4 border border-gray-200 rounded-2xl font-bold bg-gray-50 outline-none" placeholder="Téléphone" />
              <button type="submit" className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100"><Save size={20} className="mr-2" /> Sauvegarder</button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
}

