import { MapPin, Clock, CheckCircle, AlertTriangle, Star, Calendar, Phone, Navigation, User as UserIcon, Save, Wallet, LayoutGrid, DollarSign, ChevronDown, Camera, ShoppingBag, HelpCircle, Loader2 } from 'lucide-react';

interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[];
  transactions: Transaction[];
  onUpdateMissionStatus: (missionId: string, status: MissionStatus, providerId?: string, estimation?: { arrivalTime: string, distance: number }) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
  onRequestWithdrawal: (amount: number, method: string) => void;
}

export default function ProviderDashboard({ currentUser, missions, users, transactions, onUpdateMissionStatus, onDisputeMission, onRateClient, onUpdateUser, onRequestWithdrawal }: ProviderDashboardProps) {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');

  // Profile State
  const [profileForm, setProfileForm] = useState({
    name: currentUser.name || '',
    phone: currentUser.phone || '',
    address: currentUser.address || '',
    city: currentUser.city || 'Abidjan',
  });
  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>(currentUser.services || []);
  const [newAvatar, setNewAvatar] = useState<string | null>(null);

  // Wallet State
  const [withdrawalAmount, setWithdrawalAmount] = useState<number>(0);

  // Data Filtering
  const myMissions = missions.filter(m => m.providerId === currentUser.id);

  const availableMissions = missions.filter(m => 
    m.status === MissionStatus.PENDING && 
    !m.providerId && 
    (!currentUser.city || m.city === currentUser.city) && 
    (!currentUser.services || currentUser.services.includes(m.category))
  );

  const totalEarnings = myMissions.filter(m => m.status === MissionStatus.COMPLETED).reduce((sum, m) => sum + m.providerAmount, 0);
  const withdrawn = transactions.filter(t => t.type === 'PAYOUT' && t.userId === currentUser.id && t.status === 'SUCCESS').reduce((sum, t) => sum + t.amount, 0);
  const balance = Math.max(0, totalEarnings - withdrawn);

  // Modal State
  const [selectedMissionId, setSelectedMissionId] = useState<string | null>(null);
  const [modalType, setModalType] = useState<'DISPUTE' | 'RATING' | null>(null);
  const [inputText, setInputText] = useState('');
  const [ratingValue, setRatingValue] = useState(5);

  const openRating = (id: string) => {
    setSelectedMissionId(id);
    setModalType('RATING');
    setInputText('');
    setRatingValue(5);
  };

  const submitModal = () => {
    if (!selectedMissionId) return;
    if (modalType === 'RATING') {
      onRateClient(selectedMissionId, ratingValue, inputText);
    }
    setModalType(null);
    setSelectedMissionId(null);
  };

  const handleAcceptMission = (missionId: string) => {
      const arrival = new Date(); arrival.setMinutes(arrival.getMinutes() + 30);
      onUpdateMissionStatus(missionId, MissionStatus.ACCEPTED, currentUser.id, { arrivalTime: arrival.toISOString(), distance: 5 });
      setActiveTab('my-missions');
  };

  const handleProfileSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      onUpdateUser({
          ...profileForm,
          services: selectedServices,
          avatarUrl: newAvatar || currentUser.avatarUrl
      });
      alert("✅ Profil mis à jour avec succès !");
  };

  const toggleService = (service: ServiceCategory) => {
      if (selectedServices.includes(service)) {
          setSelectedServices(selectedServices.filter(s => s !== service));
      } else {
          setSelectedServices([...selectedServices, service]);
      }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => setNewAvatar(reader.result as string);
          reader.readAsDataURL(file);
      }
  };

  const renderModal = () => {
    if (!modalType) return null;
    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
        <div className="bg-white rounded-2xl p-6 w-full max-w-md animate-scale-in shadow-2xl">
          <h3 className="text-xl font-bold mb-4 text-blue-600">Noter le client</h3>
          <div className="flex justify-center space-x-2 mb-4">
              {[1, 2, 3, 4, 5].map((star) => (
                <button key={star} onClick={() => setRatingValue(star)} className={`transition-transform hover:scale-125 ${star <= ratingValue ? 'text-yellow-400' : 'text-gray-300'}`}>
                  <Star size={32} fill="currentColor" />
                </button>
              ))}
          </div>
          <textarea value={inputText} onChange={(e) => setInputText(e.target.value)} className="w-full border border-gray-300 rounded-lg p-3 mb-4 font-bold outline-none" rows={3} placeholder="Commentaire..." />
          <button onClick={submitModal} className="w-full bg-blue-600 text-white py-4 rounded-xl font-black text-lg shadow-xl shadow-blue-100 transition-all active:scale-95">Envoyer</button>
          <button onClick={() => setModalType(null)} className="w-full text-gray-400 py-3 mt-2 font-black text-xs uppercase tracking-widest">Annuler</button>
        </div>
      </div>
    );
  };

  const renderMarketplace = () => (
      <div className="space-y-4 animate-fade-in">
          {availableMissions.map(m => {
              const Icon = SERVICE_ICONS[m.category] || HelpCircle;
              return (
                <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm hover-card border border-gray-100">
                    <div className="flex justify-between items-start">
                        <div className="flex items-center space-x-4">
                            <div className="p-3 bg-gray-50 rounded-2xl text-blue-600">
                                <Icon size={24} />
                            </div>
                            <div>
                                <h3 className="font-black text-lg text-blue-950">{m.title}</h3>
                                <div className="flex items-center text-gray-400 text-xs font-bold mt-1 uppercase tracking-widest">
                                    <MapPin size={12} className="mr-1 text-blue-500"/> {m.location} ({m.city})
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <span className="block text-green-600 font-black text-xl">{m.providerAmount.toLocaleString()} F</span>
                            <span className="text-[10px] text-gray-400 font-black uppercase tracking-widest">Net vendeur</span>
                        </div>
                    </div>

                    <div className="bg-gray-50 p-4 rounded-2xl mt-4 text-sm text-gray-600 font-medium">
                        {m.category === ServiceCategory.MARKET ? (
                            <div className="flex items-center"><ShoppingBag size={14} className="mr-2 text-orange-500"/> Commande de marché ({m.marketItems?.length || 0} articles)</div>
                        ) : (
                            <p>{(m.description || 'Pas de description fournie.').substring(0, 100)}...</p>
                        )}
                    </div>

                    <button onClick={() => handleAcceptMission(m.id)} className="w-full mt-6 bg-blue-600 text-white py-4 rounded-2xl font-black text-lg hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 active:scale-95">
                        Accepter la mission
                    </button>
                </div>
              );
          })}
          {availableMissions.length === 0 && (
              <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-gray-200 animate-fade-in">
                  <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4">
                      <Clock size={32} className="text-gray-200" />
                  </div>
                  <p className="text-gray-400 font-black text-xs uppercase tracking-widest">Aucune mission disponible pour le moment.</p>
              </div>
          )}
      </div>
  );

  const renderMyMissions = () => (
      <div className="space-y-6 animate-fade-in">
          {myMissions.map(m => {
              const client = users.find(u => u.id === m.clientId);
              const isAccepted = m.status === MissionStatus.ACCEPTED || m.status === MissionStatus.IN_PROGRESS;
              const Icon = SERVICE_ICONS[m.category] || HelpCircle;

              return (
                  <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border-l-8 border-blue-600">
                      <div className="flex justify-between items-center mb-6">
                          <div className="flex items-center space-x-4">
                              <div className="p-3 bg-gray-50 rounded-2xl text-blue-600">
                                  <Icon size={24} />
                              </div>
                              <div>
                                  <h3 className="font-black text-lg text-blue-950">{m.title}</h3>
                                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Commande #{m.id.slice(-6)}</p>
                              </div>
                          </div>
                          <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${
                              m.status === MissionStatus.COMPLETED ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700 shadow-sm'
                          }`}>
                              {m.status}
                          </span>
                      </div>

                      {isAccepted && client ? (
                          <div className="bg-blue-50/50 p-6 rounded-3xl border border-blue-100 mb-6">
                              <div className="flex justify-between items-center mb-6">
                                  <div className="flex items-center space-x-3">
                                      <img src={client.avatarUrl} className="w-12 h-12 rounded-2xl object-cover border-2 border-white shadow-sm" alt="Client" />
                                      <div>
                                          <p className="font-black text-blue-950">{client.name}</p>
                                          <p className="text-xs font-bold text-gray-400 flex items-center mt-0.5">
                                              <MapPin size={12} className="mr-1 text-blue-500"/> {m.location}
                                          </p>
                                      </div>
                                  </div>
                                  <div className="flex space-x-3">
                                      <a href={`tel:${client.phone}`} className="bg-green-600 text-white p-3 rounded-2xl shadow-lg shadow-green-100 active:scale-90 transition-all" title="Appeler">
                                          <Phone size={20} />
                                      </a>
                                      <a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(m.location)}`} target="_blank" rel="noreferrer" className="bg-blue-600 text-white p-3 rounded-2xl shadow-lg shadow-blue-100 active:scale-90 transition-all">
                                          <Navigation size={20} />
                                      </a>
                                  </div>
                              </div>

                              <div className="bg-white p-5 rounded-2xl border border-blue-50">
                                  <h5 className="text-[10px] font-black text-gray-300 uppercase tracking-widest mb-3">Détails de l'intervention</h5>
                                  <p className="text-sm font-bold text-gray-700 leading-relaxed">{(m.description || 'Pas de détails supplémentaires.')}</p>
                              </div>
                          </div>
                      ) : (
                          <div className="mb-6 bg-gray-50 p-4 rounded-2xl border border-gray-100 flex items-center justify-center">
                              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">Les coordonnées seront visibles après acceptation.</p>
                          </div>
                      )}

                      <div className="flex gap-3">
                          {m.status === MissionStatus.ACCEPTED && (
                              <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.IN_PROGRESS)} className="flex-1 bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 active:scale-95 transition-all">
                                  Débuter l'intervention
                              </button>
                          )}
                          {m.status === MissionStatus.IN_PROGRESS && (
                              <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.COMPLETED)} className="flex-1 bg-green-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-green-100 active:scale-95 transition-all flex items-center justify-center">
                                  <CheckCircle size={20} className="mr-2"/> Terminer la mission
                              </button>
                          )}
                          {m.status === MissionStatus.COMPLETED && !m.providerRating && (
                              <button onClick={() => openRating(m.id)} className="flex-1 bg-yellow-400 text-blue-950 py-4 rounded-2xl font-black text-lg shadow-xl shadow-yellow-100 transition-all active:scale-95">
                                  Noter le client
                              </button>
                          )}
                      </div>
                  </div>
              );
          })}
      </div>
  );

  const renderWallet = () => (
      <div className="space-y-6 animate-fade-in">
          <div className="bg-blue-950 text-white p-10 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
              <p className="text-blue-300 text-xs font-black uppercase tracking-widest">Solde Spirituel</p>
              <h2 className="text-5xl font-black mt-2 tracking-tighter">{balance.toLocaleString()} F</h2>
              <Wallet className="absolute -right-6 -bottom-6 opacity-10 rotate-12" size={180} />
          </div>
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100">
              <h3 className="font-black text-blue-950 mb-6 flex items-center uppercase text-sm tracking-widest">
                  <DollarSign size={18} className="mr-2 text-green-600"/> Nouveau retrait
              </h3>
              <div className="flex gap-4 flex-col md:flex-row">
                  <input type="number" value={withdrawalAmount} onChange={e => setWithdrawalAmount(Number(e.target.value))} className="flex-1 p-4 border border-gray-100 bg-gray-50 rounded-2xl font-black text-2xl focus:bg-white outline-none" placeholder="0 F" />
                  <button 
                    onClick={() => { if(withdrawalAmount <= balance && withdrawalAmount > 0) onRequestWithdrawal(withdrawalAmount, 'Mobile Money'); setWithdrawalAmount(0); }} 
                    className={`px-10 py-4 rounded-2xl font-black text-lg transition-all active:scale-95 shadow-xl ${withdrawalAmount > 0 && withdrawalAmount <= balance ? 'bg-green-600 text-white shadow-green-100' : 'bg-gray-100 text-gray-300 cursor-not-allowed'}`}
                    disabled={withdrawalAmount <= 0 || withdrawalAmount > balance}
                  >
                    Valider le retrait
                  </button>
              </div>
          </div>
      </div>
  );

  const renderProfile = () => (
      <div className="bg-white rounded-3xl shadow-sm p-10 max-w-xl mx-auto animate-fade-in">
          <h2 className="text-2xl font-black text-blue-950 mb-10 flex items-center justify-center border-b border-gray-50 pb-6">
              <UserIcon className="mr-3 text-blue-600" size={28} />
              Mon Profil Pro
          </h2>

          <form onSubmit={handleProfileSubmit} className="space-y-8">
              <div className="flex flex-col items-center">
                  <div className="relative w-32 h-32 rounded-[2rem] bg-gray-50 overflow-hidden border-4 border-white shadow-xl group">
                      <img src={newAvatar || currentUser.avatarUrl} alt="Pro" className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
                      <div className="absolute inset-0 bg-blue-950/40 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                          <Camera className="text-white" />
                      </div>
                      <input type="file" accept="image/*" onChange={handleFileChange} className="absolute inset-0 opacity-0 cursor-pointer" />
                  </div>
                  <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-4">Modifier la photo</span>
              </div>

              <div className="space-y-4">
                  <input type="text" required value={profileForm.name} onChange={e => setProfileForm({...profileForm, name: e.target.value})} className="w-full p-4 border border-gray-100 bg-gray-50 rounded-2xl font-bold focus:bg-white outline-none" placeholder="Nom Complet" />
                  <input type="tel" required value={profileForm.phone} onChange={e => setProfileForm({...profileForm, phone: e.target.value})} className="w-full p-4 border border-gray-100 bg-gray-50 rounded-2xl font-bold focus:bg-white outline-none" placeholder="Téléphone" />
                  <div className="relative">
                      <select value={profileForm.city} onChange={e => setProfileForm({...profileForm, city: e.target.value})} className="w-full p-4 border border-gray-100 bg-gray-50 rounded-2xl font-bold appearance-none outline-none">
                          {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                      <ChevronDown className="absolute right-4 top-4 text-gray-400" size={20} />
                  </div>
                  <div className="pt-6 border-t border-gray-50">
                    <label className="block text-[10px] font-black text-gray-300 uppercase tracking-widest mb-4">Mes Compétences</label>
                    <div className="grid grid-cols-2 gap-3">
                        {Object.values(ServiceCategory).map((cat) => {
                            const isSelected = selectedServices.includes(cat);
                            return (
                                <button key={cat} type="button" onClick={() => toggleService(cat)} className={`flex items-center justify-center p-3 rounded-xl border-2 font-black text-[10px] uppercase tracking-tighter transition-all ${isSelected ? 'border-blue-600 bg-blue-50 text-blue-600 shadow-sm' : 'border-gray-50 text-gray-400'}`}>
                                    {cat}
                                </button>
                            );
                        })}
                    </div>
                  </div>
              </div>

              <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-[1.5rem] font-black text-lg shadow-xl shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all flex justify-center items-center">
                  <Save size={20} className="mr-2" /> Sauvegarder les modifications
              </button>
          </form>
      </div>
  );

  return (
    <div className="space-y-6">
      {renderModal()}

      <div className="flex space-x-1.5 bg-white p-1.5 rounded-2xl shadow-sm max-w-xl mx-auto border border-gray-100 animate-fade-in">
        <button onClick={() => setActiveTab('marketplace')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all relative ${activeTab === 'marketplace' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>
          Missions
          {availableMissions.length > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[8px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-white">{availableMissions.length}</span>}
        </button>
        <button onClick={() => setActiveTab('my-missions')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'my-missions' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Mes Travaux</button>
        <button onClick={() => setActiveTab('wallet')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'wallet' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Portefeuille</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'profile' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Profil</button>
      </div>

      <div className="animate-fade-in">
        {activeTab === 'marketplace' && renderMarketplace()}
        {activeTab === 'my-missions' && renderMyMissions()}
        {activeTab === 'wallet' && renderWallet()}
        {activeTab === 'profile' && renderProfile()}
      </div>
    </div>
  );
}

