import React, { useState } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, Transaction } from '../types';
import { SERVICE_ICONS, CITIES } from '../constants';
import { MapPin, Clock, CheckCircle, Star, Phone, Navigation, User as UserIcon, Save, Wallet, DollarSign, ChevronDown, Camera, ShoppingBag, HelpCircle, Loader2, Info } from 'lucide-react';

interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[];
  transactions: Transaction[];
  onUpdateMissionStatus: (missionId: string, status: MissionStatus, providerId?: string, estimation?: { arrivalTime: string, distance: number }) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
  onRequestWithdrawal: (amount: number, method: string) => void;
}

export default function ProviderDashboard({ currentUser, missions, users, transactions, onUpdateMissionStatus, onDisputeMission, onRateClient, onUpdateUser, onRequestWithdrawal }: ProviderDashboardProps) {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');

  const [profileForm, setProfileForm] = useState({
    name: currentUser.name || '',
    phone: currentUser.phone || '',
    address: currentUser.address || '',
    city: currentUser.city || 'Abidjan',
  });
  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>(currentUser.services || []);
  const [newAvatar, setNewAvatar] = useState<string | null>(null);
  const [withdrawalAmount, setWithdrawalAmount] = useState<number>(0);

  // Data Filtering
  const myMissions = missions.filter(m => m.providerId === currentUser.id);
  const availableMissions = missions.filter(m => 
    m.status === MissionStatus.PENDING && 
    !m.providerId && 
    (!currentUser.city || m.city === currentUser.city) && 
    (!currentUser.services || currentUser.services.includes(m.category))
  );

  const totalEarnings = myMissions.filter(m => m.status === MissionStatus.COMPLETED).reduce((sum, m) => sum + m.providerAmount, 0);
  const withdrawn = transactions.filter(t => t.type === 'PAYOUT' && t.userId === currentUser.id && t.status === 'SUCCESS').reduce((sum, t) => sum + t.amount, 0);
  const balance = Math.max(0, totalEarnings - withdrawn);

  const handleAcceptMission = (missionId: string) => {
      const arrival = new Date(); arrival.setMinutes(arrival.getMinutes() + 30);
      onUpdateMissionStatus(missionId, MissionStatus.ACCEPTED, currentUser.id, { arrivalTime: arrival.toISOString(), distance: 5 });
      setActiveTab('my-missions');
  };

  const renderMarketplace = () => (
      <div className="space-y-4 animate-fade-in">
          {availableMissions.map(m => {
              const Icon = SERVICE_ICONS[m.category] || HelpCircle;
              return (
                <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
                    <div className="flex justify-between items-start">
                        <div className="flex items-center space-x-4">
                            <div className="p-3 bg-gray-50 rounded-2xl text-blue-600"><Icon size={24} /></div>
                            <div>
                                <h3 className="font-black text-lg text-blue-950">{m.title}</h3>
                                <div className="flex items-center text-gray-400 text-xs font-bold mt-1 uppercase"><MapPin size={12} className="mr-1 text-blue-500"/> {m.location}</div>
                            </div>
                        </div>
                        <div className="text-right">
                            <span className="block text-green-600 font-black text-xl">{m.providerAmount?.toLocaleString()} F</span>
                        </div>
                    </div>
                    <div className="bg-gray-50 p-4 rounded-2xl mt-4 text-sm text-gray-600 font-medium">
                        {m.category === ServiceCategory.MARKET ? (
                            <div className="flex items-center"><ShoppingBag size={14} className="mr-2 text-orange-500"/> Commande de marché ({m.marketItems?.length || 0} articles)</div>
                        ) : (
                            <p>{(m.description || 'Pas de description.').substring(0, 100)}...</p>
                        )}
                    </div>
                    <button onClick={() => handleAcceptMission(m.id)} className="w-full mt-6 bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100">Accepter</button>
                </div>
              );
          })}
          {availableMissions.length === 0 && (
              <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-gray-200">
                  <Info size={32} className="mx-auto text-gray-200 mb-2" />
                  <p className="text-gray-400 font-black text-xs uppercase">Aucune mission disponible.</p>
              </div>
          )}
      </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex space-x-1 bg-white p-1.5 rounded-2xl shadow-sm max-w-xl mx-auto border border-gray-100">
