                    </div>
                    <button onClick={() => handleAcceptMission(m.id)} className="w-full mt-6 bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 transition-all active:scale-95">Accepter la mission</button>
                </div>
              );
          })}
