import React, { useState } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, Transaction } from '../types';
import { SERVICE_ICONS, CITIES } from '../constants';
import { MapPin, Clock, CheckCircle, Star, Phone, Navigation, User as UserIcon, Save, Wallet, DollarSign, ChevronDown, Camera, ShoppingBag, HelpCircle, Loader2, Info } from 'lucide-react';

interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[];
  transactions: Transaction[];
  onUpdateMissionStatus: (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
  onRequestWithdrawal: (amount: number, method: string) => void;
}

export default function ProviderDashboard({ 
  currentUser, 
  missions = [], 
  users = [], 
  transactions = [], 
  onUpdateMissionStatus, 
  onDisputeMission, 
  onRateClient, 
  onUpdateUser, 
  onRequestWithdrawal 
}: ProviderDashboardProps) {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');

  const [profileForm, setProfileForm] = useState({
    name: currentUser?.name || '',
    phone: currentUser?.phone || '',
    address: currentUser?.address || '',
    city: currentUser?.city || 'Abidjan',
  });

  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>(currentUser?.services || []);
  const [newAvatar, setNewAvatar] = useState<string | null>(null);
  const [withdrawalAmount, setWithdrawalAmount] = useState<number>(0);

  const myMissions = missions.filter(m => m.providerId === currentUser?.id);
  const availableMissions = missions.filter(m => 
    m.status === MissionStatus.PENDING && 
    !m.providerId && 
    (!currentUser?.city || m.city === currentUser.city) && 
    (!currentUser?.services || currentUser.services.includes(m.category))
  );

  const totalEarnings = myMissions.filter(m => m.status === MissionStatus.COMPLETED).reduce((sum, m) => sum + (m.providerAmount || 0), 0);
  const withdrawn = transactions.filter(t => t.type === 'PAYOUT' && t.userId === currentUser?.id && t.status === 'SUCCESS').reduce((sum, t) => sum + t.amount, 0);
  const balance = Math.max(0, totalEarnings - withdrawn);

  const handleAcceptMission = (missionId: string) => {
      const arrival = new Date(); 
      arrival.setMinutes(arrival.getMinutes() + 30);
      onUpdateMissionStatus(missionId, MissionStatus.ACCEPTED, currentUser.id, { arrivalTime: arrival.toISOString(), distance: 5 });
      setActiveTab('my-missions');
  };

  const renderMarketplace = () => (
      <div className="space-y-4 animate-fade-in">
          {availableMissions.map(m => {
              const Icon = SERVICE_ICONS[m.category] || HelpCircle;
              return (
                <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
                    <div className="flex justify-between items-start">
                        <div className="flex items-center space-x-4">
                            <div className="p-3 bg-gray-50 rounded-2xl text-blue-600"><Icon size={24} /></div>
                            <div>
                                <h3 className="font-black text-lg text-blue-950">{m.title || "Mission sans titre"}</h3>
                                <div className="flex items-center text-gray-400 text-[10px] font-black mt-1 uppercase">
                                    <MapPin size={12} className="mr-1 text-blue-500"/> {m.location || "Lieu inconnu"}
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <span className="block text-green-600 font-black text-xl">{(m.providerAmount || 0).toLocaleString()} F</span>
                        </div>
                    </div>
                    <div className="bg-gray-50 p-4 rounded-2xl mt-4 text-sm text-gray-600 font-medium">
                        {m.category === ServiceCategory.MARKET ? (
                            <div className="flex items-center font-bold"><ShoppingBag size={14} className="mr-2 text-orange-500"/> Marché ({m.marketItems?.length || 0} articles)</div>
                        ) : (
                            <p>{(m.description || 'Pas de description.').substring(0, 100)}...</p>
                        )}
                    </div>
                    <button onClick={() => handleAcceptMission(m.id)} className="w-full mt-6 bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 transition-all active:scale-95">Accepter la mission</button>
                </div>
              );
          })}
          {availableMissions.length === 0 && (
              <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-gray-200">
                  <Info size={32} className="mx-auto text-gray-200 mb-2" />
                  <p className="text-gray-400 font-black text-xs uppercase">Aucune mission disponible pour le moment.</p>
              </div>
          )}
      </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex space-x-1 bg-white p-1.5 rounded-2xl shadow-sm max-w-xl mx-auto border border-gray-100">
        <button onClick={() => setActiveTab('marketplace')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'marketplace' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Missions</button>
        <button onClick={() => setActiveTab('my-missions')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'my-missions' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Mes Travaux</button>
        <button onClick={() => setActiveTab('wallet')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'wallet' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Portefeuille</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'profile' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Profil</button>
      </div>

      <div className="animate-fade-in">
        {activeTab === 'marketplace' && renderMarketplace()}
        {activeTab === 'my-missions' && (
          <div className="space-y-4">
             {myMissions.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-3xl text-gray-400 font-black uppercase text-xs">Vous n'avez pas encore de missions acceptées.</div>
             ) : (
                myMissions.map(m => (
                    <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border-l-8 border-blue-600">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-black text-blue-950">{m.title}</h3>
                            <span className="text-[10px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-full uppercase">{m.status}</span>
                        </div>
                        <p className="text-sm text-gray-500 mb-6">{m.location}</p>
                        <div className="flex gap-2">
                            {m.status === MissionStatus.ACCEPTED && (
                                <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.IN_PROGRESS)} className="flex-1 bg-blue-600 text-white py-3 rounded-xl font-black text-sm">Débuter</button>
                            )}
                            {m.status === MissionStatus.IN_PROGRESS && (
                                <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.COMPLETED)} className="flex-1 bg-green-600 text-white py-3 rounded-xl font-black text-sm">Terminer</button>
                            )}
                        </div>
                    </div>
                ))
             )}
          </div>
        )}
        {activeTab === 'wallet' && (
          <div className="space-y-6">
              <div className="bg-blue-950 text-white p-10 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
                  <p className="text-blue-300 text-xs font-black uppercase tracking-widest">Mon Solde</p>
                  <h2 className="text-5xl font-black mt-2 tracking-tighter">{balance.toLocaleString()} F</h2>
                  <Wallet className="absolute -right-6 -bottom-6 opacity-10" size={180} />
              </div>
              <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100">
                  <h3 className="font-black text-blue-950 mb-6 flex items-center uppercase text-xs tracking-widest">
                      <DollarSign size={18} className="mr-2 text-green-600"/> Nouveau retrait
                  </h3>
                  <div className="flex gap-4">
                      <input type="number" value={withdrawalAmount} onChange={e => setWithdrawalAmount(Number(e.target.value))} className="flex-1 p-4 border border-gray-100 bg-gray-50 rounded-2xl font-black text-2xl outline-none" placeholder="0 F" />
                      <button 
                        onClick={() => { if(withdrawalAmount > 0 && withdrawalAmount <= balance) onRequestWithdrawal(withdrawalAmount, 'Mobile Money'); setWithdrawalAmount(0); }} 
                        className={`px-8 py-4 rounded-2xl font-black text-sm transition-all shadow-xl ${withdrawalAmount > 0 && withdrawalAmount <= balance ? 'bg-green-600 text-white shadow-green-100' : 'bg-gray-100 text-gray-300'}`}
                        disabled={withdrawalAmount <= 0 || withdrawalAmount > balance}
                      >
                        Retirer
                      </button>
                  </div>
              </div>
          </div>
        )}
        {activeTab === 'profile' && (
           <div className="bg-white p-10 rounded-3xl shadow-sm text-center font-black text-blue-950 uppercase text-xs tracking-widest">
               Les modifications du profil seront bientôt disponibles.
           </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { UserRole, User, Mission, MissionStatus, ServiceCategory, Transaction } from './types';
import { BASE_RATES, COMMISSION_RATE, MOCK_USERS, MOCK_MISSIONS, MOCK_TRANSACTIONS } from './constants';
import Auth from './components/Auth';
import Layout from './components/Layout';
import ClientDashboard from './components/ClientDashboard';
import ProviderDashboard from './components/ProviderDashboard';
import AdminDashboard from './components/AdminDashboard';
import { Info } from 'lucide-react';
import { db } from './services/firebase';
import { collection, onSnapshot, doc, updateDoc, setDoc, query, orderBy, deleteDoc, disableNetwork } from "firebase/firestore";

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try { 
      const saved = localStorage.getItem('serviplus_current_user'); 
      return saved ? JSON.parse(saved) : null; 
    } catch (e) { return null; }
  });

  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [missions, setMissions] = useState<Mission[]>(MOCK_MISSIONS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_TRANSACTIONS);
  const [baseRates, setBaseRates] = useState(BASE_RATES);
  const [commissionRate, setCommissionRate] = useState(COMMISSION_RATE);
  const [isOfflineMode, setIsOfflineMode] = useState(() => localStorage.getItem('serviplus_offline_mode') === 'true');
  const [showOfflineBanner, setShowOfflineBanner] = useState(true);

  const enableOfflineMode = async () => {
      setIsOfflineMode(true);
      localStorage.setItem('serviplus_offline_mode', 'true');
      try { await disableNetwork(db); } catch (e) {}
  };

  const retryConnection = () => {
      localStorage.removeItem('serviplus_offline_mode');
      window.location.reload();
  };

  useEffect(() => {
      if (isOfflineMode) return;

      const unsubscribeMissions = onSnapshot(
        query(collection(db, "missions"), orderBy("createdAt", "desc")), 
        (snap) => {
            setMissions(snap.docs.map(d => ({ ...d.data(), id: d.id } as Mission)));
        },
        () => { enableOfflineMode().catch(() => {}); }
      );

      const unsubscribeUsers = onSnapshot(
        collection(db, "users"), 
        (snap) => {
            const loadedUsers = snap.docs.map(d => ({ ...d.data(), id: d.id } as User));
            if(loadedUsers.length > 0) setUsers(loadedUsers);
        },
        () => { enableOfflineMode().catch(() => {}); }
      );

      const unsubscribeTrans = onSnapshot(
        query(collection(db, "transactions"), orderBy("date", "desc")),
        (snap) => setTransactions(snap.docs.map(d => ({ ...d.data(), id: d.id } as Transaction))),
        () => {}
      );

      return () => {
          unsubscribeMissions();
          unsubscribeUsers();
          unsubscribeTrans();
      };
  }, [isOfflineMode]);

  useEffect(() => {
      if (currentUser) {
        localStorage.setItem('serviplus_current_user', JSON.stringify(currentUser));
      } else {
        localStorage.removeItem('serviplus_current_user');
      }
  }, [currentUser]);

  // Handlers
  const handleRegister = async (newUser: User) => {
    setCurrentUser(newUser);
    setUsers(prev => [...prev, newUser]);
    if (!isOfflineMode) {
        try { await setDoc(doc(db, "users", newUser.id), JSON.parse(JSON.stringify(newUser))); } catch (e) { enableOfflineMode().catch(() => {}); }
    }
  };

  const handleUpdateUser = async (updatedData: Partial<User>) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, ...updatedData };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
    if (!isOfflineMode) {
        try { await updateDoc(doc(db, "users", currentUser.id), updatedData); } catch (e) {}
    }
  };

  const handleAddMission = async (newMission: Mission, paymentMethod: string) => {
    setMissions(prev => [newMission, ...prev]);
    const newTx: Transaction = { 
        id: `tx_${Date.now()}`, 
        amount: newMission.totalPrice, 
        type: 'INCOME', 
        userId: newMission.clientId, 
        userName: newMission.clientName, 
        date: new Date().toISOString(), 
        method: paymentMethod as any, 
        status: 'SUCCESS' 
    };
    setTransactions(prev => [newTx, ...prev]);
    if (!isOfflineMode) {
        try { 
            await setDoc(doc(db, "missions", newMission.id), JSON.parse(JSON.stringify(newMission))); 
            await setDoc(doc(db, "transactions", newTx.id), newTx);
        } catch (e) { enableOfflineMode().catch(() => {}); }
    }
  };

  const handleUpdateMissionStatus = async (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => {
      setMissions(prev => prev.map(m => {
          if (m.id !== missionId) return m;
          return { ...m, status, providerId, providerName: providerId ? users.find(u => u.id === providerId)?.name : m.providerName, estimatedArrivalTime: estimation?.arrivalTime, estimatedDistance: estimation?.distance };
      }));
      if (!isOfflineMode) {
          const updates: any = { status };
          if (providerId) {
              updates.providerId = providerId;
              updates.providerName = users.find(u => u.id === providerId)?.name;
          }
          if (estimation) {
              updates.estimatedArrivalTime = estimation.arrivalTime;
              updates.estimatedDistance = estimation.distance;
          }
          try { await updateDoc(doc(db, "missions", missionId), updates); } catch(e){}
      }
  };

  const handleDisputeMission = async (missionId: string, reason: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.DISPUTED, disputeReason: reason } : m));
      if (!isOfflineMode) {
          try { await updateDoc(doc(db, "missions", missionId), { status: MissionStatus.DISPUTED, disputeReason: reason, disputeInitiator: currentUser?.role === UserRole.CLIENT ? 'CLIENT' : 'PROVIDER' }); } catch(e){}
      }
  };

  const handleRate = async (missionId: string, rating: number, comment: string) => {
      if (!currentUser) return;
      const updates: any = currentUser.role === UserRole.CLIENT 
        ? { clientRating: rating, clientComment: comment } 
        : { providerRating: rating, providerComment: comment };

      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, ...updates } : m));
      if (!isOfflineMode) {
          try { await updateDoc(doc(db, "missions", missionId), updates); } catch (e) {}
      }
  };

  const handleValidateMission = async (missionId: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.COMPLETED } : m));
      if (!isOfflineMode) {
          try { await updateDoc(doc(db, "missions", missionId), { status: MissionStatus.COMPLETED, completedAt: new Date().toISOString() }); } catch(e){}
      }
  };

  // Admin Handlers
  const handleResolveDispute = async (missionId: string, resolution: 'REFUND' | 'PAY') => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: resolution === 'PAY' ? MissionStatus.COMPLETED : MissionStatus.CANCELLED } : m));
      if(!isOfflineMode) try { await updateDoc(doc(db, "missions", missionId), { status: resolution === 'PAY' ? MissionStatus.COMPLETED : MissionStatus.CANCELLED }); } catch(e){}
  };

  const handleVerifyUser = async (userId: string, isVerified: boolean) => {
      setUsers(prev => prev.map(u => u.id === userId ? {...u, verified: isVerified} : u));
      if(!isOfflineMode) try { await updateDoc(doc(db, "users", userId), { verified: isVerified }); } catch(e){}
  };

  const handleUpdateSettings = async (rates: Record<ServiceCategory, number>, commission: number) => {
      setBaseRates(rates); setCommissionRate(commission);
      if(!isOfflineMode) try { await setDoc(doc(db, "settings", "global"), { baseRates: rates, commissionRate: commission }, { merge: true }); } catch(e){}
  };

  const handleAddAdmin = async (newAdmin: User) => {
      setUsers(prev => [...prev, newAdmin]);
      if(!isOfflineMode) try { await setDoc(doc(db, "users", newAdmin.id), newAdmin); } catch(e){}
  };

  const handleDeleteUser = async (userId: string) => {
      setUsers(prev => prev.filter(u => u.id !== userId));
      if(!isOfflineMode) try { await deleteDoc(doc(db, "users", userId)); } catch(e){}
  };

  const handleDeleteMission = async (missionId: string) => {
      setMissions(prev => prev.filter(m => m.id !== missionId));
      if(!isOfflineMode) try { await deleteDoc(doc(db, "missions", missionId)); } catch(e){}
  };

  const handleApproveWithdrawal = async (txId: string) => {
      setTransactions(prev => prev.map(t => t.id === txId ? { ...t, status: 'SUCCESS' } : t));
      if(!isOfflineMode) try { await updateDoc(doc(db, "transactions", txId), { status: 'SUCCESS' }); } catch(e){}
  };

  const handleRequestWithdrawal = async (amount: number, method: string) => {
      if (!currentUser) return;
      const newTx: Transaction = { 
          id: `tx_out_${Date.now()}`, 
          amount, 
          type: 'PAYOUT', 
          userId: currentUser.id, 
          userName: currentUser.name, 
          date: new Date().toISOString(), 
          method: method as any, 
          status: 'PENDING_APPROVAL' 
      };
      setTransactions(prev => [newTx, ...prev]);
      if(!isOfflineMode) try { await setDoc(doc(db, "transactions", newTx.id), newTx); } catch(e){}
  };

  if (!currentUser) return <Auth users={users} onLogin={setCurrentUser} onRegister={handleRegister} />;

  return (
    <Layout currentUser={currentUser} onLogout={() => setCurrentUser(null)} isOfflineMode={isOfflineMode} onRetryConnection={retryConnection}>
      {isOfflineMode && showOfflineBanner && (
          <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-xl mb-6 flex items-center justify-between">
              <span className="flex items-center"><Info size={20} className="mr-2"/> Mode Démo (Hors ligne)</span>
              <button onClick={retryConnection} className="bg-white px-3 py-1 rounded border text-xs font-bold">Réessayer</button>
          </div>
      )}
      {currentUser.role === UserRole.CLIENT && (
        <ClientDashboard 
          currentUser={currentUser} 
          missions={missions} 
          onAddMission={handleAddMission} 
          onValidateMission={handleValidateMission} 
          onDisputeMission={handleDisputeMission} 
          onRateMission={handleRate} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onUpdateUser={handleUpdateUser} 
        />
      )}
      {currentUser.role === UserRole.PROVIDER && (
        <ProviderDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDisputeMission={handleDisputeMission} 
          onRateClient={handleRate} 
          onUpdateUser={handleUpdateUser} 
          onRequestWithdrawal={handleRequestWithdrawal} 
        />
      )}
      {currentUser.role === UserRole.ADMIN && (
        <AdminDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onResolveDispute={handleResolveDispute} 
          onVerifyUser={handleVerifyUser} 
          onUpdateSettings={handleUpdateSettings} 
          onAddAdmin={handleAddAdmin} 
          onDeleteUser={handleDeleteUser} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDeleteMission={handleDeleteMission} 
          onApproveWithdrawal={handleApproveWithdrawal} 
        />
      )}
    </Layout>
  );
};

export default App;

