import React, { useState } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, Transaction } from '../types';
import { SERVICE_ICONS } from '../constants';
import { MapPin, Clock, CheckCircle, Star, Phone, Navigation, User as UserIcon, Save, Wallet, DollarSign, ChevronDown, Camera, ShoppingBag, HelpCircle, Loader2, Info } from 'lucide-react';

export interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[];
  transactions: Transaction[];
  onUpdateMissionStatus: (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
  onRequestWithdrawal: (amount: number, method: string) => void;
}

export default function ProviderDashboard({ 
  currentUser, 
  missions = [], 
  users = [], 
  transactions = [], 
  onUpdateMissionStatus, 
  onDisputeMission, 
  onRateClient, 
  onUpdateUser, 
  onRequestWithdrawal 
}: ProviderDashboardProps) {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');

  const [withdrawalAmount, setWithdrawalAmount] = useState<number>(0);

  const myMissions = missions.filter(m => m.providerId === currentUser?.id);
  const availableMissions = missions.filter(m => 
    m.status === MissionStatus.PENDING && 
    !m.providerId && 
    (!currentUser?.city || m.city === currentUser.city) && 
    (!currentUser?.services || currentUser.services.includes(m.category))
  );

  const totalEarnings = myMissions.filter(m => m.status === MissionStatus.COMPLETED).reduce((sum, m) => sum + (m.providerAmount || 0), 0);
  const withdrawn = transactions.filter(t => t.type === 'PAYOUT' && t.userId === currentUser?.id && t.status === 'SUCCESS').reduce((sum, t) => sum + t.amount, 0);
  const balance = Math.max(0, totalEarnings - withdrawn);

  const handleAcceptMission = (missionId: string) => {
      const arrival = new Date(); 
      arrival.setMinutes(arrival.getMinutes() + 30);
      onUpdateMissionStatus(missionId, MissionStatus.ACCEPTED, currentUser.id, { arrivalTime: arrival.toISOString(), distance: 5 });
      setActiveTab('my-missions');
  };

  return (
    <div className="space-y-6">
      <div className="flex space-x-1 bg-white p-1.5 rounded-2xl shadow-sm max-w-xl mx-auto border border-gray-100">
        <button onClick={() => setActiveTab('marketplace')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'marketplace' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Missions</button>
        <button onClick={() => setActiveTab('my-missions')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'my-missions' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Mes Travaux</button>
        <button onClick={() => setActiveTab('wallet')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'wallet' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Portefeuille</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'profile' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Profil</button>
      </div>

      <div className="animate-fade-in">
        {activeTab === 'marketplace' && (
             <div className="space-y-4">
                 {availableMissions.map(m => {
                     const Icon = SERVICE_ICONS[m.category] || HelpCircle;
                     return (
                        <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
                            <div className="flex justify-between items-start">
                                <div className="flex items-center space-x-4">
                                    <div className="p-3 bg-gray-50 rounded-2xl text-blue-600"><Icon size={24} /></div>
                                    <div>
                                        <h3 className="font-black text-lg text-blue-950">{m.title}</h3>
                                        <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{m.location}</div>
                                    </div>
                                </div>
                                <span className="text-green-600 font-black text-xl">{(m.providerAmount || 0).toLocaleString()} F</span>
                            </div>
                            <button onClick={() => handleAcceptMission(m.id)} className="w-full mt-6 bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 transition-all active:scale-95">Accepter la mission</button>
                        </div>
                     );
                 })}
                 {availableMissions.length === 0 && (
                    <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-gray-200">
                        <Info size={32} className="mx-auto text-gray-200 mb-2" />
                        <p className="text-gray-400 font-black text-xs uppercase tracking-widest">Aucune mission disponible</p>
                    </div>
                 )}
             </div>
        )}
        {activeTab === 'wallet' && (
            <div className="bg-blue-950 text-white p-10 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
                <p className="text-blue-300 text-xs font-black uppercase tracking-widest">Mon Solde</p>
