import React, { useState, useEffect } from 'react';
import { UserRole, User, Mission, MissionStatus, ServiceCategory, Transaction } from './types';
import { BASE_RATES, COMMISSION_RATE, MOCK_USERS, MOCK_MISSIONS, MOCK_TRANSACTIONS } from './constants';
import Auth from './components/Auth';
import Layout from './components/Layout';
import ClientDashboard from './components/ClientDashboard';
import ProviderDashboard from './components/ProviderDashboard';
import AdminDashboard from './components/AdminDashboard';
import { Info } from 'lucide-react';
import { db } from './services/firebase';
// Consolidated modular Firestore imports to fix potential named export resolution issues
import { collection, onSnapshot, doc, updateDoc, setDoc, query, orderBy, deleteDoc, disableNetwork } from "firebase/firestore";

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try { 
      const saved = localStorage.getItem('serviplus_current_user'); 
      return saved ? JSON.parse(saved) : null; 
    } catch (e) { return null; }
  });

  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [missions, setMissions] = useState<Mission[]>(MOCK_MISSIONS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_TRANSACTIONS);
  const [baseRates, setBaseRates] = useState(BASE_RATES);
  const [commissionRate, setCommissionRate] = useState(COMMISSION_RATE);
  const [isOfflineMode, setIsOfflineMode] = useState(() => localStorage.getItem('serviplus_offline_mode') === 'true');
  const [showOfflineBanner, setShowOfflineBanner] = useState(true);

  const enableOfflineMode = async () => {
      setIsOfflineMode(true);
      localStorage.setItem('serviplus_offline_mode', 'true');
      try { await disableNetwork(db); } catch (e) {}
  };

  const retryConnection = () => {
      localStorage.removeItem('serviplus_offline_mode');
      window.location.reload();
  };

  useEffect(() => {
      if (isOfflineMode) return;

      const unsubscribeMissions = onSnapshot(
        query(collection(db, "missions"), orderBy("createdAt", "desc")), 
        (snap) => {
            setMissions(snap.docs.map(d => ({ ...d.data(), id: d.id } as Mission)));
        },
        () => { enableOfflineMode().catch(() => {}); }
      );

      const unsubscribeUsers = onSnapshot(
        collection(db, "users"), 
        (snap) => {
            const loadedUsers = snap.docs.map(d => ({ ...d.data(), id: d.id } as User));
            if(loadedUsers.length > 0) setUsers(loadedUsers);
        },
        () => { enableOfflineMode().catch(() => {}); }
      );

      const unsubscribeTrans = onSnapshot(
        query(collection(db, "transactions"), orderBy("date", "desc")),
        (snap) => setTransactions(snap.docs.map(d => ({ ...d.data(), id: d.id } as Transaction))),
        () => {}
      );

      return () => {
          unsubscribeMissions();
          unsubscribeUsers();
          unsubscribeTrans();
      };
  }, [isOfflineMode]);

  useEffect(() => {
      if (currentUser) {
        localStorage.setItem('serviplus_current_user', JSON.stringify(currentUser));
      } else {
        localStorage.removeItem('serviplus_current_user');
      }
  }, [currentUser]);

  // Handlers
  const handleRegister = async (newUser: User) => {
    setCurrentUser(newUser);
    setUsers(prev => [...prev, newUser]);
    if (!isOfflineMode) {
        try { await setDoc(doc(db, "users", newUser.id), JSON.parse(JSON.stringify(newUser))); } catch (e) { enableOfflineMode().catch(() => {}); }
    }
  };

  const handleUpdateUser = async (updatedData: Partial<User>) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, ...updatedData };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
    if (!isOfflineMode) {
        try { await updateDoc(doc(db, "users", currentUser.id), updatedData); } catch (e) {}
    }
  };

  const handleAddMission = async (newMission: Mission, paymentMethod: string) => {
    setMissions(prev => [newMission, ...prev]);
    const newTx: Transaction = { 
        id: `tx_${Date.now()}`, 
        amount: newMission.totalPrice, 
        type: 'INCOME', 
        userId: newMission.clientId, 
        userName: newMission.clientName, 
        date: new Date().toISOString(), 
        method: paymentMethod as any, 
        status: 'SUCCESS' 
    };
    setTransactions(prev => [newTx, ...prev]);
    if (!isOfflineMode) {
        try { 
            await setDoc(doc(db, "missions", newMission.id), JSON.parse(JSON.stringify(newMission))); 
            await setDoc(doc(db, "transactions", newTx.id), newTx);
        } catch (e) { enableOfflineMode().catch(() => {}); }
    }
  };

  const handleUpdateMissionStatus = async (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => {
      setMissions(prev => prev.map(m => {
          if (m.id !== missionId) return m;
          return { ...m, status, providerId, providerName: providerId ? users.find(u => u.id === providerId)?.name : m.providerName, estimatedArrivalTime: estimation?.arrivalTime, estimatedDistance: estimation?.distance };
      }));
      if (!isOfflineMode) {
          const updates: any = { status };
          if (providerId) {
              updates.providerId = providerId;
              updates.providerName = users.find(u => u.id === providerId)?.name;
          }
          if (estimation) {
              updates.estimatedArrivalTime = estimation.arrivalTime;
              updates.estimatedDistance = estimation.distance;
          }
          try { await updateDoc(doc(db, "missions", missionId), updates); } catch(e){}
      }
  };

  const handleDisputeMission = async (missionId: string, reason: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.DISPUTED, disputeReason: reason } : m));
      if (!isOfflineMode) {
          try { await updateDoc(doc(db, "missions", missionId), { status: MissionStatus.DISPUTED, disputeReason: reason, disputeInitiator: currentUser?.role === UserRole.CLIENT ? 'CLIENT' : 'PROVIDER' }); } catch(e){}
      }
  };

  const handleRate = async (missionId: string, rating: number, comment: string) => {
      if (!currentUser) return;
      const updates: any = currentUser.role === UserRole.CLIENT 
        ? { clientRating: rating, clientComment: comment } 
        : { providerRating: rating, providerComment: comment };

      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, ...updates } : m));
      if (!isOfflineMode) {
          try { await updateDoc(doc(db, "missions", missionId), updates); } catch (e) {}
      }
  };

  const handleValidateMission = async (missionId: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.COMPLETED } : m));
      if (!isOfflineMode) {
          try { await updateDoc(doc(db, "missions", missionId), { status: MissionStatus.COMPLETED, completedAt: new Date().toISOString() }); } catch(e){}
      }
  };

  // Admin Handlers
  const handleResolveDispute = async (missionId: string, resolution: 'REFUND' | 'PAY') => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: resolution === 'PAY' ? MissionStatus.COMPLETED : MissionStatus.CANCELLED } : m));
      if(!isOfflineMode) try { await updateDoc(doc(db, "missions", missionId), { status: resolution === 'PAY' ? MissionStatus.COMPLETED : MissionStatus.CANCELLED }); } catch(e){}
  };

  const handleVerifyUser = async (userId: string, isVerified: boolean) => {
      setUsers(prev => prev.map(u => u.id === userId ? {...u, verified: isVerified} : u));
      if(!isOfflineMode) try { await updateDoc(doc(db, "users", userId), { verified: isVerified }); } catch(e){}
  };

  const handleUpdateSettings = async (rates: Record<ServiceCategory, number>, commission: number) => {
      setBaseRates(rates); setCommissionRate(commission);
      if(!isOfflineMode) try { await setDoc(doc(db, "settings", "global"), { baseRates: rates, commissionRate: commission }, { merge: true }); } catch(e){}
  };

  const handleAddAdmin = async (newAdmin: User) => {
      setUsers(prev => [...prev, newAdmin]);
      if(!isOfflineMode) try { await setDoc(doc(db, "users", newAdmin.id), newAdmin); } catch(e){}
  };

  const handleDeleteUser = async (userId: string) => {
      setUsers(prev => prev.filter(u => u.id !== userId));
      if(!isOfflineMode) try { await deleteDoc(doc(db, "users", userId)); } catch(e){}
  };

  const handleDeleteMission = async (missionId: string) => {
      setMissions(prev => prev.filter(m => m.id !== missionId));
      if(!isOfflineMode) try { await deleteDoc(doc(db, "missions", missionId)); } catch(e){}
  };

  const handleApproveWithdrawal = async (txId: string) => {
      setTransactions(prev => prev.map(t => t.id === txId ? { ...t, status: 'SUCCESS' } : t));
      if(!isOfflineMode) try { await updateDoc(doc(db, "transactions", txId), { status: 'SUCCESS' }); } catch(e){}
  };

  const handleRequestWithdrawal = async (amount: number, method: string) => {
      if (!currentUser) return;
      const newTx: Transaction = { 
          id: `tx_out_${Date.now()}`, 
          amount, 
          type: 'PAYOUT', 
          userId: currentUser.id, 
          userName: currentUser.name, 
          date: new Date().toISOString(), 
          method: method as any, 
          status: 'PENDING_APPROVAL' 
      };
      setTransactions(prev => [newTx, ...prev]);
      if(!isOfflineMode) try { await setDoc(doc(db, "transactions", newTx.id), newTx); } catch(e){}
  };

  if (!currentUser) return <Auth users={users} onLogin={setCurrentUser} onRegister={handleRegister} />;

  return (
    <Layout currentUser={currentUser} onLogout={() => setCurrentUser(null)} isOfflineMode={isOfflineMode} onRetryConnection={retryConnection}>
      {isOfflineMode && showOfflineBanner && (
          <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-xl mb-6 flex items-center justify-between">
              <span className="flex items-center"><Info size={20} className="mr-2"/> Mode Démo (Hors ligne)</span>
              <button onClick={retryConnection} className="bg-white px-3 py-1 rounded border text-xs font-bold">Réessayer</button>
          </div>
      )}
      {currentUser.role === UserRole.CLIENT && (
        <ClientDashboard 
          currentUser={currentUser} 
          missions={missions} 
          onAddMission={handleAddMission} 
          onValidateMission={handleValidateMission} 
          onDisputeMission={handleDisputeMission} 
          onRateMission={handleRate} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onUpdateUser={handleUpdateUser} 
        />
      )}
      {currentUser.role === UserRole.PROVIDER && (
        <ProviderDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDisputeMission={handleDisputeMission} 
          onRateClient={handleRate} 
          onUpdateUser={handleUpdateUser} 
          onRequestWithdrawal={handleRequestWithdrawal} 
        />
      )}
      {currentUser.role === UserRole.ADMIN && (
        <AdminDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onResolveDispute={handleResolveDispute} 
          onVerifyUser={handleVerifyUser} 
          onUpdateSettings={handleUpdateSettings} 
          onAddAdmin={handleAddAdmin} 
          onDeleteUser={handleDeleteUser} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDeleteMission={handleDeleteMission} 
          onApproveWithdrawal={handleApproveWithdrawal} 
        />
      )}
    </Layout>
  );
};

