import React, { useState, useEffect } from 'react';
import { UserRole, User, Mission, MissionStatus, ServiceCategory, Transaction } from './types';
import { BASE_RATES, COMMISSION_RATE, MOCK_USERS, MOCK_MISSIONS, MOCK_TRANSACTIONS } from './constants';
import Auth from './components/Auth';
import Layout from './components/Layout';
import ClientDashboard from './components/ClientDashboard';
import ProviderDashboard from './components/ProviderDashboard';
import AdminDashboard from './components/AdminDashboard';
import { Info } from 'lucide-react';
import { db } from './services/firebase';
// Consolidated modular Firestore imports to fix potential named export resolution issues
import { collection, onSnapshot, doc, updateDoc, setDoc, query, orderBy, deleteDoc, disableNetwork } from "firebase/firestore";

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try { 
      const saved = localStorage.getItem('serviplus_current_user'); 
      return saved ? JSON.parse(saved) : null; 
    } catch (e) { return null; }
  });

  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [missions, setMissions] = useState<Mission[]>(MOCK_MISSIONS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_TRANSACTIONS);
  const [baseRates, setBaseRates] = useState(BASE_RATES);
  const [commissionRate, setCommissionRate] = useState(COMMISSION_RATE);
  const [isOfflineMode, setIsOfflineMode] = useState(() => localStorage.getItem('serviplus_offline_mode') === 'true');

  const enableOfflineMode = async () => {
      setIsOfflineMode(true);
      localStorage.setItem('serviplus_offline_mode', 'true');
      try { await disableNetwork(db); } catch (e) {}
  };

  const retryConnection = () => {
      localStorage.removeItem('serviplus_offline_mode');
      window.location.reload();
  };

  useEffect(() => {
      if (isOfflineMode) return;
      const unsubscribeMissions = onSnapshot(query(collection(db, "missions"), orderBy("createdAt", "desc")), 
        (snap) => setMissions(snap.docs.map(d => ({ ...d.data(), id: d.id } as Mission))), 
        enableOfflineMode
      );
      const unsubscribeUsers = onSnapshot(collection(db, "users"), 
        (snap) => {
            const loadedUsers = snap.docs.map(d => ({ ...d.data(), id: d.id } as User));
            if(loadedUsers.length > 0) setUsers(loadedUsers);
        },
        enableOfflineMode
      );
      const unsubscribeTrans = onSnapshot(query(collection(db, "transactions"), orderBy("date", "desc")),
        (snap) => setTransactions(snap.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)))
      );

      return () => {
          unsubscribeMissions();
          unsubscribeUsers();
          unsubscribeTrans();
      };
  }, [isOfflineMode]);

  // Handlers
  const handleRegister = async (newUser: User) => {
    setCurrentUser(newUser);
    setUsers(prev => [...prev, newUser]);
    if (!isOfflineMode) { try { await setDoc(doc(db, "users", newUser.id), JSON.parse(JSON.stringify(newUser))); } catch (e) {} }
  };

  const handleUpdateUser = async (updatedData: Partial<User>) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, ...updatedData };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
    if (!isOfflineMode) { try { await updateDoc(doc(db, "users", currentUser.id), updatedData); } catch (e) {} }
  };

  const handleAddMission = async (newMission: Mission, paymentMethod: string) => {
    setMissions(prev => [newMission, ...prev]);
    if (!isOfflineMode) { try { await setDoc(doc(db, "missions", newMission.id), JSON.parse(JSON.stringify(newMission))); } catch (e) {} }
  };

  const handleUpdateMissionStatus = async (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => {
      setMissions(prev => prev.map(m => (m.id === missionId ? { ...m, status, providerId, providerName: providerId ? users.find(u => u.id === providerId)?.name : m.providerName } : m)));
      if (!isOfflineMode) { try { await updateDoc(doc(db, "missions", missionId), { status, providerId }); } catch(e){} }
  };

  const handleDisputeMission = async (missionId: string, reason: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.DISPUTED, disputeReason: reason } : m));
  };

  const handleRate = async (missionId: string, rating: number, comment: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, clientRating: rating, clientComment: comment } : m));
  };

  const handleValidateMission = async (missionId: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.COMPLETED } : m));
  };

  // Admin Handlers Placeholder
  const handleResolveDispute = (id: string, res: 'REFUND' | 'PAY') => {};
  const handleVerifyUser = (id: string, v: boolean) => {};
  const handleUpdateSettings = (r: any, c: number) => {};
  const handleAddAdmin = (u: User) => {};
  const handleDeleteUser = (id: string) => {};
  const handleDeleteMission = (id: string) => {};
  const handleApproveWithdrawal = (id: string) => {};
  const handleRequestWithdrawal = (amount: number, method: string) => {};

  if (!currentUser) return <Auth users={users} onLogin={setCurrentUser} onRegister={handleRegister} />;

  return (
    <Layout currentUser={currentUser} onLogout={() => setCurrentUser(null)} isOfflineMode={isOfflineMode} onRetryConnection={retryConnection}>
      {currentUser.role === UserRole.CLIENT && (
        <ClientDashboard 
          currentUser={currentUser} 
          missions={missions} 
          onAddMission={handleAddMission} 
          onValidateMission={handleValidateMission} 
          onDisputeMission={handleDisputeMission} 
          onRateMission={handleRate} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onUpdateUser={handleUpdateUser} 
        />
      )}
      {currentUser.role === UserRole.PROVIDER && (
        <ProviderDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDisputeMission={handleDisputeMission} 
          onRateClient={handleRate} 
          onUpdateUser={handleUpdateUser} 
          onRequestWithdrawal={handleRequestWithdrawal} 
        />
      )}
      {currentUser.role === UserRole.ADMIN && (
        <AdminDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onResolveDispute={handleResolveDispute} 
          onVerifyUser={handleVerifyUser} 
          onUpdateSettings={handleUpdateSettings} 
          onAddAdmin={handleAddAdmin} 
          onDeleteUser={handleDeleteUser} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDeleteMission={handleDeleteMission} 
          onApproveWithdrawal={handleApproveWithdrawal} 
        />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { UserRole, User, ServiceCategory } from '../types';
import { Eye, EyeOff, Lock, Phone, AlertCircle, Loader2, MapPin, Camera, Shield, Smartphone, ChevronDown, CheckCircle, LayoutGrid } from 'lucide-react';
import { uploadImage, auth, RecaptchaVerifier } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  multiFactor,
  PhoneAuthProvider,
  PhoneMultiFactorGenerator,
  getMultiFactorResolver
} from "firebase/auth";
import { CITIES, SERVICE_ICONS } from '../constants';

const BACKGROUND_IMAGE = "https://images.unsplash.com/photo-1581578731117-104f2a41272c?q=80&w=2070&auto=format&fit=crop";

interface AuthProps {
  users: User[];
  onLogin: (user: User) => void;
  onRegister: (newUser: User) => void;
}

export default function Auth({ users, onLogin, onRegister }: AuthProps) {
  const [viewMode, setViewMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [authStep, setAuthStep] = useState<'FORM' | 'MFA_CHALLENGE'>('FORM');
  const [verificationCode, setVerificationCode] = useState(['', '', '', '', '', '']);

  const [mfaResolver, setMfaResolver] = useState<any>(null);
  const [verificationId, setVerificationId] = useState<string>('');
  const recaptchaVerifierRef = useRef<any>(null);

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    city: 'Abidjan',
    password: '',
    confirmPassword: '',
    role: UserRole.CLIENT,
    address: '',
    idNumber: '',
    acceptTerms: false
  });

  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>([]);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [idCardRectoFile, setIdCardRectoFile] = useState<File | null>(null);
  const [idCardVersoFile, setIdCardVersoFile] = useState<File | null>(null);

  useEffect(() => {
    return () => {
      if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
      }
    };
  }, []);

  const setupRecaptcha = () => {
    if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
    }
    const container = document.getElementById('recaptcha-container');
    if (container) container.innerHTML = '';

    const verifier = new RecaptchaVerifier(auth, 'recaptcha-container', { 'size': 'invisible' });
    recaptchaVerifierRef.current = verifier;
    return verifier;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const value = e.target.type === 'checkbox' ? (e.target as HTMLInputElement).checked : e.target.value;
    setFormData({ ...formData, [e.target.name]: value });
    setError('');
  };

  const toggleService = (service: ServiceCategory) => {
    if (selectedServices.includes(service)) {
      setSelectedServices(selectedServices.filter(s => s !== service));
    } else {
      setSelectedServices([...selectedServices, service]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'AVATAR' | 'ID_RECTO' | 'ID_VERSO') => {
    const file = e.target.files?.[0];
    if (file) {
      if (type === 'AVATAR') {
          setAvatarFile(file);
          const reader = new FileReader();
          reader.onloadend = () => setAvatarPreview(reader.result as string);
          reader.readAsDataURL(file);
      } else if (type === 'ID_RECTO') setIdCardRectoFile(file);
      else if (type === 'ID_VERSO') setIdCardVersoFile(file);
    }
  };

  const handleCodeChange = (index: number, value: string) => {
      if (!/^\d*$/.test(value)) return;
      const newCode = [...verificationCode];
      newCode[index] = value.slice(-1);
      setVerificationCode(newCode);
      if (value && index < 5) document.getElementById(`code-${index + 1}`)?.focus();
  };

  const handleAuthSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');
      setLoading(true);

      const email = formData.email || `${formData.phone}@serviplus.ci`;

      try {
          if (viewMode === 'REGISTER') {
              if (!formData.acceptTerms) throw new Error("Vous devez accepter les conditions.");
              if (!avatarFile || !idCardRectoFile || !idCardVersoFile) throw new Error("Documents requis.");
              if (formData.password !== formData.confirmPassword) throw new Error("Mots de passe différents.");
              if (formData.role === UserRole.PROVIDER && selectedServices.length === 0) throw new Error("Sélectionnez au moins une compétence.");

              const userCredential = await createUserWithEmailAndPassword(auth, email, formData.password);
              const user = userCredential.user;

              const appVerifier = setupRecaptcha();
              const mfaSession = await multiFactor(user).getSession();
              const phoneOpts = { phoneNumber: `+225${formData.phone}`, session: mfaSession };
              const phoneProvider = new PhoneAuthProvider(auth);
              const vId = await phoneProvider.verifyPhoneNumber(phoneOpts, appVerifier);

              setVerificationId(vId);
              setAuthStep('MFA_CHALLENGE');
              setLoading(false);
          } else {
              try {
                  await signInWithEmailAndPassword(auth, email, formData.password);
                  const dbUser = users.find(u => u.phone === formData.phone);
                  if (dbUser) onLogin(dbUser);
                  else throw new Error("Utilisateur non trouvé dans la base de données.");
              } catch (err: any) {
                  if (err.code === 'auth/multi-factor-auth-required') {
                      const resolver = getMultiFactorResolver(auth, err);
                      setMfaResolver(resolver);
                      const appVerifier = setupRecaptcha();
                      const phoneProvider = new PhoneAuthProvider(auth);
                      const vId = await phoneProvider.verifyPhoneNumber({
                          multiFactorHint: resolver.hints[0],
                          session: resolver.session
                      }, appVerifier);
                      setVerificationId(vId);
                      setAuthStep('MFA_CHALLENGE');
                      setLoading(false);
                  } else throw err;
              }
          }
      } catch (err: any) {
          setError(err.message || "Une erreur est survenue");
          setLoading(false);
      }
  };

  const finalizeMfa = async (e: React.FormEvent) => {
      e.preventDefault();
      setLoading(true);
      const code = verificationCode.join('');

      try {
          const cred = PhoneAuthProvider.credential(verificationId, code);
          const assertion = PhoneMultiFactorGenerator.assertion(cred);

          if (viewMode === 'REGISTER') {
              await multiFactor(auth.currentUser!).enroll(assertion, "Mobile Principal");
              const avatarUrl = await uploadImage(avatarFile!, `avatars/${formData.phone}`);
              const newUser: User = {
                  id: auth.currentUser!.uid,
                  name: formData.name,
                  email: formData.email || `${formData.phone}@serviplus.ci`,
                  phone: formData.phone,
                  role: formData.role,
                  city: formData.city,
                  address: formData.address,
                  avatarUrl: avatarUrl,
                  services: formData.role === UserRole.PROVIDER ? selectedServices : undefined,
                  verified: false,
                  walletBalance: 0,
                  createdAt: new Date().toISOString()
              };
              onRegister(newUser);
          } else {
              await mfaResolver.resolveSignIn(assertion);
              const dbUser = users.find(u => u.phone === formData.phone);
              if (dbUser) onLogin(dbUser);
          }
      } catch (err: any) {
          setError("Code invalide.");
          setLoading(false);
      }
  };

  if (authStep === 'MFA_CHALLENGE') {
      return (
          <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 relative font-sans">
              <div className="absolute inset-0 bg-blue-900/70 backdrop-blur-md"></div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md relative z-10 animate-scale-in border border-white/20">
                  <div className="text-center mb-10">
                      <div className="bg-blue-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-inner">
                          <Shield className="text-blue-600" size={40} />
                      </div>
                      <h2 className="text-3xl font-black text-gray-900">Vérification</h2>
                      <p className="text-gray-500 mt-3 text-sm font-medium">Identity Platform : Entrez le code SMS reçu.</p>
                  </div>

                  {error && <div className="bg-red-50 text-red-600 p-4 rounded-2xl mb-8 text-sm flex items-center border border-red-100 font-bold"><AlertCircle size={18} className="mr-2" />{error}</div>}

                  <form onSubmit={finalizeMfa}>
                      <div className="flex justify-between gap-2 mb-10">
                          {verificationCode.map((digit, index) => (
                              <input key={index} id={`code-${index}`} type="text" maxLength={1} value={digit} onChange={(e) => handleCodeChange(index, e.target.value)} className="w-12 h-16 text-center text-2xl font-black border-2 border-gray-100 rounded-2xl focus:border-blue-500 focus:bg-blue-50/50 outline-none transition-all shadow-sm" />
                          ))}
                      </div>
                      <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white py-5 rounded-[1.5rem] font-black text-lg shadow-xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center">
                          {loading ? <Loader2 className="animate-spin" /> : "Confirmer l'identité"}
                      </button>
                  </form>
                  <div id="recaptcha-container"></div>
              </div>
          </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900 p-4 relative overflow-hidden font-sans">
        <div className="absolute inset-0 z-0 opacity-40">
             <img src={BACKGROUND_IMAGE} alt="Bg" className="w-full h-full object-cover" />
             <div className="absolute inset-0 bg-gradient-to-b from-blue-900 via-transparent to-blue-900"></div>
        </div>

        <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-lg relative z-10 overflow-hidden animate-scale-in flex flex-col max-h-[92vh]">
            <div className="pt-10 pb-6 px-10 text-center">
                 <div className="w-20 h-20 bg-blue-600 rounded-[2rem] flex items-center justify-center text-white font-black text-3xl mx-auto mb-4 shadow-2xl shadow-blue-200 animate-float">S+</div>
                 <h1 className="text-3xl font-black text-blue-950">Servi<span className="text-orange-500">+</span> <span className="text-[10px] bg-blue-100 text-blue-600 px-3 py-1 rounded-full align-middle ml-1 uppercase tracking-widest font-bold">Identity</span></h1>
                 <p className="text-gray-400 text-sm mt-2 font-medium">La plateforme de services la plus sécurisée d'Abidjan</p>
            </div>

            <div className="px-10 pb-10 overflow-y-auto custom-scrollbar flex-1">
                <div className="flex bg-gray-50 p-1.5 rounded-[1.5rem] mb-8 border border-gray-100">
                    <button onClick={() => setViewMode('LOGIN')} className={`flex-1 py-3 text-sm font-black rounded-[1rem] transition-all ${viewMode === 'LOGIN' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}>Connexion</button>
                    <button onClick={() => setViewMode('REGISTER')} className={`flex-1 py-3 text-sm font-black rounded-[1rem] transition-all ${viewMode === 'REGISTER' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}>Inscription</button>
                </div>

                {error && <div className="bg-red-50 text-red-600 p-4 rounded-2xl mb-6 text-xs font-bold border border-red-100 flex items-center animate-shake"><AlertCircle size={14} className="mr-2"/>{error}</div>}

                <form onSubmit={handleAuthSubmit} className="space-y-5">
                    {viewMode === 'REGISTER' && (
                        <>
                            <div className="grid grid-cols-2 gap-4">
                                <button type="button" onClick={() => setFormData({...formData, role: UserRole.CLIENT})} className={`p-4 rounded-2xl border-2 font-black text-xs transition-all ${formData.role === UserRole.CLIENT ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-100 text-gray-400'}`}>Je suis Client</button>
                                <button type="button" onClick={() => setFormData({...formData, role: UserRole.PROVIDER})} className={`p-4 rounded-2xl border-2 font-black text-xs transition-all ${formData.role === UserRole.PROVIDER ? 'border-orange-500 bg-orange-50 text-orange-700' : 'border-gray-100 text-gray-400'}`}>Je suis Prestataire</button>
                            </div>
                            <div className="flex flex-col items-center">
                                <div className="relative w-24 h-24 group">
                                    <div className={`w-full h-full rounded-full overflow-hidden border-4 ${avatarPreview ? 'border-blue-500' : 'border-gray-100'} bg-gray-50 flex items-center justify-center transition-all`}>
                                        {avatarPreview ? <img src={avatarPreview} alt="Av" className="w-full h-full object-cover" /> : <Camera size={32} className="text-gray-300" />}
                                    </div>
                                    <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'AVATAR')} className="absolute inset-0 opacity-0 cursor-pointer" />
                                </div>
                                <span className="text-[10px] font-black text-gray-400 mt-2 uppercase">Photo de profil requise</span>
                            </div>
                            <input type="text" name="name" placeholder="Nom et Prénoms" value={formData.name} onChange={handleChange} className="w-full p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold focus:bg-white focus:border-blue-500 transition-all outline-none" required />
                        </>
                    )}

                    <div className="relative">
                        <Smartphone className="absolute left-4 top-4 text-gray-300" size={20} />
                        <input type="tel" name="phone" placeholder="Numéro Mobile (ex: 07...)" value={formData.phone} onChange={handleChange} className="w-full pl-12 p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-black focus:bg-white focus:border-blue-500 outline-none" required />
                    </div>

                    {viewMode === 'REGISTER' && (
                        <>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="relative">
                                    <select name="city" value={formData.city} onChange={handleChange} className="w-full p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-black appearance-none focus:bg-white outline-none">
                                        {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
                                    </select>
                                    <ChevronDown className="absolute right-4 top-4 text-gray-400 pointer-events-none" size={20} />
                                </div>
                                <input type="text" name="address" placeholder="Quartier" value={formData.address} onChange={handleChange} className="w-full p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-black focus:bg-white outline-none" />
                            </div>

                            {formData.role === UserRole.PROVIDER && (
                                <div className="bg-orange-50/50 p-5 rounded-3xl border border-orange-100/50">
                                    <h3 className="text-[10px] font-black text-orange-600 uppercase tracking-widest mb-4 flex items-center">
                                        <LayoutGrid size={14} className="mr-2"/> Mes Compétences (Sélectionnez)
                                    </h3>
                                    <div className="grid grid-cols-2 gap-2">
                                        {Object.values(ServiceCategory).filter(c => c !== ServiceCategory.MARKET).map(cat => (
                                            <button
                                                key={cat}
                                                type="button"
                                                onClick={() => toggleService(cat)}
                                                className={`p-2.5 rounded-xl text-[10px] font-black uppercase transition-all border ${selectedServices.includes(cat) ? 'bg-orange-500 text-white border-orange-600 shadow-md' : 'bg-white text-gray-400 border-gray-100 hover:bg-gray-50'}`}
                                            >
                                                {cat}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </>
                    )}

                    <div className="relative">
                        <Lock className="absolute left-4 top-4 text-gray-300" size={20} />
                        <input type={showPassword ? "text" : "password"} name="password" placeholder="Mot de passe" value={formData.password} onChange={handleChange} className="w-full pl-12 pr-12 p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-black focus:bg-white outline-none" required />
                        <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-4 text-gray-300">{showPassword ? <EyeOff size={20} /> : <Eye size={20} />}</button>
                    </div>

                    {viewMode === 'REGISTER' && (
                        <>
                         <div className="relative">
                            <Lock className="absolute left-4 top-4 text-gray-300" size={20} />
                            <input type="password" name="confirmPassword" placeholder="Confirmer mot de passe" value={formData.confirmPassword} onChange={handleChange} className="w-full pl-12 p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-black focus:bg-white outline-none" required />
                         </div>

                         <div className="bg-gray-50 p-5 rounded-3xl border border-gray-100">
                            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Vérification CNI</h3>
                            <input type="text" name="idNumber" placeholder="Numéro de pièce" value={formData.idNumber} onChange={handleChange} className="w-full p-3 border border-gray-100 rounded-xl text-xs font-black mb-4 bg-white" required />
                            <div className="grid grid-cols-2 gap-3">
                                <div className={`relative border-2 border-dashed rounded-2xl p-3 flex flex-col items-center justify-center h-24 transition-all ${idCardRectoFile ? 'border-green-500 bg-green-50' : 'border-gray-200 bg-white'}`}>
                                    <span className="text-[10px] font-black uppercase text-gray-400 mb-2">Recto</span>
                                    {idCardRectoFile ? <CheckCircle className="text-green-500" /> : <Camera className="text-gray-300" />}
                                    <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'ID_RECTO')} className="absolute inset-0 opacity-0 cursor-pointer" />
                                </div>
                                <div className={`relative border-2 border-dashed rounded-2xl p-3 flex flex-col items-center justify-center h-24 transition-all ${idCardVersoFile ? 'border-green-500 bg-green-50' : 'border-gray-200 bg-white'}`}>
                                    <span className="text-[10px] font-black uppercase text-gray-400 mb-2">Verso</span>
                                    {idCardVersoFile ? <CheckCircle className="text-green-500" /> : <Camera className="text-gray-300" />}
                                    <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'ID_VERSO')} className="absolute inset-0 opacity-0 cursor-pointer" />
                                </div>
                            </div>
                        </div>

                        <label className="flex items-center space-x-3 p-2 cursor-pointer group">
                            <input type="checkbox" name="acceptTerms" checked={formData.acceptTerms} onChange={handleChange} className="w-5 h-5 rounded-lg border-gray-300 text-blue-600 focus:ring-blue-500" />
                            <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter group-hover:text-gray-600 transition-colors">J'accepte les conditions d'utilisation</span>
                        </label>
                        </>
                    )}

                    <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white py-5 rounded-[1.5rem] font-black shadow-xl shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all flex justify-center items-center">
                        {loading ? <Loader2 className="animate-spin" /> : (viewMode === 'LOGIN' ? "Se connecter" : "Créer mon compte")}
                    </button>
                    <div id="recaptcha-container"></div>
                </form>

                <p className="mt-8 text-center text-xs text-gray-400 font-bold">
                    {viewMode === 'LOGIN' ? "Nouveau sur Servi+ ?" : "Déjà membre ?"}{' '}
                    <button onClick={() => setViewMode(viewMode === 'LOGIN' ? 'REGISTER' : 'LOGIN')} className="text-blue-600 uppercase tracking-wider underline underline-offset-4 ml-1">Cliquez ici</button>
                </p>
            </div>
        </div>
    </div>
  );
}

import React, { useState } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, Transaction } from '../types';
import { SERVICE_ICONS } from '../constants';
import { MapPin, Clock, CheckCircle, Star, Phone, Navigation, User as UserIcon, Save, Wallet, DollarSign, ChevronDown, Camera, ShoppingBag, HelpCircle, Loader2, Info } from 'lucide-react';

export interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[];
  transactions: Transaction[];
  onUpdateMissionStatus: (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
  onRequestWithdrawal: (amount: number, method: string) => void;
}

export default function ProviderDashboard({ 
  currentUser, 
  missions = [], 
  users = [], 
  transactions = [], 
  onUpdateMissionStatus, 
  onDisputeMission, 
  onRateClient, 
  onUpdateUser, 
  onRequestWithdrawal 
}: ProviderDashboardProps) {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');

  const [withdrawalAmount, setWithdrawalAmount] = useState<number>(0);

  // Sécurité : S'assurer que les propriétés critiques existent pour éviter l'écran blanc
  const userServices = currentUser?.services || [];
  const userCity = currentUser?.city || 'Abidjan';

  const myMissions = (missions || []).filter(m => m.providerId === currentUser?.id);

  // Filtrage robuste des missions disponibles
  const availableMissions = (missions || []).filter(m => 
    m.status === MissionStatus.PENDING && 
    !m.providerId && 
    (!userCity || m.city === userCity) && 
    (userServices.length === 0 || userServices.includes(m.category))
  );

  const totalEarnings = myMissions.filter(m => m.status === MissionStatus.COMPLETED).reduce((sum, m) => sum + (m.providerAmount || 0), 0);
  const withdrawn = (transactions || []).filter(t => t.type === 'PAYOUT' && t.userId === currentUser?.id && t.status === 'SUCCESS').reduce((sum, t) => sum + t.amount, 0);
  const balance = Math.max(0, totalEarnings - withdrawn);

  const handleAcceptMission = (missionId: string) => {
      if (!currentUser?.id) return;
      const arrival = new Date(); 
      arrival.setMinutes(arrival.getMinutes() + 30);
      onUpdateMissionStatus(missionId, MissionStatus.ACCEPTED, currentUser.id, { arrivalTime: arrival.toISOString(), distance: 5 });
      setActiveTab('my-missions');
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Navigation Mobile / Desktop Tabs */}
      <div className="flex space-x-1 bg-white p-1.5 rounded-2xl shadow-sm max-w-xl mx-auto border border-gray-100">
        <button onClick={() => setActiveTab('marketplace')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'marketplace' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Missions</button>
        <button onClick={() => setActiveTab('my-missions')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'my-missions' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Mes Travaux</button>
