import React, { useState, useEffect, useRef } from 'react';
import { UserRole, User, ServiceCategory } from '../types';
import { Eye, EyeOff, Lock, Phone, AlertCircle, Loader2, MapPin, Camera, Shield, Smartphone, ChevronDown, CheckCircle, LayoutGrid } from 'lucide-react';
import { uploadImage, auth, RecaptchaVerifier } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  multiFactor,
  PhoneAuthProvider,
  PhoneMultiFactorGenerator,
  getMultiFactorResolver
} from "firebase/auth";
import { CITIES } from '../constants';

const BACKGROUND_IMAGE = "https://images.unsplash.com/photo-1581578731117-104f2a41272c?q=80&w=2070&auto=format&fit=crop";

// Liste explicite des catégories pour éviter les bugs d'énumération
const AVAILABLE_SERVICES = [
    ServiceCategory.CLEANING,
    ServiceCategory.COOKING,
    ServiceCategory.ELDERLY_CARE,
    ServiceCategory.GARDENING,
    ServiceCategory.LAUNDRY,
    ServiceCategory.BABYSITTING,
    ServiceCategory.HANDYMAN // Bricolage est bien ici
];

interface AuthProps {
  users: User[];
  onLogin: (user: User) => void;
  onRegister: (newUser: User) => void;
}

export default function Auth({ users, onLogin, onRegister }: AuthProps) {
  const [viewMode, setViewMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [authStep, setAuthStep] = useState<'FORM' | 'MFA_CHALLENGE'>('FORM');
  const [verificationCode, setVerificationCode] = useState(['', '', '', '', '', '']);

  const [mfaResolver, setMfaResolver] = useState<any>(null);
  const [verificationId, setVerificationId] = useState<string>('');
  const recaptchaVerifierRef = useRef<any>(null);

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    city: 'Abidjan',
    password: '',
    confirmPassword: '',
    role: UserRole.CLIENT,
    address: '',
    idNumber: '',
    acceptTerms: false
  });

  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>([]);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [idCardRectoFile, setIdCardRectoFile] = useState<File | null>(null);
  const [idCardVersoFile, setIdCardVersoFile] = useState<File | null>(null);

  useEffect(() => {
    return () => {
      if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
      }
    };
  }, []);

  const setupRecaptcha = () => {
    if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
    }
    const container = document.getElementById('recaptcha-container');
    if (container) container.innerHTML = '';

    const verifier = new RecaptchaVerifier(auth, 'recaptcha-container', { 'size': 'invisible' });
    recaptchaVerifierRef.current = verifier;
    return verifier;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const value = e.target.type === 'checkbox' ? (e.target as HTMLInputElement).checked : e.target.value;
    setFormData({ ...formData, [e.target.name]: value });
    setError('');
  };

  const toggleService = (service: ServiceCategory) => {
    if (selectedServices.includes(service)) {
      setSelectedServices(selectedServices.filter(s => s !== service));
    } else {
      setSelectedServices([...selectedServices, service]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'AVATAR' | 'ID_RECTO' | 'ID_VERSO') => {
    const file = e.target.files?.[0];
    if (file) {
      if (type === 'AVATAR') {
          setAvatarFile(file);
          const reader = new FileReader();
          reader.onloadend = () => setAvatarPreview(reader.result as string);
          reader.readAsDataURL(file);
      } else if (type === 'ID_RECTO') setIdCardRectoFile(file);
      else if (type === 'ID_VERSO') setIdCardVersoFile(file);
    }
  };

  const handleCodeChange = (index: number, value: string) => {
      if (!/^\d*$/.test(value)) return;
      const newCode = [...verificationCode];
      newCode[index] = value.slice(-1);
      setVerificationCode(newCode);
      if (value && index < 5) document.getElementById(`code-${index + 1}`)?.focus();
  };

  const handleAuthSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');
      setLoading(true);

      const email = formData.email || `${formData.phone}@serviplus.ci`;

      try {
          if (viewMode === 'REGISTER') {
              if (!formData.acceptTerms) throw new Error("Vous devez accepter les conditions.");
              if (!avatarFile || !idCardRectoFile || !idCardVersoFile) throw new Error("Documents requis.");
              if (formData.password !== formData.confirmPassword) throw new Error("Mots de passe différents.");
              if (formData.role === UserRole.PROVIDER && selectedServices.length === 0) throw new Error("Sélectionnez au moins une compétence.");

              const userCredential = await createUserWithEmailAndPassword(auth, email, formData.password);
              const user = userCredential.user;

              const appVerifier = setupRecaptcha();
              const mfaSession = await multiFactor(user).getSession();
              const phoneOpts = { phoneNumber: `+225${formData.phone}`, session: mfaSession };
              const phoneProvider = new PhoneAuthProvider(auth);
              const vId = await phoneProvider.verifyPhoneNumber(phoneOpts, appVerifier);

              setVerificationId(vId);
              setAuthStep('MFA_CHALLENGE');
              setLoading(false);
          } else {
              try {
                  await signInWithEmailAndPassword(auth, email, formData.password);
                  const dbUser = users.find(u => u.phone === formData.phone);
                  if (dbUser) onLogin(dbUser);
                  else throw new Error("Utilisateur non trouvé dans la base de données.");
              } catch (err: any) {
                  if (err.code === 'auth/multi-factor-auth-required') {
                      const resolver = getMultiFactorResolver(auth, err);
                      setMfaResolver(resolver);
                      const appVerifier = setupRecaptcha();
                      const phoneProvider = new PhoneAuthProvider(auth);
                      const vId = await phoneProvider.verifyPhoneNumber({
                          multiFactorHint: resolver.hints[0],
                          session: resolver.session
                      }, appVerifier);
                      setVerificationId(vId);
                      setAuthStep('MFA_CHALLENGE');
                      setLoading(false);
                  } else throw err;
              }
          }
      } catch (err: any) {
          setError(err.message || "Une erreur est survenue");
          setLoading(false);
      }
  };

  const finalizeMfa = async (e: React.FormEvent) => {
      e.preventDefault();
      setLoading(true);
      const code = verificationCode.join('');

      try {
          const cred = PhoneAuthProvider.credential(verificationId, code);
          const assertion = PhoneMultiFactorGenerator.assertion(cred);

          if (viewMode === 'REGISTER') {
              await multiFactor(auth.currentUser!).enroll(assertion, "Mobile Principal");
              const avatarUrl = await uploadImage(avatarFile!, `avatars/${formData.phone}`);
              const newUser: User = {
                  id: auth.currentUser!.uid,
                  name: formData.name,
                  email: formData.email || `${formData.phone}@serviplus.ci`,
                  phone: formData.phone,
                  role: formData.role,
                  city: formData.city,
                  address: formData.address,
                  avatarUrl: avatarUrl,
                  services: formData.role === UserRole.PROVIDER ? selectedServices : undefined,
                  verified: false,
                  walletBalance: 0,
                  createdAt: new Date().toISOString()
              };
              onRegister(newUser);
          } else {
              await mfaResolver.resolveSignIn(assertion);
              const dbUser = users.find(u => u.phone === formData.phone);
              if (dbUser) onLogin(dbUser);
          }
      } catch (err: any) {
          setError("Code invalide.");
          setLoading(false);
      }
  };

  if (authStep === 'MFA_CHALLENGE') {
      return (
          <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 relative font-sans">
              <div className="absolute inset-0 bg-blue-900/70 backdrop-blur-md"></div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md relative z-10 animate-scale-in border border-white/20">
                  <div className="text-center mb-10">
                      <div className="bg-blue-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-inner">
                          <Shield className="text-blue-600" size={40} />
                      </div>
                      <h2 className="text-3xl font-black text-gray-900">Vérification</h2>
                      <p className="text-gray-500 mt-3 text-sm font-medium">Entrez le code SMS reçu.</p>
                  </div>

                  {error && <div className="bg-red-50 text-red-600 p-4 rounded-2xl mb-8 text-sm flex items-center border border-red-100 font-bold"><AlertCircle size={18} className="mr-2" />{error}</div>}

                  <form onSubmit={finalizeMfa}>
                      <div className="flex justify-between gap-2 mb-10">
                          {verificationCode.map((digit, index) => (
                              <input key={index} id={`code-${index}`} type="text" maxLength={1} value={digit} onChange={(e) => handleCodeChange(index, e.target.value)} className="w-12 h-16 text-center text-2xl font-black border-2 border-gray-100 rounded-2xl focus:border-blue-500 focus:bg-blue-50/50 outline-none transition-all shadow-sm" />
                          ))}
                      </div>
                      <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white py-5 rounded-[1.5rem] font-black text-lg shadow-xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center">
                          {loading ? <Loader2 className="animate-spin" /> : "Confirmer"}
                      </button>
                  </form>
                  <div id="recaptcha-container"></div>
              </div>
          </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900 p-4 relative overflow-hidden font-sans">
        <div className="absolute inset-0 z-0 opacity-40">
             <img src={BACKGROUND_IMAGE} alt="Bg" className="w-full h-full object-cover" />
             <div className="absolute inset-0 bg-gradient-to-b from-blue-900 via-transparent to-blue-900"></div>
        </div>

        <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-lg relative z-10 overflow-hidden animate-scale-in flex flex-col max-h-[92vh]">
            <div className="pt-10 pb-6 px-10 text-center">
                 <div className="w-20 h-20 bg-blue-600 rounded-[2rem] flex items-center justify-center text-white font-black text-3xl mx-auto mb-4 shadow-2xl shadow-blue-200 animate-float">S+</div>
                 <h1 className="text-3xl font-black text-blue-950">Servi<span className="text-orange-500">+</span></h1>
            </div>

            <div className="px-10 pb-10 overflow-y-auto custom-scrollbar flex-1">
                <div className="flex bg-gray-50 p-1.5 rounded-[1.5rem] mb-8 border border-gray-100">
                    <button onClick={() => setViewMode('LOGIN')} className={`flex-1 py-3 text-sm font-black rounded-[1rem] transition-all ${viewMode === 'LOGIN' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}>Connexion</button>
                    <button onClick={() => setViewMode('REGISTER')} className={`flex-1 py-3 text-sm font-black rounded-[1rem] transition-all ${viewMode === 'REGISTER' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}>Inscription</button>
                </div>

                {error && <div className="bg-red-50 text-red-600 p-4 rounded-2xl mb-6 text-xs font-bold border border-red-100 flex items-center animate-shake"><AlertCircle size={14} className="mr-2"/>{error}</div>}

                <form onSubmit={handleAuthSubmit} className="space-y-5">
                    {viewMode === 'REGISTER' && (
                        <>
                            <div className="grid grid-cols-2 gap-4">
                                <button type="button" onClick={() => setFormData({...formData, role: UserRole.CLIENT})} className={`p-4 rounded-2xl border-2 font-black text-xs transition-all ${formData.role === UserRole.CLIENT ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-100 text-gray-400'}`}>Je suis Client</button>
                                <button type="button" onClick={() => setFormData({...formData, role: UserRole.PROVIDER})} className={`p-4 rounded-2xl border-2 font-black text-xs transition-all ${formData.role === UserRole.PROVIDER ? 'border-orange-500 bg-orange-50 text-orange-700' : 'border-gray-100 text-gray-400'}`}>Je suis Prestataire</button>
                            </div>
                            <div className="flex flex-col items-center">
                                <div className="relative w-24 h-24 group">
                                    <div className={`w-full h-full rounded-full overflow-hidden border-4 ${avatarPreview ? 'border-blue-500' : 'border-gray-100'} bg-gray-50 flex items-center justify-center transition-all`}>
                                        {avatarPreview ? <img src={avatarPreview} alt="Av" className="w-full h-full object-cover" /> : <Camera size={32} className="text-gray-300" />}
                                    </div>
                                    <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'AVATAR')} className="absolute inset-0 opacity-0 cursor-pointer" />
                                </div>
                                <span className="text-[10px] font-black text-gray-400 mt-2 uppercase">Photo de profil</span>
                            </div>
                            <input type="text" name="name" placeholder="Nom et Prénoms" value={formData.name} onChange={handleChange} className="w-full p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold focus:bg-white focus:border-blue-500 outline-none" required />
                        </>
                    )}

                    <div className="relative">
                        <Smartphone className="absolute left-4 top-4 text-gray-300" size={20} />
                        <input type="tel" name="phone" placeholder="Numéro Mobile (ex: 07...)" value={formData.phone} onChange={handleChange} className="w-full pl-12 p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-black focus:bg-white focus:border-blue-500 outline-none" required />
                    </div>

                    {viewMode === 'REGISTER' && (
                        <>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="relative">
                                    <select name="city" value={formData.city} onChange={handleChange} className="w-full p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-black appearance-none focus:bg-white outline-none">
                                        {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
                                    </select>
                                    <ChevronDown className="absolute right-4 top-4 text-gray-400 pointer-events-none" size={20} />
                                </div>
                                <input type="text" name="address" placeholder="Quartier" value={formData.address} onChange={handleChange} className="w-full p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-black focus:bg-white outline-none" />
                            </div>

                            {formData.role === UserRole.PROVIDER && (
                                <div className="bg-orange-50/50 p-5 rounded-3xl border border-orange-100/50">
                                    <h3 className="text-[10px] font-black text-orange-600 uppercase tracking-widest mb-4 flex items-center">
                                        <LayoutGrid size={14} className="mr-2"/> Mes Compétences
                                    </h3>
                                    <div className="grid grid-cols-2 gap-2">
                                        {AVAILABLE_SERVICES.map(cat => (
                                            <button
                                                key={cat}
                                                type="button"
                                                onClick={() => toggleService(cat)}
                                                className={`p-2.5 rounded-xl text-[10px] font-black uppercase transition-all border ${selectedServices.includes(cat) ? 'bg-orange-500 text-white border-orange-600 shadow-md' : 'bg-white text-gray-400 border-gray-100 hover:bg-gray-50'}`}
                                            >
