import React, { useState } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, Transaction } from '../types';
import { SERVICE_ICONS } from '../constants';
import { MapPin, Clock, CheckCircle, Star, Phone, Navigation, User as UserIcon, Save, Wallet, DollarSign, ChevronDown, Camera, ShoppingBag, HelpCircle, Loader2, Info } from 'lucide-react';

export interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[];
  transactions: Transaction[];
  onUpdateMissionStatus: (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
  onRequestWithdrawal: (amount: number, method: string) => void;
}

export default function ProviderDashboard({ 
  currentUser, 
  missions = [], 
  users = [], 
  transactions = [], 
  onUpdateMissionStatus, 
  onDisputeMission, 
  onRateClient, 
  onUpdateUser, 
  onRequestWithdrawal 
}: ProviderDashboardProps) {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');

  const [withdrawalAmount, setWithdrawalAmount] = useState<number>(0);

  // Sécurité renforcée pour éviter les plantages lors du rendu initial
  if (!currentUser) return null;

  const userServices = currentUser.services || [];
  const userCity = currentUser.city || 'Abidjan';

  const myMissions = (missions || []).filter(m => m.providerId === currentUser.id);

  const availableMissions = (missions || []).filter(m => 
    m && m.status === MissionStatus.PENDING && 
    !m.providerId && 
    (!userCity || m.city === userCity) && 
    (userServices.length === 0 || userServices.includes(m.category))
  );

  const totalEarnings = myMissions.filter(m => m.status === MissionStatus.COMPLETED).reduce((sum, m) => sum + (m.providerAmount || 0), 0);
  const withdrawn = (transactions || []).filter(t => t.type === 'PAYOUT' && t.userId === currentUser.id && t.status === 'SUCCESS').reduce((sum, t) => sum + t.amount, 0);
  const balance = Math.max(0, totalEarnings - withdrawn);

  const handleAcceptMission = (missionId: string) => {
      if (!currentUser.id) return;
      const arrival = new Date(); 
      arrival.setMinutes(arrival.getMinutes() + 30);
      onUpdateMissionStatus(missionId, MissionStatus.ACCEPTED, currentUser.id, { arrivalTime: arrival.toISOString(), distance: 5 });
      setActiveTab('my-missions');
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Menu Navigation */}
      <div className="flex space-x-1 bg-white p-1.5 rounded-2xl shadow-sm max-w-xl mx-auto border border-gray-100">
        <button onClick={() => setActiveTab('marketplace')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'marketplace' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Missions</button>
        <button onClick={() => setActiveTab('my-missions')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'my-missions' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Travaux</button>
        <button onClick={() => setActiveTab('wallet')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'wallet' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Banque</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'profile' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:text-blue-600'}`}>Profil</button>
      </div>

      <div className="animate-slide-up">
        {activeTab === 'marketplace' && (
             <div className="space-y-4">
                 {availableMissions.length > 0 ? availableMissions.map(m => {
                     const Icon = SERVICE_ICONS[m.category] || HelpCircle;
                     return (
                        <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 hover:border-blue-200 transition-colors group">
                            <div className="flex justify-between items-start">
                                <div className="flex items-center space-x-4">
                                    <div className="p-3 bg-gray-50 rounded-2xl text-blue-600 group-hover:bg-blue-50 transition-colors"><Icon size={24} /></div>
                                    <div>
                                        <h3 className="font-black text-lg text-blue-950">{m.title || m.category}</h3>
                                        <div className="flex items-center text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">
                                            <MapPin size={10} className="mr-1 text-blue-500"/> {m.location}
                                        </div>
                                    </div>
                                </div>
                                <span className="text-green-600 font-black text-xl">{(m.providerAmount || 0).toLocaleString()} F</span>
                            </div>
                            <button onClick={() => handleAcceptMission(m.id)} className="w-full mt-6 bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-100 transition-all active:scale-95 hover:bg-blue-700">Accepter la mission</button>
                        </div>
                     );
                 }) : (
                    <div className="text-center py-20 bg-white rounded-[2.5rem] border border-dashed border-gray-200">
                        <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                            <Info size={32} className="text-gray-300" />
                        </div>
                        <p className="text-gray-400 font-black text-xs uppercase tracking-widest">Aucune mission disponible pour le moment</p>
                    </div>
                 )}
             </div>
        )}

        {activeTab === 'my-missions' && (
            <div className="space-y-4">
                {myMissions.length > 0 ? myMissions.map(m => (
                    <div key={m.id} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
                        <div className="flex justify-between items-center mb-4">
                             <div className="flex items-center space-x-3">
                                <div className="p-2 bg-blue-50 rounded-xl text-blue-600">{React.createElement(SERVICE_ICONS[m.category] || HelpCircle, {size: 18})}</div>
                                <h3 className="font-black text-blue-950">{m.title || m.category}</h3>
                             </div>
                             <span className="text-[10px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-full uppercase tracking-tighter">{m.status}</span>
                        </div>
                        <div className="space-y-2 mb-6 text-xs font-bold text-gray-400 uppercase">
                            <div className="flex items-center"><MapPin size={12} className="mr-2 text-blue-500"/> {m.location}</div>
                            <div className="flex items-center"><Clock size={12} className="mr-2 text-blue-500"/> {new Date(m.date).toLocaleString()}</div>
                        </div>
                        <div className="flex gap-2">
                             {m.status === MissionStatus.ACCEPTED && (
                                <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.IN_PROGRESS)} className="flex-1 bg-blue-600 text-white py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-blue-50">Démarrer</button>
                             )}
                             {m.status === MissionStatus.IN_PROGRESS && (
                                <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.COMPLETED)} className="flex-1 bg-green-600 text-white py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-green-50">Terminer</button>
                             )}
                             <button className="p-3 bg-gray-50 rounded-2xl text-gray-400 hover:bg-gray-100"><Phone size={18}/></button>
                        </div>
                    </div>
                )) : (
                    <div className="text-center py-20 bg-white rounded-[2.5rem] border border-dashed border-gray-200">
                        <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300"><CheckCircle size={32}/></div>
                        <p className="text-gray-400 font-black text-xs uppercase tracking-widest">Aucune mission en cours</p>
                    </div>
                )}
            </div>
        )}

        {activeTab === 'wallet' && (
            <div className="space-y-6">
                <div className="bg-blue-950 text-white p-10 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
                    <p className="text-blue-300 text-xs font-black uppercase tracking-widest opacity-60">Mon Solde</p>
                    <h2 className="text-5xl font-black mt-2 tracking-tighter">{balance.toLocaleString()} F</h2>
                    <Wallet className="absolute -right-6 -bottom-6 opacity-10 rotate-12" size={180} />
                </div>

                <div className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm">
                    <h3 className="text-xs font-black text-blue-950 uppercase tracking-widest mb-6 flex items-center">
                        <DollarSign size={16} className="mr-2 text-green-500"/> Retrait Mobile Money
                    </h3>
                    <div className="flex gap-3">
                        <input 
                            type="number" 
                            value={withdrawalAmount} 
                            onChange={(e) => setWithdrawalAmount(Number(e.target.value))}
                            className="flex-1 p-4 bg-gray-50 border border-gray-100 rounded-2xl font-black text-lg outline-none focus:bg-white focus:border-blue-500 transition-all"
                            placeholder="Montant..."
                        />
                        <button 
                            disabled={withdrawalAmount <= 0 || withdrawalAmount > balance}
                            onClick={() => { onRequestWithdrawal(withdrawalAmount, 'Mobile Money'); setWithdrawalAmount(0); }}
                            className={`px-8 py-4 rounded-2xl font-black text-sm uppercase transition-all ${withdrawalAmount > 0 && withdrawalAmount <= balance ? 'bg-green-600 text-white shadow-xl shadow-green-100 active:scale-95' : 'bg-gray-100 text-gray-300'}`}
                        >
                            Retirer
                        </button>
                    </div>
                </div>
            </div>
        )}

        {activeTab === 'profile' && (
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm text-center border border-gray-100 max-w-xl mx-auto">
                <div className="w-24 h-24 rounded-full overflow-hidden mx-auto border-4 border-blue-50 mb-6">
                    <img src={currentUser.avatarUrl} alt="Avatar" className="w-full h-full object-cover" />
                </div>
                <h2 className="text-2xl font-black text-blue-950">{currentUser.name}</h2>
                <div className="flex flex-wrap justify-center gap-2 mt-4">
                    {(currentUser.services || []).map(s => (
                        <span key={s} className="px-3 py-1 bg-gray-50 text-gray-500 text-[10px] font-black uppercase rounded-full border border-gray-100">{s}</span>
                    ))}
                </div>
                <p className="text-gray-400 text-xs font-bold uppercase mt-6 tracking-widest flex items-center justify-center">
                    <MapPin size={12} className="mr-1 text-blue-500"/> {currentUser.city || 'Abidjan'} • {currentUser.phone}
                </p>
            </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { UserRole, User, Mission, MissionStatus, ServiceCategory, Transaction } from './types';
import { BASE_RATES, COMMISSION_RATE, MOCK_USERS, MOCK_MISSIONS, MOCK_TRANSACTIONS } from './constants';
import Auth from './components/Auth';
import Layout from './components/Layout';
import ClientDashboard from './components/ClientDashboard';
import ProviderDashboard from './components/ProviderDashboard';
import AdminDashboard from './components/AdminDashboard';
import { Info } from 'lucide-react';
import { db } from './services/firebase';
// Utilisation d'imports directs et stables pour Firebase
import { 
  collection, 
  onSnapshot, 
  doc, 
  updateDoc, 
  setDoc, 
  query, 
  orderBy, 
  deleteDoc, 
  disableNetwork 
} from "firebase/firestore";

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try { 
      const saved = localStorage.getItem('serviplus_current_user'); 
      return saved ? JSON.parse(saved) : null; 
    } catch (e) { return null; }
  });

  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [missions, setMissions] = useState<Mission[]>(MOCK_MISSIONS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_TRANSACTIONS);
  const [baseRates, setBaseRates] = useState(BASE_RATES);
  const [commissionRate, setCommissionRate] = useState(COMMISSION_RATE);
  const [isOfflineMode, setIsOfflineMode] = useState(() => localStorage.getItem('serviplus_offline_mode') === 'true');

  const enableOfflineMode = async () => {
      setIsOfflineMode(true);
      localStorage.setItem('serviplus_offline_mode', 'true');
      try { await disableNetwork(db); } catch (e) {}
  };

  const retryConnection = () => {
      localStorage.removeItem('serviplus_offline_mode');
      window.location.reload();
  };

  useEffect(() => {
      if (isOfflineMode) return;

      const unsubscribeMissions = onSnapshot(query(collection(db, "missions"), orderBy("createdAt", "desc")), 
        (snap) => setMissions(snap.docs.map(d => ({ ...d.data(), id: d.id } as Mission))), 
        enableOfflineMode
      );
      const unsubscribeUsers = onSnapshot(collection(db, "users"), 
        (snap) => {
            const loadedUsers = snap.docs.map(d => ({ ...d.data(), id: d.id } as User));
            if(loadedUsers.length > 0) setUsers(loadedUsers);
        },
        enableOfflineMode
      );
      const unsubscribeTrans = onSnapshot(query(collection(db, "transactions"), orderBy("date", "desc")),
        (snap) => setTransactions(snap.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)))
      );

      return () => {
          unsubscribeMissions();
          unsubscribeUsers();
          unsubscribeTrans();
      };
  }, [isOfflineMode]);

  useEffect(() => {
      if (currentUser) {
          localStorage.setItem('serviplus_current_user', JSON.stringify(currentUser));
      } else {
          localStorage.removeItem('serviplus_current_user');
      }
  }, [currentUser]);

  // Handlers
  const handleRegister = async (newUser: User) => {
    setCurrentUser(newUser);
    setUsers(prev => [...prev, newUser]);
    if (!isOfflineMode) { try { await setDoc(doc(db, "users", newUser.id), JSON.parse(JSON.stringify(newUser))); } catch (e) {} }
  };

  const handleUpdateUser = async (updatedData: Partial<User>) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, ...updatedData };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
    if (!isOfflineMode) { try { await updateDoc(doc(db, "users", currentUser.id), updatedData); } catch (e) {} }
  };

  const handleAddMission = async (newMission: Mission, paymentMethod: string) => {
    setMissions(prev => [newMission, ...prev]);
    if (!isOfflineMode) { try { await setDoc(doc(db, "missions", newMission.id), JSON.parse(JSON.stringify(newMission))); } catch (e) {} }
  };

  const handleUpdateMissionStatus = async (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => {
      setMissions(prev => prev.map(m => (m.id === missionId ? { ...m, status, providerId, providerName: providerId ? users.find(u => u.id === providerId)?.name : m.providerName } : m)));
      if (!isOfflineMode) { try { await updateDoc(doc(db, "missions", missionId), { status, providerId }); } catch(e){} }
  };

  const handleDisputeMission = async (missionId: string, reason: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.DISPUTED, disputeReason: reason } : m));
  };

  const handleRate = async (missionId: string, rating: number, comment: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, clientRating: rating, clientComment: comment } : m));
  };

  const handleValidateMission = async (missionId: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.COMPLETED } : m));
  };

  // Admin Handlers
  const handleResolveDispute = (id: string, res: 'REFUND' | 'PAY') => {};
  const handleVerifyUser = (id: string, v: boolean) => {};
  const handleUpdateSettings = (r: any, c: number) => {};
  const handleAddAdmin = (u: User) => {};
  const handleDeleteUser = (id: string) => {};
  const handleDeleteMission = (id: string) => {};
  const handleApproveWithdrawal = (id: string) => {};
  const handleRequestWithdrawal = (amount: number, method: string) => {};

  if (!currentUser) return <Auth users={users} onLogin={setCurrentUser} onRegister={handleRegister} />;

  return (
    <Layout currentUser={currentUser} onLogout={() => setCurrentUser(null)} isOfflineMode={isOfflineMode} onRetryConnection={retryConnection}>
      {currentUser?.role === UserRole.CLIENT && (
        <ClientDashboard 
          currentUser={currentUser} 
          missions={missions} 
          onAddMission={handleAddMission} 
          onValidateMission={handleValidateMission} 
          onDisputeMission={handleDisputeMission} 
          onRateMission={handleRate} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onUpdateUser={handleUpdateUser} 
        />
      )}
      {currentUser?.role === UserRole.PROVIDER && (
        <ProviderDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDisputeMission={handleDisputeMission} 
          onRateClient={handleRate} 
          onUpdateUser={handleUpdateUser} 
          onRequestWithdrawal={handleRequestWithdrawal} 
        />
      )}
      {currentUser?.role === UserRole.ADMIN && (
        <AdminDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onResolveDispute={handleResolveDispute} 
          onVerifyUser={handleVerifyUser} 
          onUpdateSettings={handleUpdateSettings} 
          onAddAdmin={handleAddAdmin} 
          onDeleteUser={handleDeleteUser} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDeleteMission={handleDeleteMission} 
          onApproveWithdrawal={handleApproveWithdrawal} 
        />
      )}
    </Layout>
  );
};

export default App;

