import React, { useState, useEffect } from 'react';
import { UserRole, User, Mission, MissionStatus, ServiceCategory, Transaction } from './types';
import { BASE_RATES, COMMISSION_RATE, MOCK_USERS, MOCK_MISSIONS, MOCK_TRANSACTIONS } from './constants';
import Auth from './components/Auth';
import Layout from './components/Layout';
import ClientDashboard from './components/ClientDashboard';
import ProviderDashboard from './components/ProviderDashboard';
import AdminDashboard from './components/AdminDashboard';
import { Info } from 'lucide-react';
import { db } from './services/firebase';
import { 
  collection, 
  onSnapshot, 
  doc, 
  updateDoc, 
  setDoc, 
  query, 
  orderBy, 
  deleteDoc, 
  disableNetwork 
} from "firebase/firestore";

const App: React.FC = () => {
  // Chargement sécurisé de l'utilisateur
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try { 
      const saved = localStorage.getItem('serviplus_current_user'); 
      if (!saved) return null;
      const parsed = JSON.parse(saved);
      // Vérification basique de l'objet
      return (parsed && parsed.id) ? parsed : null;
    } catch (e) { 
      localStorage.removeItem('serviplus_current_user');
      return null; 
    }
  });

  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [missions, setMissions] = useState<Mission[]>(MOCK_MISSIONS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_TRANSACTIONS);
  const [baseRates] = useState(BASE_RATES);
  const [commissionRate] = useState(COMMISSION_RATE);
  const [isOfflineMode, setIsOfflineMode] = useState(() => localStorage.getItem('serviplus_offline_mode') === 'true');

  const enableOfflineMode = async () => {
      if (isOfflineMode) return;
      setIsOfflineMode(true);
      localStorage.setItem('serviplus_offline_mode', 'true');
      try { await disableNetwork(db); } catch (e) {}
  };

  const retryConnection = () => {
      localStorage.removeItem('serviplus_offline_mode');
      window.location.reload();
  };

  useEffect(() => {
      if (isOfflineMode) return;

      let unsubscribeMissions = () => {};
      let unsubscribeUsers = () => {};
      let unsubscribeTrans = () => {};

      try {
        unsubscribeMissions = onSnapshot(query(collection(db, "missions"), orderBy("createdAt", "desc")), 
          (snap) => {
            const data = snap.docs.map(d => ({ ...d.data(), id: d.id } as Mission));
            setMissions(data);
          },
          (err) => {
            console.warn("Firestore mission error, switching to demo mode", err);
            enableOfflineMode();
          }
        );

        unsubscribeUsers = onSnapshot(collection(db, "users"), 
          (snap) => {
            const loadedUsers = snap.docs.map(d => ({ ...d.data(), id: d.id } as User));
            if (loadedUsers.length > 0) setUsers(loadedUsers);
          },
          () => {}
        );

        unsubscribeTrans = onSnapshot(query(collection(db, "transactions"), orderBy("date", "desc")),
          (snap) => setTransactions(snap.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)))
        );
      } catch (e) {
        console.error("Error setting up snapshots:", e);
      }

      return () => {
          unsubscribeMissions();
          unsubscribeUsers();
          unsubscribeTrans();
      };
  }, [isOfflineMode]);

  useEffect(() => {
      if (currentUser) {
          localStorage.setItem('serviplus_current_user', JSON.stringify(currentUser));
      } else {
          localStorage.removeItem('serviplus_current_user');
      }
  }, [currentUser]);

  // Handlers
  const handleRegister = async (newUser: User) => {
    setCurrentUser(newUser);
    setUsers(prev => [...prev, newUser]);
    if (!isOfflineMode) { 
      try { 
        await setDoc(doc(db, "users", newUser.id), JSON.parse(JSON.stringify(newUser))); 
      } catch (e) { console.error(e); } 
    }
  };

  const handleUpdateUser = async (updatedData: Partial<User>) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, ...updatedData };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
    if (!isOfflineMode) { 
      try { 
        await updateDoc(doc(db, "users", currentUser.id), updatedData); 
      } catch (e) { console.error(e); } 
    }
  };

  const handleAddMission = async (newMission: Mission) => {
    setMissions(prev => [newMission, ...prev]);
    if (!isOfflineMode) { 
      try { 
        await setDoc(doc(db, "missions", newMission.id), JSON.parse(JSON.stringify(newMission))); 
      } catch (e) { console.error(e); } 
    }
  };

  const handleUpdateMissionStatus = async (missionId: string, status: MissionStatus, providerId?: string) => {
      setMissions(prev => prev.map(m => (m.id === missionId ? { 
        ...m, 
        status, 
        providerId, 
        providerName: providerId ? users.find(u => u.id === providerId)?.name : m.providerName 
      } : m)));

      if (!isOfflineMode) { 
        try { 
          const updates: any = { status };
          if (providerId) updates.providerId = providerId;
          await updateDoc(doc(db, "missions", missionId), updates); 
        } catch(e) { console.error(e); } 
      }
  };

  const handleDisputeMission = (missionId: string, reason: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.DISPUTED, disputeReason: reason } : m));
  };

  const handleRate = (missionId: string, rating: number, comment: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, clientRating: rating, clientComment: comment } : m));
  };

  const handleValidateMission = (missionId: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.COMPLETED } : m));
  };

  // Affichage conditionnel de l'interface
  if (!currentUser) {
    return <Auth users={users} onLogin={setCurrentUser} onRegister={handleRegister} />;
  }

  return (
    <Layout 
      currentUser={currentUser} 
      onLogout={() => setCurrentUser(null)} 
      isOfflineMode={isOfflineMode} 
      onRetryConnection={retryConnection}
    >
      {currentUser.role === UserRole.CLIENT && (
        <ClientDashboard 
          currentUser={currentUser} 
          missions={missions} 
          onAddMission={handleAddMission} 
          onValidateMission={handleValidateMission} 
          onDisputeMission={handleDisputeMission} 
          onRateMission={handleRate} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onUpdateUser={handleUpdateUser} 
        />
      )}
      {currentUser.role === UserRole.PROVIDER && (
        <ProviderDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDisputeMission={handleDisputeMission} 
          onRateClient={handleRate} 
          onUpdateUser={handleUpdateUser} 
          onRequestWithdrawal={() => {}} 
        />
      )}
      {currentUser.role === UserRole.ADMIN && (
        <AdminDashboard 
          currentUser={currentUser} 
          missions={missions} 
          users={users} 
          transactions={transactions} 
          baseRates={baseRates} 
          commissionRate={commissionRate} 
          onResolveDispute={() => {}} 
          onVerifyUser={() => {}} 
          onUpdateSettings={() => {}} 
          onAddAdmin={() => {}} 
          onDeleteUser={() => {}} 
          onUpdateMissionStatus={handleUpdateMissionStatus} 
          onDeleteMission={() => {}} 
          onApproveWithdrawal={() => {}} 
        />
      )}
    </Layout>
  );
};

export default App;

