  Star, 
  Phone, 
  Navigation, 
  User as UserIcon, 
  Save, 
  Wallet, 
  DollarSign, 
  ChevronDown, 
  Camera, 
  ShoppingBag, 
  HelpCircle, 
  Loader2, 
  Info,
  AlertCircle
} from 'lucide-react';

export interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[];
  transactions: Transaction[];
  onUpdateMissionStatus: (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
  onRequestWithdrawal: (amount: number, method: string) => void;
}

export default function ProviderDashboard({ 
  currentUser, 
  missions = [], 
  users = [], 
  transactions = [], 
  onUpdateMissionStatus, 
  onDisputeMission, 
  onRateClient, 
  onUpdateUser, 
  onRequestWithdrawal 
}: ProviderDashboardProps) {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');
  const [withdrawalAmount, setWithdrawalAmount] = useState<number>(0);

  // Sécurité : S'assurer que le rendu ne plante pas si currentUser est corrompu
  if (!currentUser || !currentUser.id) {
    return (
      <div className="flex flex-col items-center justify-center p-12 text-center bg-white rounded-3xl shadow-sm border border-red-100">
        <AlertCircle size={48} className="text-red-500 mb-4" />
        <h2 className="text-xl font-black text-gray-900">Erreur de Profil</h2>
        <p className="text-gray-500 mt-2">Impossible de charger vos informations de prestataire.</p>
        <button onClick={() => window.location.reload()} className="mt-6 bg-blue-600 text-white px-6 py-2 rounded-xl font-bold">Réessayer</button>
      </div>
    );
  }

  // Calculs mémoïsés pour la performance et la sécurité
  const userServices = useMemo(() => currentUser.services || [], [currentUser.services]);
  const userCity = useMemo(() => currentUser.city || 'Abidjan', [currentUser.city]);

  const myMissions = useMemo(() => 
    (missions || []).filter(m => m && m.providerId === currentUser.id),
    [missions, currentUser.id]
  );

  const availableMissions = useMemo(() => 
    (missions || []).filter(m => 
      m && 
      m.status === MissionStatus.PENDING && 
      !m.providerId && 
      (m.city === userCity) && 
      (userServices.length === 0 || userServices.includes(m.category))
    ),
    [missions, userCity, userServices]
  );

  const finances = useMemo(() => {
    const totalEarnings = myMissions
      .filter(m => m.status === MissionStatus.COMPLETED)
      .reduce((sum, m) => sum + (Number(m.providerAmount) || 0), 0);

    const withdrawn = (transactions || [])
      .filter(t => t && t.type === 'PAYOUT' && t.userId === currentUser.id && t.status === 'SUCCESS')
      .reduce((sum, t) => sum + (Number(t.amount) || 0), 0);

    return {
      balance: Math.max(0, totalEarnings - withdrawn),
      totalEarnings
    };
  }, [myMissions, transactions, currentUser.id]);

  const handleAcceptMission = (missionId: string) => {
    const arrival = new Date(); 
    arrival.setMinutes(arrival.getMinutes() + 30);
    onUpdateMissionStatus(missionId, MissionStatus.ACCEPTED, currentUser.id, { arrivalTime: arrival.toISOString(), distance: 5 });
    setActiveTab('my-missions');
  };

  return (
    <div className="space-y-6 animate-fade-in max-w-2xl mx-auto">
      {/* Navigation Mobile Optimisée */}
      <div className="flex space-x-1 bg-white p-1.5 rounded-2xl shadow-sm border border-gray-100 overflow-x-auto no-scrollbar">
        <button onClick={() => setActiveTab('marketplace')} className={`flex-1 min-w-[80px] py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'marketplace' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Missions</button>
        <button onClick={() => setActiveTab('my-missions')} className={`flex-1 min-w-[80px] py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'my-missions' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Mes Travaux</button>
        <button onClick={() => setActiveTab('wallet')} className={`flex-1 min-w-[80px] py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'wallet' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Banque</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 min-w-[80px] py-3 text-[10px] font-black uppercase rounded-xl transition-all ${activeTab === 'profile' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}>Profil</button>
      </div>

      <div className="animate-slide-up">
        {activeTab === 'marketplace' && (
             <div className="space-y-4">
                 <div className="flex items-center justify-between px-2">
                    <h2 className="text-lg font-black text-blue-950 uppercase tracking-tighter">Missions Disponibles</h2>
                    <span className="bg-blue-50 text-blue-600 px-3 py-1 rounded-full text-[10px] font-black">{availableMissions.length}</span>
                 </div>

                 {availableMissions.length > 0 ? availableMissions.map(m => {
                     const Icon = SERVICE_ICONS[m.category] || HelpCircle;
                     return (
                        <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 group transition-all active:scale-[0.98]">
                            <div className="flex justify-between items-start">
                                <div className="flex items-center space-x-4">
                                    <div className="p-3 bg-blue-50 rounded-2xl text-blue-600"><Icon size={24} /></div>
                                    <div>
                                        <h3 className="font-black text-lg text-blue-950 leading-tight">{m.title || m.category}</h3>
                                        <div className="flex items-center text-[10px] font-bold text-gray-400 uppercase mt-1">
                                            <MapPin size={10} className="mr-1 text-blue-500"/> {m.location}
                                        </div>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <span className="text-green-600 font-black text-xl">{(m.providerAmount || 0).toLocaleString()} F</span>
                                </div>
                            </div>
                            <button 
                                onClick={() => handleAcceptMission(m.id)} 
                                className="w-full mt-6 bg-blue-600 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-blue-100 active:bg-blue-700"
                            >
                                Accepter la mission
                            </button>
                        </div>
                     );
                 }) : (
                    <div className="text-center py-16 bg-white rounded-[2.5rem] border border-dashed border-gray-200 px-6">
                        <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                            <Info size={32} className="text-gray-300" />
                        </div>
                        <p className="text-gray-400 font-black text-xs uppercase tracking-widest leading-relaxed">
                            Aucune mission disponible à {userCity} pour vos compétences.
                        </p>
                    </div>
                 )}
             </div>
        )}

        {activeTab === 'my-missions' && (
            <div className="space-y-4">
                <h2 className="text-lg font-black text-blue-950 uppercase tracking-tighter px-2">Travaux en cours</h2>
                {myMissions.length > 0 ? myMissions.map(m => (
                    <div key={m.id} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
                        <div className="flex justify-between items-center mb-4">
                             <div className="flex items-center space-x-3">
                                <div className="p-2 bg-blue-50 rounded-xl text-blue-600">
                                    {React.createElement(SERVICE_ICONS[m.category] || HelpCircle, {size: 18})}
                                </div>
                                <h3 className="font-black text-blue-950">{m.title || m.category}</h3>
                             </div>
                             <span className={`text-[10px] font-black px-3 py-1 rounded-full uppercase ${
                                 m.status === MissionStatus.COMPLETED ? 'bg-green-50 text-green-600' : 'bg-blue-50 text-blue-600'
                             }`}>{m.status}</span>
                        </div>
                        <div className="space-y-2 mb-6 text-xs font-bold text-gray-400 uppercase">
                            <div className="flex items-center"><MapPin size={12} className="mr-2 text-blue-500"/> {m.location}</div>
                            <div className="flex items-center"><Clock size={12} className="mr-2 text-blue-500"/> {new Date(m.date).toLocaleString('fr-FR')}</div>
                        </div>
                        <div className="flex gap-2">
                             {m.status === MissionStatus.ACCEPTED && (
                                <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.IN_PROGRESS)} className="flex-1 bg-blue-600 text-white py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-blue-50">Démarrer</button>
                             )}
                             {m.status === MissionStatus.IN_PROGRESS && (
                                <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.COMPLETED)} className="flex-1 bg-green-600 text-white py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-green-50">Terminer</button>
                             )}
                             <a href={`tel:${users.find(u => u.id === m.clientId)?.phone}`} className="p-3 bg-gray-50 rounded-2xl text-gray-400 hover:bg-gray-100 active:scale-90 transition-all">
                                <Phone size={18}/>
                             </a>
                        </div>
                    </div>
                )) : (
                    <div className="text-center py-16 bg-white rounded-[2.5rem] border border-dashed border-gray-200">
                        <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300"><CheckCircle size={32}/></div>
                        <p className="text-gray-400 font-black text-xs uppercase tracking-widest">Vous n'avez pas de mission active</p>
                    </div>
                )}
            </div>
        )}

        {activeTab === 'wallet' && (
            <div className="space-y-6">
                <div className="bg-blue-950 text-white p-10 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
                    <p className="text-blue-300 text-[10px] font-black uppercase tracking-[0.2em] opacity-60">Solde Retirable</p>
                    <h2 className="text-5xl font-black mt-2 tracking-tighter">{finances.balance.toLocaleString()} F</h2>
                    <Wallet className="absolute -right-6 -bottom-6 opacity-10 rotate-12" size={180} />
                </div>

                <div className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm">
                    <h3 className="text-xs font-black text-blue-950 uppercase tracking-widest mb-6 flex items-center">
                        <DollarSign size={16} className="mr-2 text-green-500"/> Demander un Retrait
                    </h3>
                    <div className="space-y-4">
                        <div className="relative">
                            <input 
                                type="number" 
                                value={withdrawalAmount || ''} 
                                onChange={(e) => setWithdrawalAmount(Number(e.target.value))}
                                className="w-full p-5 bg-gray-50 border border-gray-100 rounded-2xl font-black text-2xl outline-none focus:bg-white focus:border-blue-500 transition-all pr-12"
                                placeholder="0"
                            />
                            <span className="absolute right-5 top-1/2 -translate-y-1/2 font-black text-gray-300">F</span>
                        </div>
                        <button 
                            disabled={withdrawalAmount <= 0 || withdrawalAmount > finances.balance}
                            onClick={() => { onRequestWithdrawal(withdrawalAmount, 'Mobile Money'); setWithdrawalAmount(0); }}
                            className={`w-full py-5 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${
                                withdrawalAmount > 0 && withdrawalAmount <= finances.balance 
                                ? 'bg-green-600 text-white shadow-xl shadow-green-100 active:scale-[0.98]' 
                                : 'bg-gray-100 text-gray-300 cursor-not-allowed'
                            }`}
                        >
                            Confirmer le retrait
                        </button>
                    </div>
                </div>
            </div>
        )}

        {activeTab === 'profile' && (
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm text-center border border-gray-100">
                <div className="relative w-28 h-28 mx-auto mb-6">
                    <img 
                        src={currentUser.avatarUrl || `https://ui-avatars.com/api/?name=${encodeURIComponent(currentUser.name)}&background=random`} 
                        alt="Avatar" 
                        className="w-full h-full rounded-full object-cover border-4 border-white shadow-lg" 
                    />
                    {currentUser.verified && (
                        <div className="absolute bottom-1 right-1 bg-blue-600 text-white p-1.5 rounded-full border-2 border-white">
                            <CheckCircle size={14} />
                        </div>
                    )}
                </div>
                <h2 className="text-2xl font-black text-blue-950 leading-tight">{currentUser.name}</h2>
                <p className="text-gray-400 text-[10px] font-black uppercase mt-1 tracking-widest">
                    {currentUser.role} • {currentUser.city || 'Abidjan'}
                </p>

                <div className="flex flex-wrap justify-center gap-2 mt-6">
                    {userServices.map(s => (
                        <span key={s} className="px-3 py-1.5 bg-gray-50 text-gray-500 text-[10px] font-black uppercase rounded-full border border-gray-100">
                            {s}
                        </span>
                    ))}
                    {userServices.length === 0 && <span className="text-gray-300 italic text-xs">Aucune compétence configurée</span>}
                </div>

                <div className="mt-10 pt-10 border-t border-gray-50 space-y-4">
                    <div className="flex items-center justify-between text-left p-4 bg-gray-50 rounded-2xl">
                        <div>
                            <p className="text-[10px] font-black text-gray-400 uppercase">Téléphone</p>
                            <p className="font-bold text-blue-950">{currentUser.phone}</p>
                        </div>
                        <Phone size={18} className="text-gray-300" />
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { UserRole, User, Mission, MissionStatus, ServiceCategory, Transaction } from './types';
import { BASE_RATES, COMMISSION_RATE, MOCK_USERS, MOCK_MISSIONS, MOCK_TRANSACTIONS } from './constants';
import Auth from './components/Auth';
import Layout from './components/Layout';
import ClientDashboard from './components/ClientDashboard';
import ProviderDashboard from './components/ProviderDashboard';
import AdminDashboard from './components/AdminDashboard';
import { Info, AlertCircle } from 'lucide-react';
import { db } from './services/firebase';
// Fix: Using module-level wildcard import to avoid 'no exported member' errors for Firestore
import * as firestoreModule from "firebase/firestore";
const { 
  collection, 
  onSnapshot, 
  doc, 
  updateDoc, 
  setDoc, 
  query, 
  orderBy, 
  deleteDoc, 
  disableNetwork 
} = firestoreModule as any;

const App: React.FC = () => {
  // Chargement sécurisé de l'utilisateur avec validation
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try { 
      const saved = localStorage.getItem('serviplus_current_user'); 
      if (!saved || saved === 'undefined') return null;
      const parsed = JSON.parse(saved);
      return (parsed && typeof parsed === 'object' && parsed.id) ? parsed : null;
    } catch (e) { 
      console.error("Erreur lecture localStorage:", e);
      return null; 
    }
  });

  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [missions, setMissions] = useState<Mission[]>(MOCK_MISSIONS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_TRANSACTIONS);
  const [baseRates, setBaseRates] = useState(BASE_RATES);
  const [commissionRate, setCommissionRate] = useState(COMMISSION_RATE);
  const [isOfflineMode, setIsOfflineMode] = useState(() => localStorage.getItem('serviplus_offline_mode') === 'true');

  const enableOfflineMode = useCallback(async () => {
      if (isOfflineMode) return;
      setIsOfflineMode(true);
      localStorage.setItem('serviplus_offline_mode', 'true');
      try { await disableNetwork(db); } catch (e) {}
  }, [isOfflineMode]);

  const retryConnection = () => {
      localStorage.removeItem('serviplus_offline_mode');
      window.location.reload();
  };

  useEffect(() => {
      if (isOfflineMode) return;

      let unsubMissions = () => {};
      let unsubUsers = () => {};
      let unsubTrans = () => {};

      try {
          unsubMissions = onSnapshot(query(collection(db, "missions"), orderBy("createdAt", "desc")), 
            (snap: any) => {
                if (snap && snap.docs) {
                    setMissions(snap.docs.map((d: any) => ({ ...d.data(), id: d.id } as Mission)));
                }
            }, 
            enableOfflineMode
          );

          unsubUsers = onSnapshot(collection(db, "users"), 
            (snap: any) => {
                if (snap && snap.docs) {
                    const loadedUsers = snap.docs.map((d: any) => ({ ...d.data(), id: d.id } as User));
                    if(loadedUsers.length > 0) setUsers(loadedUsers);
                }
            },
            enableOfflineMode
          );

          unsubTrans = onSnapshot(query(collection(db, "transactions"), orderBy("date", "desc")),
            (snap: any) => {
                if (snap && snap.docs) {
                    setTransactions(snap.docs.map((d: any) => ({ ...d.data(), id: d.id } as Transaction)));
                }
            }
          );
      } catch (err) {
          console.error("Erreur Firestore Snapshots:", err);
          enableOfflineMode();
      }

      return () => {
          unsubMissions();
          unsubUsers();
          unsubTrans();
      };
  }, [isOfflineMode, enableOfflineMode]);

  useEffect(() => {
      if (currentUser) {
          localStorage.setItem('serviplus_current_user', JSON.stringify(currentUser));
      } else {
          localStorage.removeItem('serviplus_current_user');
      }
  }, [currentUser]);

  // Handlers
  const handleRegister = async (newUser: User) => {
    setCurrentUser(newUser);
    setUsers(prev => [newUser, ...prev.filter(u => u.id !== newUser.id)]);
    if (!isOfflineMode) { 
        try { await setDoc(doc(db, "users", newUser.id), JSON.parse(JSON.stringify(newUser))); } catch (e) {} 
    }
  };

  const handleUpdateUser = async (updatedData: Partial<User>) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, ...updatedData };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
    if (!isOfflineMode) { 
        try { await updateDoc(doc(db, "users", currentUser.id), updatedData); } catch (e) {} 
    }
  };

  const handleAddMission = async (newMission: Mission, paymentMethod: string) => {
    setMissions(prev => [newMission, ...prev]);
    if (!isOfflineMode) { 
        try { await setDoc(doc(db, "missions", newMission.id), JSON.parse(JSON.stringify(newMission))); } catch (e) {} 
    }
  };

  const handleUpdateMissionStatus = async (missionId: string, status: MissionStatus, providerId?: string, estimation?: any) => {
      setMissions(prev => prev.map(m => (m.id === missionId ? { 
          ...m, 
          status, 
          providerId: providerId || m.providerId, 
          providerName: providerId ? (users.find(u => u.id === providerId)?.name || m.providerName) : m.providerName 
      } : m)));
      if (!isOfflineMode) { 
          try { 
              const updates: any = { status };
              if (providerId) updates.providerId = providerId;
              await updateDoc(doc(db, "missions", missionId), updates); 
          } catch(e){} 
      }
  };

  const handleDisputeMission = (missionId: string, reason: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.DISPUTED, disputeReason: reason } : m));
  };

  const handleRate = (missionId: string, rating: number, comment: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, clientRating: rating, clientComment: comment } : m));
  };

  const handleValidateMission = (missionId: string) => {
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.COMPLETED } : m));
  };

  if (!currentUser) return <Auth users={users} onLogin={setCurrentUser} onRegister={handleRegister} />;

  // Rendu conditionnel du dashboard avec protection
  let dashboardContent;
  try {
      if (currentUser.role === UserRole.CLIENT) {
        dashboardContent = (
            <ClientDashboard 
              currentUser={currentUser} 
              missions={missions} 
              onAddMission={handleAddMission} 
              onValidateMission={handleValidateMission} 
              onDisputeMission={handleDisputeMission} 
              onRateMission={handleRate} 
              baseRates={baseRates} 
              commissionRate={commissionRate} 
              onUpdateUser={handleUpdateUser} 
            />
        );
      } else if (currentUser.role === UserRole.PROVIDER) {
        dashboardContent = (
            <ProviderDashboard 
              currentUser={currentUser} 
              missions={missions} 
              users={users} 
              transactions={transactions} 
              onUpdateMissionStatus={handleUpdateMissionStatus} 
              onDisputeMission={handleDisputeMission} 
              onRateClient={handleRate} 
              onUpdateUser={handleUpdateUser} 
              onRequestWithdrawal={() => {}} 
            />
        );
      } else if (currentUser.role === UserRole.ADMIN) {
        dashboardContent = (
            <AdminDashboard 
              currentUser={currentUser} 
              missions={missions} 
              users={users} 
              transactions={transactions} 
              baseRates={baseRates} 
              commissionRate={commissionRate} 
              onResolveDispute={() => {}} 
              onVerifyUser={() => {}} 
              onUpdateSettings={() => {}} 
              onAddAdmin={() => {}} 
              onDeleteUser={() => {}} 
              onUpdateMissionStatus={handleUpdateMissionStatus} 
              onDeleteMission={() => {}} 
              onApproveWithdrawal={() => {}} 
            />
        );
      } else {
          dashboardContent = (
              <div className="p-12 text-center">
                  <AlertCircle className="mx-auto text-orange-500 mb-4" size={48} />
                  <p className="font-bold text-gray-900">Rôle inconnu. Veuillez vous reconnecter.</p>
                  <button onClick={() => setCurrentUser(null)} className="mt-4 text-blue-600 underline">Se déconnecter</button>
              </div>
          );
      }
  } catch (err) {
      console.error("Crash during dashboard render:", err);
      dashboardContent = (
          <div className="p-12 text-center bg-white rounded-3xl border border-red-100 shadow-sm">
              <AlertCircle className="mx-auto text-red-500 mb-4" size={48} />
              <h2 className="text-xl font-bold text-gray-900">Oups !</h2>
              <p className="text-gray-500 mt-2">Le tableau de bord a rencontré un problème.</p>
              <button onClick={() => window.location.reload()} className="mt-6 bg-blue-600 text-white px-6 py-2 rounded-xl font-bold">Recharger</button>
          </div>
      );
  }

  return (
    <Layout currentUser={currentUser} onLogout={() => setCurrentUser(null)} isOfflineMode={isOfflineMode} onRetryConnection={retryConnection}>
      {dashboardContent}
    </Layout>
  );
};

export default App;
